update content_bodies set title = 'Spiritual Island~SHIKOKU HENRO~', description = 'This video introduces Spiritual Island~SHIKOKU HENRO~.' where id = 'rBmuDmmmNaaq-u8WTCb2Z';
update content_bodies set title = '近鉄沿線で見つける三重の魅力', description = '三重県の伊勢志摩エリアは、日本の歴史を感じ、伝統的な料理を味わい、特別なアクティビティを楽しむのに最適な場所です。近鉄鉄道で簡単にアクセスできるこの地域では、さまざまな観光スポットがあります。アマダイバーと一緒に潜ったり、アマ小屋さとうみあんを訪れたり、かつお節の工場見学を楽しむことができます。他にも、宮古リゾートの奥志摩アクアフォレストや志摩ベイサイドテラス、伊勢神宮などの名所があります。忍者文化に興味がある方には、赤目48滝の忍者トレーニング村や伊賀流忍者博物館もおすすめです。観光をより楽しむために、観光特急「しまかぜ」に乗ることをお勧めします。' where id = 'SLLEz9iupbqdZkKvcpEbx';
update content_bodies set title = 'Find charms along Kintetsu lines in MIE', description = 'The Ise-Shima Area in Mie Prefecture is an ideal destination for experiencing Japanese history, savoring traditional cuisine, and engaging in unique activities. Easily accessible via Kintetsu Railway, this region offers a variety of attractions. Visitors can dive with Ama divers, explore the Ama Hut SATOUMIAN, and take factory tours of dried bonito. Other highlights include the Miyako Resort Okushima Aqua Forest, Miyako Resort Shima Bayside Terrace, and the famous Ise Jingu shrine. For those interested in ninja culture, the Ninja Training Village at Akame 48 Falls and the Ninja Museum of Igaryu are must-visit spots. To enhance your sightseeing experience, consider riding the Sightseeing Limited Express trains like SHIMAKAZE.' where id = 'PtefsC367VbdtQxXiMJ1n';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド  天城町編', description = '奄美群島のエコツーリズム魅力体験事業に関する内容で、徳之島の天城町に住む認定エコツアーガイドの松村さんに密着した動画が作成されました。この動画では、天城町の美しさや生物多様性が紹介されています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。この取り組みは一般社団法人徳之島観光連盟によって支援されています。' where id = 'RD4cnGmp1LlBgF1b02qeN';
update content_bodies set title = 'Eco tourism in Amagi Town Tokunoshima Island', description = 'This project showcases the eco-tourism experiences in the Amami Islands, focusing on Amagi Town in Tokunoshima Island. The video features Matsumura, a certified eco-tour guide residing in Amagi Town, highlighting the beauty and biodiversity of the area. For inquiries about tours and guides, please contact the local tourism associations of each island. The initiative is supported by the Tokunoshima Tourism Organization.' where id = 'ETcJ50rGVWwjDzZxsgc32';
update content_bodies set title = '奄美群島語り部たちのメッセージ「語り継ぐこと」', description = 'この動画では、奄美群島の語り部たちが「語り継ぐこと」の重要性についてのメッセージを紹介しています。' where id = '_3Ja8Pw65ZZd9cHB4htG_';
update content_bodies set title = 'Messages from the Storytellers of the Amami Islands: ''Passing Down Stories''', description = 'This video introduces the messages from the storytellers of the Amami Islands regarding the importance of ''passing down stories''.' where id = 'EaN162LXQ96_K3rCYHYwd';
update content_bodies set title = '奄美群島人材育成成果発表会「島サバクリエイティヴGCD（ガシド）」', description = 'このイベントは、奄美群島で様々な可能性に挑戦している方々に焦点を当てています。6名の参加者がそれぞれの島から現在の取り組みや苦労、奄美に対する想いをトークショー形式で発表します。また、「奄美群島チャレンジ商品展示販売会」も同時開催されます。日時は2024年2月3日、徳之島町生涯学習センターで、開場は15時、閉会は18時30分です。プログラムには地元の関係者からの挨拶や、様々な参加者による多様な取り組みや商品が紹介される予定です。' where id = '72ET5YV_pfaCqINbY-9qC';
update content_bodies set title = 'Amami Islands Human Resource Development Results Presentation "Island Sabacreative GCD (Gashido)"', description = 'The event focuses on individuals challenging various possibilities in the Amami Islands. Six participants from different islands will share their current projects, struggles, and feelings towards Amami in a talk show format. The event will also feature the "Amami Islands Challenge Product Exhibition and Sales" concurrently. It is scheduled for February 3, 2024, at the Tokunoshima Town Lifelong Learning Center, starting at 3:00 PM and concluding at 6:30 PM. The program includes greetings from local officials and presentations from various participants, showcasing a diverse range of initiatives and products, including local specialties and collaborations.' where id = 'CJ9N1vg0WNEU7KGYP1TJ3';
update content_bodies set title = '奄美群島人材育成成果発表会「島サバクリエイティヴGCD（ガシド）」', description = '奄美群島で挑戦している方々に焦点を当てたイベントで、各島から6名の参加者がそれぞれの取り組みや苦労、奄美に対する想いを語るトークショーが行われます。参加者のバックグラウンドが異なるため、幅広いテーマのプレゼンテーションが展開される予定です。また、同時に「奄美群島チャレンジ商品展示販売会」も開催されます。日時は令和6年2月3日（土）で、開場は15時、開演は15時30分、閉会は18時30分です。場所は徳之島町生涯学習センター2階です。' where id = 'zmUS6wWXIK96yQepdXfbN';
update content_bodies set title = 'Amami Islands Human Resource Development Results Presentation "Island Sabacreative GCD (Gashido)"', description = 'The event focuses on individuals who are taking on challenges in the Amami Islands. It features a talk show where six participants from different islands will share their current projects, struggles, and feelings about Amami. The presentations will cover a wide range of topics due to the diverse backgrounds of the speakers. Additionally, the event will coincide with the "Amami Islands Challenge Product Exhibition and Sales". The event is scheduled for February 3, 2024, starting at 3:00 PM at the Tokunoshima Town Lifelong Learning Center, with the closing at 6:30 PM.' where id = '69CmSXJNfLdSxIxqSByxo';
update content_bodies set title = '奄美群島日本復帰70周年記念式典', description = '奄美群島の日本復帰70周年記念式典が2023年11月11日（土）午後3時から奄美川商ホールで開催されます。この式典は奄美群島日本復帰70周年記念事業実行委員会が主催します。式典では、奄美高校郷土芸能部のパフォーマンスや日本復帰の歌、米軍統治下のプレゼンテーションなどの歓迎アトラクションが行われます。記念式典では、副実行委員長の開会の言葉、国歌斉唱、実行委員長や国土交通大臣、環境大臣政務官、衆議院議員、鹿児島県知事、鹿児島県議長からの祝辞が予定されています。最後には、奄美群島の語り部たちからのメッセージや万歳三唱で締めくくられます。' where id = 'C2OSSVFBJ6VbgLUm6gh9K';
update content_bodies set title = '70th Anniversary Ceremony of Amami Islands'' Return to Japan', description = 'The 70th Anniversary Ceremony of the Amami Islands'' return to Japan will be held on November 11, 2023, starting at 3 PM at the Amami Kawa Commercial Hall. The event is organized by the Executive Committee for the 70th Anniversary of the Amami Islands'' Return to Japan. The ceremony will feature welcoming attractions, including performances by the Amami High School Folk Arts Club, songs celebrating the return to Japan, and presentations on the U.S. military administration. The main ceremony will include speeches from various dignitaries, including the Vice Chair of the Executive Committee, the Minister of Land, Infrastructure, Transport and Tourism, and the Governor of Kagoshima Prefecture. The event will conclude with messages from storytellers of the Amami Islands and a celebratory chant.' where id = 'juyhwMxkEMkliHytJNVaa';
update content_bodies set title = '島サバクリエイティヴGCD in 沖永良部島', description = '「島サバクリエイティヴGCD（ガシド）」は、奄美群島において様々な可能性に挑戦している人々に焦点を当てた発表会です。参加者は、自身の取り組みや苦労、奄美に対する想いを語るトークショー形式で行われます。プログラムには、司会者や来賓の挨拶、全国高等学校総合文化祭に出場した沖永良部高校エイサー部の発表、地域の団体や企業の代表者によるプレゼンテーションが含まれています。特に、private dining 陽-haru-のオーナー後藤健太氏や一般社団法人シマスキの代表窪田貴史氏などが登壇します。また、奄美群島の地域産品や取り組みも紹介され、地域の活性化を目指しています。開催は2024年12月22日、沖永良部フローラルホテルで行われる予定です。' where id = 'NQvaTaAmIFyEqbuoMvsdS';
update content_bodies set title = 'Island Sabacreative GCD in Okinoerabu Island', description = 'The Island Sabacreative GCD (Gashido) is a presentation event focusing on individuals challenging various possibilities in the Amami Islands. The event features talks from participants sharing their current projects, struggles, and aspirations for Amami. The agenda includes greetings from hosts and guests, presentations from local high school cultural festival participants, and representatives from various organizations and businesses. Notable speakers include Kenji Goto, owner of private dining Haru, and Takashi Kubota, representative of the Shimasuki organization. The event also showcases local products and initiatives aimed at promoting the Amami Islands. Scheduled for December 22, 2024, at the Okinoerabu Floral Hotel, the event aims to connect and inspire the community.' where id = 'jtShDHDnXPKB8GLJxmAdH';
update content_bodies set title = '奄美群島周遊キャンペーン（奄美群島しまめぐり割）（自然篇）', description = '奄美群島しまめぐり割は、奄美群島が世界自然遺産に登録されたことに伴い、観光客の増加を見込んで実施されるキャンペーンです。この効果を奄美群島全体に波及させるため、旅行会社が販売する奄美群島への旅行商品に対して割引助成が行われます。また、旅行者には各島で利用できる電子クーポンが付与されます。割引額はお一人様一泊あたり最大5,000円で、宿泊者には2,000円分の旅クーポンも付いてきます。対象期間は令和5年7月1日から令和6年2月1日までです。お問い合わせは奄美群島しまめぐり割事務局（TEL：0570-000-255）まで、営業時間は平日・土日祝の10：00～17：00です。' where id = '_3tEqBxqiIT7CHKBjnKja';
update content_bodies set title = 'Amami Islands Tour Campaign (Amami Islands Island Tour Discount) - Nature Edition', description = 'The Amami Islands Island Tour Discount aims to promote tourism following the registration of the Amami Islands as a UNESCO World Natural Heritage site. To enhance the impact of this recognition, travel companies will offer discounts on travel packages to the Amami Islands. Additionally, travelers will receive electronic coupons usable on each island. The discount is up to 5,000 yen per person per night, along with a 2,000 yen travel coupon for overnight guests. The campaign runs from July 1, 2023, to February 1, 2024. For inquiries, contact the Amami Islands Island Tour Discount Office at 0570-000-255, available from 10:00 AM to 5:00 PM on weekdays and weekends, excluding the New Year holidays.' where id = 'm-bvEzoLF5H-h7SXhrDGA';
update content_bodies set title = '島サバクリエイティブ GCD(ガシド)トークショー＆奄美群島民間チャレンジ支援事業「見本市」2023年2月5日(日)', description = 'この動画では、島サバクリエイティブ GCD(ガシド)トークショーと奄美群島民間チャレンジ支援事業「見本市」について紹介しています。イベントは2023年2月5日に開催され、地域のクリエイティブな取り組みや支援事業の内容が取り上げられています。' where id = 't4P4DyCJZHrq1ccwLiSO-';
update content_bodies set title = 'Island Saba Creative GCD Talk Show & Amami Islands Private Challenge Support Project ''Exhibition'' February 5, 2023', description = 'This video introduces the Island Saba Creative GCD Talk Show and the Amami Islands Private Challenge Support Project ''Exhibition''.' where id = 'ZUxd_VQ7D4Pe14p0m77zO';
update content_bodies set title = '奄美大島', description = '奄美大島は鹿児島市から南へ約380キロメートルに位置し、周囲約461キロメートルの島です。日本で2番目に広いマングローブ林や、絶滅が危惧されるアマミノクロウサギなどの固有種を有し、自然の多様性と稀少性が際立っています。また、島唄や八月踊りなどの伝統文化や、奄美大島紬などの伝統産業もあり、古くから島人たちに大切にされてきた風景や情景が楽しめます。東京や大阪、福岡などの主要空港からアクセス可能で、奄美大島からは飛行機やフェリーを利用して奄美群島への移動もできます。' where id = '_wE3MbrrctHXy8L_PuUUR';
update content_bodies set title = 'Amami Island, Japan in 8K', description = 'Amami Island is located approximately 380 kilometers south of Kagoshima City, with a circumference of about 461 kilometers. The island boasts a rich natural environment, featuring Japan''s second-largest mangrove forest and endemic species like the endangered Amami rabbit. It is also home to traditional culture, including island songs and August dances, as well as traditional industries such as Amami Oshima textiles, which have been cherished by the island''s inhabitants for generations. The island is accessible from major airports in Tokyo, Osaka, and Fukuoka, and offers connections to the Amami Islands via flights and ferries.' where id = 'usqowENsP2ArOu50vOEnS';
update content_bodies set title = '見栄サミット第2弾（リモート会議ver） 一話「体験、それはロマン／伊勢志摩」 #三重の観光PR動画', description = '三重県の5つのエリアを国に見立てた「見栄サミット」がリモート会議として帰ってきました。第一話は「体験、それはロマン／伊勢志摩」で、伊勢志摩の魅力をテーマにリモート会議で語ります。伊勢志摩の首脳が自作の映像を通じて、伊勢シーパラダイスやフォレストアドベンチャー、忍者体験などの体験スポットを紹介し、地域の魅力をアピールします。このエピソードは、伊勢志摩のユニークな体験を強調し、視聴者に地域を訪れることを促しています。' where id = '2Gl9C5hoKUwPyyVaiPhfI';
update content_bodies set title = 'Mie Summit Vol. 2 (Remote Meeting Version) Episode 1: ''Experience, That is Romance / Ise-Shima'' #Mie Tourism PR Video', description = 'The second installment of the ''Mie Summit'' returns as a remote meeting, where leaders from five areas of Mie Prefecture, each imagined as a different country, gather to boast about their regions. Episode 1 focuses on ''Experience, That is Romance / Ise-Shima,'' highlighting the attractions of Ise-Shima through a remote conference format. The leaders showcase self-made videos in a TV program style, presenting various experiential spots in Ise-Shima, including Ise Sea Paradise, Forest Adventure, ninja experiences, and more. The episode emphasizes the unique experiences available in Ise-Shima, encouraging viewers to explore the region''s charm.' where id = 'dVhpvmg2SbVEXFrSMc7Oc';
update content_bodies set title = '沖永良部島', description = '沖永良部島は、鹿児島市から南へ約552kmの位置にある周囲約55.8kmの隆起サンゴ礁の島です。年間平均気温は23度で、温暖な気候に恵まれ、四季を通じて熱帯や亜熱帯の花々が咲き誇ります。特にエラブユリやスプレーキクの栽培が盛んです。また、地下には多くの鍾乳洞が存在し、「花と鍾乳洞の島」として知られています。澄んだ青い海と空、まばゆい太陽、そして素朴で温かい人情が、訪れる人々に忘れられない旅の思い出を提供します。' where id = 'uFt-ilsExsD_QrFhq-eoS';
update content_bodies set title = 'Okinoerabu Island, Japan in 8K', description = 'Okinoerabu Island is located approximately 552 km south of Kagoshima City and is a raised coral reef island with a circumference of about 55.8 km. The island enjoys a warm climate with an average annual temperature of 23 degrees Celsius, allowing tropical and subtropical flowers to bloom throughout the year, including the Erabu lily and spray chrysanthemum. It is known as the ''Island of Flowers and Caves'' due to the numerous limestone caves beneath its surface. The clear blue sea and sky, dazzling sun, and warm-hearted locals create unforgettable travel memories.' where id = 'qZGYS3ON0Iw9LaZomIO7k';
update content_bodies set title = '与論島', description = '与論島は奄美群島の最南端に位置し、沖縄本島から約23kmの距離にある周囲約23.8kmの島です。サンゴ礁が隆起してできたこの島は、白い砂浜と透明度の高い海を持ち、「東洋の真珠」と称されています。特に「百合ヶ浜」は、特定の条件下でのみ現れる美しいビーチで、エメラルドグリーンに輝く海と白い砂浜が訪れる人々を魅了します。また、沖縄県との深い関係があり、薩摩と琉球の文化が融合した独自の文化を楽しむことができます。' where id = 'IjoOckTdkUlv-jtXaGKS_';
update content_bodies set title = 'Yoron Island, Japan in 8K', description = 'Yoron Island is located at the southernmost tip of the Amami Islands, approximately 23 km from Okinawa. The island, which has a circumference of about 23.8 km, was formed by raised coral reefs and is often referred to as the ''Pearl of the Orient'' due to its white sandy beaches and crystal-clear waters. One of its highlights is ''Yurigahama,'' a beach that only appears under specific conditions, shining in emerald green and captivating visitors with its stunning scenery. The island has a deep connection with Okinawa, offering a unique culture that blends elements of Satsuma and Ryukyu.' where id = '53-mnOdKNMEtggh0wW1Qr';
update content_bodies set title = '徳之島 Tokuno Island, Japan in 8K', description = '徳之島は鹿児島市から南へ約468kmの位置にあり、周囲約89kmの島です。主要な産業はサトウキビやジャガイモ、果樹などの農業、近海漁業、黒糖を原料とした菓子や黒糖焼酎の製造です。また、闘牛が盛んな島としても知られ、年に数回大きな大会が開催されます。奄美群島で2番目に大きな島であり、豊かな自然と素朴な南の島の文化を楽しむことができます。' where id = 'Cy1XN4jXiHWBugit7loJv';
update content_bodies set title = 'Tokuno Island, Japan in 8K', description = 'Tokuno Island is located approximately 468 km south of Kagoshima City, with a circumference of about 89 km. The main industries include agriculture, such as sugarcane, potatoes, and fruit, as well as nearshore fishing, and the production of sweets and shochu made from brown sugar. The island is also famous for its bullfighting, hosting large tournaments several times a year. It is the second largest island in the Amami Islands, offering rich nature and the simple culture of a southern island.' where id = 'brMjupGVtblCBbbR9DKi2';
update content_bodies set title = '喜界島 Kikai Island, Japan in 8K', description = '喜界島は奄美大島の東に位置し、周囲約48.7kmの島です。島の大部分は隆起したサンゴ礁で構成され、年間数ミリずつ隆起し続けています。主な産業は農業で、島全体に広がるサトウキビ畑からは黒糖や黒糖焼酎が生産され、特産品となっています。また、喜界島は国内最大のゴマの産地としても知られています。島内ではオオゴマダラやアサギマダラなどの蝶が見られ、近年ではダイビングスポットとしても注目されています。' where id = 'Qn4PrmSWgs8I__bvImmUc';
update content_bodies set title = 'Kikai Island, Japan in 8K', description = 'Kikai Island is located east of Amami Oshima and has a circumference of approximately 48.7 km. The island is primarily composed of uplifted coral reefs that continue to rise a few millimeters each year. Agriculture is the main industry, with sugarcane fields covering the island, producing local specialties such as brown sugar and brown sugar shochu. Kikai is also known as the largest sesame production area in Japan. The island is home to various butterflies, including the Oogomadara and Asagimadara, and has recently gained attention as a diving spot.' where id = 'aap_Z_Lwg4B-aHq5yLENh';
update content_bodies set title = '奄美群島認定エコツアーガイド 与論町編', description = 'この動画では、与論島に住む認定エコツアーガイドの池田さんに密着し、エコツーリズムの魅力を紹介しています。動画は無声で再生可能で、日本語字幕が付いています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。与論島観光協会のウェブサイトは http://www.yorontou.info/ です。内容は、生物多様性や国立公園、海岸清掃などのエコ活動の重要性を強調しています。' where id = 'RmcOP5u01SweVLwuWGl4U';
update content_bodies set title = 'Eco tourism in Yoron Town Yoronima Island (Japanese subtitles included)', description = 'This video features a certified eco-tour guide, Mr. Ikeda, who lives on Yoron Island, showcasing eco-tourism experiences. The video is designed to be played silently with Japanese subtitles. For inquiries about tours and guides, please contact the tourism association of each island. The Yoron Tourism Association is available at http://www.yorontou.info/. The content highlights the importance of biodiversity, national parks, and eco-friendly activities such as coast cleaning and nature experiences.' where id = 'xA0d2avu0v3eaQEJGHCI7';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド 徳之島町編 - Eco tourism in Tokunoshima Town Tokunoshima Island (日本語字幕付き)', description = 'この動画は、徳之島町に住む認定エコツアーガイドの元田さんに密着した内容です。奄美広域事務組合が実施する奄美群島エコツーリズム魅力体験事業の一環として制作されました。動画では、徳之島の自然の美しさや生物多様性を紹介し、エコツアーの魅力を伝えています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。徳之島観光連盟のウェブサイトも参考にしてください。' where id = '9M2I5Gv3p3LIAZNUqE2qj';
update content_bodies set title = 'Eco tourism in Tokunoshima Town Tokunoshima Island (with Japanese subtitles)', description = 'This video features a certified eco-tour guide, Mr. Motoda, who resides in Tokunoshima Town. It is part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video showcases eco-tours and provides insights into the natural beauty and biodiversity of Tokunoshima. For inquiries about tours and guides, please contact the local tourism association. The Tokunoshima Tourism Organization''s website is available for more information.' where id = '3U8FYijNCQUhaj5MEXT7e';
update content_bodies set title = '【喜界島】奄美群島認定エコツアーガイド 喜界町編', description = 'この動画は、喜界島の喜界町に住む認定エコツアーガイドの武田さんに密着した内容です。奄美広域事務組合による奄美群島エコツーリズム魅力体験事業の一環として制作されました。動画は無声で再生可能で、日本語字幕が付いています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。詳細は喜界島総合情報サイト「喜界島ナビ」をご覧ください。' where id = 'URwUqh_s2LY-sFkIOzrGH';
update content_bodies set title = 'Eco tourism in Kikai Town Kikaijima Island (with Japanese subtitles)', description = 'This video features a certified eco-tour guide, Mr. Takeda, who lives in Kikai Town on Kikaijima Island. It is part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video can be played silently with Japanese subtitles. For inquiries about tours and guides, please contact the tourism association of each island. The Kikaijima Tourism Association website is provided for more information.' where id = 'ubyejPHfCuthgLYeqrU8p';
update content_bodies set title = '【奄美大島】奄美群島認定エコツアーガイド 奄美市編', description = 'この動画では、奄美市に住む認定エコツアーガイドの興さんに密着し、奄美群島のエコツーリズム体験を紹介しています。動画は無声で再生可能で、日本語字幕が付いています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。このプロジェクトは、奄美広域事務組合のエコツーリズム推進事業の一環です。' where id = 'Qm-ylkart_car9V8fu1Tj';
update content_bodies set title = 'Eco tourism in Amami City Amami Oshima Island (with Japanese subtitles)', description = 'This video features a certified eco-tour guide, Mr. Hiroshi, who lives in Amami City, showcasing eco-tourism experiences in the Amami Islands. The video is designed to be played silently with Japanese subtitles. For inquiries about tours and guides, please contact the tourism associations of each island. The project is part of the Amami Regional Office''s initiative to promote eco-tourism in the area.' where id = 'ImI8GRzoFjEu97OJXvWBR';
update content_bodies set title = '【沖永良部島】奄美群島エコツアー ケイビング', description = 'この動画は、奄美群島の沖永良部島に焦点を当てたオンラインエコツアーを紹介しています。奄美群島に住む認定エコツアーガイドに密着し、彼らの体験を通じて地域の魅力を伝えています。ガイドの小林さんが鍾乳洞を案内し、自然の美しさや生物多様性についての知識を共有します。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。動画は無声で、日本語字幕付きで再生可能です。' where id = '6W1KA2oaWY3eg_DlzkSSu';
update content_bodies set title = 'Eco tourism in Okinoerabujima Island (Japanese subtitles available)', description = 'This video features an online eco-tour in the Amami Islands, focusing on Okinoerabujima Island. It highlights the experiences of certified eco-tour guides living on the five islands of the Amami archipelago. The tour is led by guide Kobayashi, who provides insights into the limestone caves of the region. For inquiries about the guide and tours, please contact the tourism associations of each island. The video is silent and can be played with Japanese subtitles.' where id = 'iwLAGhQ6Mf_mf8nnb9-Se';
update content_bodies set title = '【喜界島】奄美群島エコツアー 黒糖焼酎の酒造ツアー', description = '奄美群島エコツーリズム魅力体験事業の一環として、喜界島に焦点を当てたオンラインエコツアーが開催されました。認定エコツアーガイドの外内さんが黒糖焼酎の酒造見学を案内し、喜界島の自然の美しさを紹介します。ガイドやツアーに関する問い合わせは、各島の観光協会にお願いします。動画は日本語字幕付きで、無声でも再生可能です。' where id = 'XKv5Qf0dAI1hYRVQdHB3b';
update content_bodies set title = 'Eco tourism in Kikaijima Island (with Japanese subtitles)', description = 'This video features an online eco-tour hosted by the Amami Islands Eco-Tourism Experience Project, focusing on Kikaijima Island. It follows certified eco-tour guide, Mr. Soto, as he provides a tour of a brown sugar shochu distillery and showcases the natural beauty of Kikaijima. For inquiries about the guide and tours, please contact the tourism associations of each island. The video is available with Japanese subtitles and can be played without sound.' where id = 'Px_97pQUDkMlMXFtiI3D-';
update content_bodies set title = '奄美群島 地域通訳案内士', description = '奄美群島地域通訳案内士とは、奄美群島を訪れる外国人観光客に対して、外国語を用いて旅行に関する案内を行う専門家です。彼らは特定の地域における歴史、地理、文化に関する深い知識を持ち、観光客に対して適切で洞察に富んだガイドを提供することができます。この資格は、奄美群島広域事務組合が実施する研修プログラムを通じて取得され、正確な情報を提供できることが保証されています。' where id = 'xrCOZ-JlD79IE_o_BXzv5';
update content_bodies set title = 'Amami Islands Area Licensed Guide Interpreters', description = 'An Amami Islands Area Licensed Guide Interpreter is a professional who assists foreign tourists visiting the Amami Islands by providing travel-related information in foreign languages. These interpreters possess in-depth knowledge of the local history, geography, and culture, making them well-equipped to guide visitors. They obtain their certification through a training program conducted by the Wide Area Administration Association of Amami Islands, ensuring they are qualified to offer accurate and insightful guidance.' where id = 'cxiRnfq2tbGhaFcKOMjTP';
update content_bodies set title = '奄美群島国立公園エコツアーガイド5島12市町村', description = 'このプロジェクトは、奄美群島国立公園に住む認定エコツアーガイドと地域通訳案内士に焦点を当てています。既存のオンラインエコツアー動画をまとめ、視聴者がガイドの自然に対する思いや生き様に触れることを目的としています。ガイドやツアーに関する問い合わせは、各島の観光協会にお願いします。プロジェクトには、奄美大島のハイキング、喜界島の黒糖焼酎の酒造ツアー、沖永良部島のケイビングなど、ユニークな体験を紹介するエコツーリズム動画へのリンクが含まれています。この取り組みは、地域のエコツーリズムと生物多様性を促進し、異文化交流や自然体験を奨励します。' where id = 'c7iaOO9BLQz53ZUjH3-_M';
update content_bodies set title = 'Amami Islands National Park Ecotour Guides: 5 Islands and 12 Municipalities', description = 'This project focuses on certified ecotour guides and local interpreters living in the five islands of the Amami Islands National Park. It compiles existing online ecotour videos, aiming to connect viewers with the guides'' thoughts and lifestyles regarding nature. For inquiries about guides and tours, please contact the tourism associations of each island. The project includes links to various ecotourism videos showcasing unique experiences such as hiking in Amami Oshima, a black sugar distillery tour in Kikaijima, and caving in Okinoerabujima, among others. The initiative promotes ecotourism and biodiversity in the region, encouraging cultural exchange and nature experiences.' where id = 'nig9clr1EfMY0JLuOcFkz';
update content_bodies set title = '奄美群島の国立公園（5つの島：1市/9町/2村）とエコツアーガイド', description = '奄美群島では、認定エコツアーガイドとライセンスを持つ通訳者による17本のエコツアービデオが公開されています。これらのビデオは、奄美大島、喜界島、徳之島、沖永良部島、与論島の国立公園の魅力を紹介しています。神秘的な巨木や黒糖焼酎の蒸留所、石灰岩の洞窟、クジラウォッチングなど、各島のユニークな観光名所が取り上げられています。エコツアーやガイドに関する詳細は、各島の観光協会を確認することができます。奄美群島は生物多様性と自然遺産で知られ、エコツーリズムの目的地として最適です。' where id = 'YeXNypenkJU5YNKOUGCVA';
update content_bodies set title = 'National Parks on The Islands of Amami (5 Islands: 1City/9Towns/2Villages) with Ecotour Guides', description = 'The Amami Islands offer a collection of 17 ecotour videos featuring certified ecotour guides and licensed interpreters. These videos showcase the national parks across the five islands: Amami Oshima, Kikaijima, Tokunoshima, Okinoerabu, and Yoronjima. Each video highlights unique attractions such as mystical giant trees, a brown sugar shochu distillery, limestone caves, and whale watching. For more information on eco-tours and guides, visitors can check the respective tourism associations for each island. The Amami Islands are recognized for their biodiversity and natural heritage, making them a prime destination for ecotourism.' where id = 'tbMQ2UwaNKH-5sZ-hlte6';
update content_bodies set title = '島サバクリエイティブ GCD(ガシド)オンライントークショー＆奄美群島民間チャレンジ支援事業「見本市」2022年3月13日(日)15:00 配信スタート！', description = '奄美群島における島のサバクリゴトの可能性に挑戦するユムターたちの本音を聞くトークイベントが開催されます。主催者の奄美群島広域事務組合の美里洋秋氏の挨拶から始まり、徳之島の福本慶太氏や与論島の栁田真希氏など、各島からの登壇者が参加します。また、沖永良部島の合同会社TSUMUGUや奄美大島のフランス料理レストランPousserなど、オンライン見本市に出店する業者も紹介されます。このイベントは、奄美群島の独自のクリエイティブな取り組みや地域ビジネスを強調することを目的としています。' where id = 'gO7Q-b_FleDVvk4ikdU1D';
update content_bodies set title = 'Island Sabacreative GCD Online Talk Show & Amami Islands Private Challenge Support Project ''Exhibition'' Starting March 13, 2022, at 15:00!', description = 'This online talk event features candid discussions from local creators (Yumuta) who are exploring the potential of island sabacreative activities in the Amami Islands. The event includes greetings from the organizer, Masato Yoshiaki from the Amami Islands Regional Office, and features various speakers from different islands, including Keita Fukumoto from Tokunoshima, Maki Yanagida from Yoron Island, and others. The event also showcases online exhibitors such as Tsumugu, a company developing new processed products using the blessings of Okinoshima, and Pousser, a French restaurant in Amami Oshima. The talk show aims to highlight the unique creative endeavors and local businesses in the Amami Islands.' where id = 'rNG-cWvqfD-QPEpfPr4Zr';
update content_bodies set title = '島根県の美しい風景ダイジェスト動画', description = 'この5分間の動画では、島根県の美しく懐かしい風景を4K HDで紹介しています。島根の豊かな歴史と文化を強調し、視聴者に日本のオリジナルな風景の真実性と魅力を体験するよう促しています。' where id = 'AY5zZxLZzYOBiFfj8tmTd';
update content_bodies set title = 'Shimane Prefecture''s Beautiful Scenery Digest Video', description = 'This 5-minute video showcases the beautiful and nostalgic landscapes of Shimane Prefecture in stunning 4K HD. It highlights the region''s rich history and culture, inviting viewers to experience the authenticity and charm of Japan''s original scenery.' where id = '4t_J7z_dUz5gJKdxftGVU';
update content_bodies set title = '奄美郡岛认证生态导游 加计吕麻岛 濑户内町', description = '奄美群岛総合管理協会は、奄美群島におけるエコツーリズム体験事業に取り組んでいます。加計吕麻島の濑戸内町に住む奄美郡島認定エコツアーガイドの寺本さんにインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。詳細は、一般社団法人あまみ大島観光物産連盟のウェブサイトをご覧ください。' where id = 'PYnzEUHFdlQ_k_qAFidC6';
update content_bodies set title = 'Eco tourism in Setouchi Town (Kakeromajima) Amami Oshima Island', description = 'The Amami Islands Comprehensive Management Association is involved in eco-tourism experiences in the Amami Islands. We interviewed Ms. Teramoto, a certified eco-tour guide living in Setouchi Town on Kakeromajima, and conducted an online tour. For inquiries about guides and tourism, please contact the tourism associations of each island. More information can be found at the Amami Tourism & Products Federation''s website.' where id = 'ZVXCjEDxSfWucCmvQIiHU';
update content_bodies set title = '西日本屈指の紅葉名所 奥津渓プレミアムウォーク（鏡野町）', description = '岡山県で話題の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや予約、申込みの情報が掲載されています。岡山観光に関する動画もあり、観光情報を得るのに最適なサイトです。' where id = '434gIUq__pb8OFeSIvbrp';
update content_bodies set title = 'Okutsu Valley Premium Walk - A Top Autumn Foliage Spot in Western Japan (Kagamino Town)', description = 'Discover the latest experiences and tours in Okayama Prefecture! This site offers immersive experience reports along with options for reservations and applications.' where id = '3ONiRfTLhEtN-_ESBaLoy';
update content_bodies set title = '【与論島】奄美群島認定エコツアーガイド 与論町編', description = 'このプロジェクトは、奄美群島の一部である与論町におけるエコツーリズム体験を紹介しています。与論島に住む認定エコツアーガイドの池田さんが登場し、地域の美しさや生態的重要性を伝える動画が作成されました。ツアーやガイドに関する問い合わせは、各島の観光協会にご連絡ください。一般社団法人ヨロン島観光協会は、訪問者が島の自然遺産を探求するためのリソースや情報を提供しています。' where id = 'E9SOzNsX6LRfoEJdNMqZM';
update content_bodies set title = 'Eco tourism in Yoron Town Yoronima Island', description = 'This project highlights the eco-tourism experiences in Yoron Town, part of the Amami Islands. The video features Ikeda, a certified eco-tour guide residing on Yoron Island, showcasing the beauty and ecological significance of the area. For inquiries about tours and guides, please contact the local tourism association. The Yoron Tourism Association provides resources and information for visitors interested in exploring the island''s natural heritage.' where id = '7GUjxBGdMPl5XIjGOZxLX';
update content_bodies set title = '奄美群島エコツアーガイド 知名町編', description = 'このプロジェクトは、奄美群島の沖永良部島知名町におけるエコツーリズム体験を紹介しています。地域通訳案内士の有川さんが登場し、地域の自然の美しさや生物多様性についての洞察を提供する動画が作成されました。ツアーやガイドに関する問い合わせは、各島の観光協会に連絡することが推奨されています。この取り組みは、世界自然遺産として認識されている地域の独自の文化と自然遺産を促進することを目的としています。' where id = 'ek5Twwk9ioRbhsNJ73Vka';
update content_bodies set title = 'Eco tourism in China Town Okinoerabujima Island', description = 'This project highlights eco-tourism experiences in the Amami Islands, focusing on Okinoerabu Island''s China Town. The video features a local interpreter guide, Mr. Arikawa, who provides insights into the region''s natural beauty and biodiversity. For inquiries about tours and guides, visitors are encouraged to contact the local tourism association. The initiative aims to promote the unique cultural and natural heritage of the area, which is recognized as a World Natural Heritage site.' where id = 'yB9YurglTkeIl4-COiIUp';
update content_bodies set title = '【沖永良部島】奄美群島エコツアーガイド 和泊町編', description = 'このプロジェクトは、奄美群島のエコツーリズムを紹介し、沖永良部島の和泊町に焦点を当てています。地域通訳案内士の吉成さんが登場し、地域のユニークな体験を紹介するエコツアー動画を作成しました。ツアーやガイドに関する問い合わせは、各島の観光協会にご連絡ください。この取り組みは、奄美広域事務組合が地域の自然遺産や生物多様性を促進するための一環です。' where id = 'HXhYepAeUNPZ9qMtolz1k';
update content_bodies set title = 'Eco tourism in Okinoerabujima Wadomari Town', description = 'This project highlights eco-tourism in the Amami Islands, focusing on Wadomari Town in Okinoerabujima. The video features Yoshinari, a local interpreter guide, showcasing the unique experiences available in the area. For inquiries about tours and guides, please contact the local tourism association. The initiative is part of the Amami Regional Office''s efforts to promote the natural heritage and biodiversity of the region.' where id = 'Wf7VUElyswvsfd_ewl38M';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド 伊仙町編', description = 'このプロジェクトは、奄美群島のエコツーリズム体験を紹介し、徳之島の伊仙町に焦点を当てています。徳之島町に住む認定エコツアーガイドの関さんが、エコツアーを紹介する動画に登場します。ガイドやツアーに関する問い合わせは、各島の観光協会にご連絡ください。' where id = 'FVwbeHFGmbOzTpUcks52s';
update content_bodies set title = 'Eco tourism in Isen Town Tokunoshima Island', description = 'This project highlights the eco-tourism experiences in the Amami Islands, focusing on Isen Town in Tokunoshima. A certified eco-tour guide, Mr. Seki, who resides in Tokunoshima Town, is featured in a video showcasing eco-tours. For inquiries about the guide and tours, please contact the local tourism associations of each island.' where id = '_zsHcg1q58OaHVCJ9tfPq';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド 徳之島町編', description = 'このプロジェクトは、奄美群島の一部である徳之島町におけるエコツーリズム体験に焦点を当てています。徳之島に住む認定エコツアーガイドの元田さんを特集し、エコツアーの魅力を伝える動画が作成されました。この地域の自然の美しさや生物多様性を強調しています。ガイドやツアーに関する問い合わせは、各島の観光協会にご連絡ください。徳之島観光連盟は、地域の自然遺産とエコツーリズムの推進に努めています。' where id = 'HFBpqEOBEzcRRnfGJ7BtP';
update content_bodies set title = 'Eco tourism in Tokunoshima Town Tokunoshima Island', description = 'This project focuses on the eco-tourism experience in Tokunoshima Town, part of the Amami Islands. It features a certified eco-tour guide, Mr. Motoda, who resides in Tokunoshima. A video showcasing the eco-tour has been created to highlight the natural beauty and biodiversity of the area. For inquiries about the guide and tours, please contact the local tourism association. The Tokunoshima Tourism Organization is dedicated to promoting the region''s natural heritage and eco-friendly tourism.' where id = 'icQ6ELlJ8EPV97v6sEt3u';
update content_bodies set title = '伊勢角屋麦酒「地ビール」(伊勢市) ｜観光三重｜三重県の観光・旅行', description = '伊勢角屋麦酒は、世界中のビールコンペティションで金賞を受賞している実績を持つ醸造所です。伊勢神宮の近くで造られる香り高くクリアなクラフトビールは、多くの人々に愛されています。この記事では、日本のクラフトビール界を盛り上げる伊勢角屋麦酒の魅力を紹介しています。' where id = 'BMoYTBF_UOifSu9-vMVS6';
update content_bodies set title = 'Ise Kakuya Brewery ''Craft Beer'' (Ise City) | Tourism Mie | Mie Prefecture Tourism and Travel', description = 'Ise Kakuya Brewery is a regular winner of gold medals at beer competitions worldwide. They produce aromatic and clear craft beer at the foot of Ise Jingu Shrine. This report introduces Ise Kakuya Brewery, which is invigorating the craft beer scene in Japan.' where id = 'uu671mA2MTy13rdTghFRG';
update content_bodies set title = 'ばんこの里会館　(四日市市)｜観光三重｜三重県の観光・旅行情報', description = 'ばんこの里会館は、三重県の伝統的なやきものである萬古焼（ばんこやき）を見て、知り、作り、楽しむことができる施設です。2階には、地域ならではの品揃えと価格が自慢のショップ「うつわ亭」があり、土鍋や急須などの特別な一品が見つかるかもしれません。' where id = '6C2wS6yQJSzBSa3FDyA39';
update content_bodies set title = 'Banko no Sato Kaikan (Yokkaichi City) | Tourism Mie | Mie Prefecture Travel Information', description = 'The Banko no Sato Kaikan is a facility where visitors can see, learn about, create, and enjoy traditional Banko pottery from Mie Prefecture. On the second floor, there is a shop called ''Utsuwa-tei'' that boasts a selection and pricing unique to the region, where you might find special items like earthenware pots and teapots.' where id = 'ja2eaiMzuas1e2Lya3Tg3';
update content_bodies set title = '庄分酢＠福岡県大川市【福岡県観光紹介ショートムービー】', description = '大川市に位置する庄分酢は、300年の歴史を持つ酢造りの名店で、静置発酵によるこだわりのお酢を製造・販売しています。庄分酢の本社にはショップとレストランが併設されており、酢蔵の見学も可能です。' where id = 'n_HBMseu-gJ6Ew9Kq9Bfv';
update content_bodies set title = 'Shobun Vinegar in Okawa City, Fukuoka Prefecture【Fukuoka Prefecture Tourism Short Movie】', description = 'Shobun Vinegar, located in Okawa City, has been producing vinegar for 300 years, specializing in carefully crafted vinegar through static fermentation. The headquarters in Okawa City features a shop and restaurant, and offers tours of the vinegar brewery.' where id = 'AX0KO_MyT9e0fM4d2_zKo';
update content_bodies set title = 'toRmansionより11月26，27日　サンポート高松第2小ホールの高松初演音楽劇「青い鳥と赤い猫」', description = '高松をイメージして創作された完全新作音楽劇「青い鳥と赤い猫～奇妙な旅の果てのはて？～」が、11月26日（金）と27日（土）にサンポートホール高松第2小ホールで初演されます。人気のtoRmansionからのメッセージ映像も届き、初演後の公演も企画されているとのことです。子どもも大人も楽しめる「ハートフル・ドリーム・エンターテイメント」を体験できる貴重な機会です。チケットはpeatixから入手可能です。toRmansionは2007年に結成され、16カ国82都市で公演を行い、世界中で人気を博しています。フランスのアビニョン演劇祭では口コミトップ20に選ばれ、神戸ビエンナーレ大道芸コンペティションでの受賞歴もあります。' where id = 'iwznWIddpr0lD6grpFq_N';
update content_bodies set title = 'toRmansion''s Musical Theater ''The Blue Bird and the Red Cat'' Premiering in Takamatsu on November 26 and 27', description = 'A completely new musical theater production titled ''The Blue Bird and the Red Cat: A Message from the End of a Strange Journey'' has been created with Takamatsu in mind. Scheduled for performances at the Sunport Hall Takamatsu on November 26 (Friday) and 27 (Saturday), a message video from the popular group toRmansion has just arrived. There are plans for additional performances following the premiere in Takamatsu! This heartwarming dream entertainment is a fresh experience for both children and adults. Tickets can be obtained via Peatix. toRmansion, established in 2007, has performed in 82 cities across 16 countries, gaining immense popularity worldwide. They have been recognized at the Avignon Festival in France and have won multiple awards, including two Grand Prix at the Kobe Biennale Street Performance Competition. The company has received high praise internationally, with notable figures like fashion designer Jean-Paul Gaultier being a fan.' where id = 'W-7C754fNdPMOFlw8lVt4';
update content_bodies set title = '文化財に泊まる!?伊賀市の #リノベーションホテル', description = '伊賀市の城下町に位置する分散型ホテルでは、歴史的建造物をリノベーションした3つの宿泊棟が点在しています。ホテルのコンセプトは「まちに忍ぶように泊まる」で、ワクワクする客室が揃っています。大きなヒノキ風呂や秘密基地のような寝室があり、宿泊者を楽しませます。また、レストランでは地元の食材を使った料理を堪能できます。NIPPONIA HOTEL 伊賀上野 城下町は、チェックインが15:00、チェックアウトが12:00で、レストランの営業時間はランチが11:30～15:00、ディナーが17:30～22:00です。駐車場は20台分あり、料金は大人1名1泊2食付きで4万5210円からです。伊賀鉄道「上野市駅」から徒歩約6分の距離にあります。' where id = 'j05s1fZApacC3mPrm2BdQ';
update content_bodies set title = 'Stay in Cultural Heritage!? Renovation Hotel in Iga City', description = 'Experience a unique stay in a dispersed hotel located in the historic castle town of Iga City, featuring three accommodation buildings. The hotel concept is to ''stay like a ninja in the town.'' Guests can enjoy exciting rooms, including a large cypress bath and bedrooms resembling secret bases. The on-site restaurant offers a delightful dining experience with local ingredients. The hotel is located at NIPPONIA HOTEL Iga Ueno Castle Town, with check-in at 15:00 and check-out at 12:00. The restaurant serves lunch from 11:30 to 15:00 and dinner from 17:30 to 22:00. Parking is available for 20 vehicles, and rates start at 45,210 yen per adult for a one-night stay with two meals. The hotel is a 6-minute walk from Iga Railway''s Ueno City Station.' where id = '_DkkQgfLC9JfXZPDIAbsa';
update content_bodies set title = '【奄美大島】奄美群島エコツアーガイド 大和村編', description = '奄美広域事務組合が実施する奄美群島エコツーリズム魅力体験事業の一環として、奄美大島の大和村に住む地域通訳案内士の中山さんに密着したエコツアー動画が作成されました。このプロジェクトは、世界自然遺産に登録されている奄美群島の自然の美しさや生物多様性を広めることを目的としています。ツアーやガイドに関する問い合わせは、各島の観光協会に連絡するように案内されています。' where id = 'yvLhbYHGNWcB2TpdHIu5o';
update content_bodies set title = 'Eco tourism in Yamato Village Amami Oshima Island', description = 'This project showcases the eco-tourism experiences in Amami Oshima, specifically in Yamato Village, through a video featuring Nakayama, a local interpreter and tour guide. The initiative is part of the Amami Regional Office''s efforts to promote the natural beauty and biodiversity of the Amami Islands, which are recognized as a World Natural Heritage site. For inquiries about tours and guides, visitors are encouraged to contact the local tourism associations on each island.' where id = 'Qx_sukEsw5_WqpsuTgghc';
update content_bodies set title = '【加計呂麻島】奄美群島認定エコツアーガイド 瀬戸内町編', description = 'このプロジェクトは、奄美群島のエコツーリズム体験を紹介し、特に加計呂麻島と瀬戸内町に焦点を当てています。動画では、瀬戸内町に住む認定エコツアーガイドの寺本さんが登場し、地域の美しさや生物多様性を強調しています。ツアーやガイドに関する問い合わせは、各島の観光協会にご連絡ください。この取り組みは、奄美広域事務組合のエコツーリズム促進の一環です。' where id = 'aRZ5Fg4ST4gPZxEYQ9vGc';
update content_bodies set title = 'Eco tourism in Setouchi Town Amami Oshima Island', description = 'This project showcases the eco-tourism experiences in the Amami Islands, focusing on Kakeromajima and Setouchi Town. The video features Teramoto, a certified eco-tour guide residing in Setouchi Town, highlighting the beauty and biodiversity of the area. For inquiries about tours and guides, please contact the local tourism associations of each island. The initiative is part of the Amami Regional Office''s efforts to promote eco-tourism.' where id = 'WsXbe3zLtNXVIhLlP5MWb';
update content_bodies set title = '奄美群島認定エコツアーガイド 奄美市編', description = '奄美広域事務組合による奄美市のエコツーリズム魅力体験事業に焦点を当て、認定エコツアーガイドの興さんに密着したエコツアー動画が作成されました。この動画は、世界自然遺産に認定された奄美群島の自然の美しさや生物多様性を紹介しています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。一般社団法人あまみ大島観光物産連盟も地域の魅力を発信しています。' where id = 'gDMZJYaR5iBg-j3Di4CYG';
update content_bodies set title = 'Eco tourism in Amami City Amami Oshima Island', description = 'This project focuses on eco-tourism in Amami City, featuring certified eco-tour guide Hiroshi. A video showcasing eco-tours has been created to highlight the natural beauty and biodiversity of the Amami Islands, which are recognized as a World Natural Heritage site. For inquiries about tours and guides, please contact the local tourism associations of each island. The Amami Tourism & Products Federation is also involved in promoting the region''s attractions.' where id = 'qGf-7xesSf0RtFLdv7ZkH';
update content_bodies set title = '【徳之島】奄美群島エコツアー カムイヤキの森 ハイキング', description = '奄美広域事務組合が主催する奄美群島エコツーリズム魅力体験事業では、奄美群島に住む認定エコツアーガイドに密着したオンラインエコツアーが開催されました。ツアーでは、徳之島のカムイヤキの森でのハイキングが行われ、ガイドは認定エコツアーガイドの常さんです。参加者は、植物などをむやみに採取せず、ガイドの指示に従うことが求められています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。' where id = '68Pf4xyQl__pMXE2WNeW4';
update content_bodies set title = 'Eco tourism in Tokunoshima Island', description = 'The Amami Islands Eco-Tourism Experience Project, organized by the Amami Regional Office, features an online eco-tour led by certified eco-tour guides residing on the five islands of the Amami archipelago. The tour includes a hiking experience in the Kamuiyaki Forest on Tokunoshima Island, guided by Mr. Tsunetaka, a certified eco-tour guide. Participants are advised to follow the guide''s instructions and refrain from indiscriminately collecting plants. For inquiries about the guide and tours, please contact the tourism associations of each island.' where id = 'GNPLD-WB7DOUDOyFTcfhy';
update content_bodies set title = '【沖永良部島】奄美群島エコツアー ケイビング', description = '奄美広域事務組合は、奄美群島のエコツーリズム魅力体験事業を開始しました。認定エコツアーガイドの小林さんが鍾乳洞を案内するオンラインエコツアーが開催されました。ガイドやツアーに関する問い合わせは、各島の観光協会にお願いします。' where id = 's-tLnmzwvNvC-hUNJQnfP';
update content_bodies set title = 'Eco tourism in Okinoerabujima Island', description = 'The Amami Regional Office has launched an eco-tourism experience project in the Amami Islands. An online eco-tour was conducted, featuring certified eco-tour guide Kobayashi, who provided a tour of the limestone caves. For inquiries about the guide and tours, please contact the tourism associations of each island.' where id = 'S8E2X7Z8s8mWnkG_tSpTs';
update content_bodies set title = '【与論島】奄美群島エコツアー 与論城跡ハイキング', description = '奄美広域事務組合は、奄美群島の5つの島に住む認定エコツアーガイドに密着したオンラインエコツアーを開催しました。ガイドの阿由葉さんが与論城跡を案内し、参加者にその魅力を伝えました。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。' where id = 'M5tz2Fmdhgtuzf0hdgAQn';
update content_bodies set title = 'Eco tourism in Yoronjima Island', description = 'The Amami Regional Office has launched an online eco-tourism experience project featuring certified eco-tour guides from the five islands of the Amami archipelago. The tour was led by guide Ayuha, who provided insights into the historical site of Yoronjima Castle. For inquiries about the guide and tours, please contact the tourism association of each island.' where id = 'og0nJI3kwXzfpyU9svzwZ';
update content_bodies set title = '【奄美大島】 奄美群島エコツアー 不思議な巨木ハイキング', description = '奄美広域事務組合は、奄美群島の5つの島に住む認定エコツアーガイドに密着したオンラインエコツアーを開催しました。このツアーでは、ガイドの常田さんが奄美大島にある不思議な巨木を案内します。ガイドやツアーに関する問い合わせは、各島の観光協会にお願いします。' where id = '2HkaOjvWNIA5HTQpfJOp2';
update content_bodies set title = 'Eco tourism in Amami Oshima Island', description = 'The Amami Regional Office has launched an online eco-tourism experience project featuring certified eco-tour guides from the five islands of the Amami archipelago. The tour includes a hike led by guide Tsunoda, who introduces participants to the mysterious giant trees of Amami Oshima. For inquiries about the guide and tours, please contact the tourism associations of each island.' where id = '4ty11KF9pwsE2e3FNIlTl';
update content_bodies set title = '中津川の桜【苗木さくら公園】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。ここでは「苗木さくら公園」を取り上げており、訪れる人々は桜と苗木城跡の天守展望台の両方を楽しむことができます。2020年4月10日にドローンで撮影された映像では、中津川の桜を4Kで堪能できます。詳細は中津川観光協会のホームページをご覧ください。' where id = 'VW6bltRQvk7H5UP0AiEUu';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Naegi Sakura Park', description = 'This is a series showcasing the best cherry blossom spots in Nakatsugawa, Gifu Prefecture. The focus here is on Naegi Sakura Park, where visitors can enjoy views of both the cherry blossoms and the observatory at the Naegi Castle ruins. The footage was captured using a drone on April 10, 2020, allowing viewers to appreciate the cherry blossoms in stunning 4K resolution. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'Y7M9GFWgq4CCgLgiIJik5';
update content_bodies set title = 'けふの下呂温泉', description = '2月11日（土）に開催される『冬の下呂温泉花火物語』では、『バレンタイン花火』がテーマです。女性を応援する情熱的な花火が夜空に打ち上がる予定です。バレンタインデーの歴史は古く、古代ローマ帝国のウァレンティヌス司祭に由来しています。古代ローマといえば温泉も関連が深く、下呂温泉にぴったりの日です。カップルで花火を楽しみ、一足早いバレンタインデーをお祝いしてください。今後とも下呂温泉をよろしくお願いいたします。' where id = 'Ps4eyPhapXMJLBfzTXLgx';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On February 11th (Saturday), the theme for the ''Winter Gero Onsen Fireworks Story'' is ''Valentine''s Fireworks.'' Passionate fireworks supporting women are set to light up the night sky. The history of Valentine''s Day is ancient, linked to Saint Valentine, who acted to protect soldiers'' marriages during the Roman Empire. Speaking of ancient Rome, it’s a fitting day to enjoy Gero Onsen. Couples are encouraged to watch the fireworks and celebrate an early Valentine''s Day together. We look forward to your continued support of Gero Onsen.' where id = 'gYfZ5UuR5G95XOOrWJsL1';
update content_bodies set title = 'けふの下呂温泉', description = '1月28日（土）に行われた『冬の下呂温泉花火物語』の様子をお伝えします。この日は雪が降る中での花火となり、寒さが厳しい中でも多くのお客様が集まりました。テーマは「健康祈願・節分花火」で、赤鬼・青鬼・豆まきを表現した花火が打ち上げられ、皆様の健康を祈願しました。下呂温泉の湯に浸かることで健康や美容に良い効果があるとされています。次回の花火は2月4日（土）にも行われるので、ぜひお越しください。今後とも下呂温泉をよろしくお願いいたします。' where id = 'CUKu2OTUNIpekRbtqKCpd';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On January 28th (Saturday), the ''Winter Gero Onsen Fireworks Story'' took place amidst falling snow. Despite the strong cold, many guests gathered for the fireworks display. The theme for the day was ''Health Prayer and Setsubun Fireworks,'' featuring fireworks that represented red and blue demons and the tradition of throwing beans, all aimed at wishing for everyone''s health in the coming year. Visitors are encouraged to enjoy the healing waters of Gero Onsen, which are said to have significant beauty benefits. Fireworks will also be held on the following weekend, February 4th (Saturday), so please come and enjoy the show. We appreciate your continued support for Gero Onsen.' where id = 'd8dvbAqJh6Q7YsCfNQxwh';
update content_bodies set title = '現実の「鬼滅の刃」無限城 | 足湯温泉 大川荘', description = 'この動画は、足湯温泉の大川荘での「鬼滅の刃」無限城のリアルな体験を紹介しており、公共浴場を含むすべての場所で撮影許可を得ています。視聴者は、TABBIAの公式オンラインストアやInstagram、旅行マップへのリンクを見つけることができます。また、AgodaやHotels.comなどのプラットフォームを通じて宿泊予約の方法も詳しく説明されています。足湯温泉駅からの無料シャトルバスなどの交通手段も紹介されており、駅には猫の駅長がいます。2人分の料金は約44,300円で、プランや季節によって異なります。動画には、部屋のツアー、プライベートバス、三味線の演奏、食事体験などのセグメントのタイムスタンプが含まれています。' where id = 'wC_sC4DhUT2tQELUoGNVJ';
update content_bodies set title = 'Demon Slayer Infinity Castle in REAL LIFE | Ashinomaki-Onsen Ookawaso', description = 'This video showcases the real-life experience of the Demon Slayer Infinity Castle at the Ookawaso ryokan in Ashinomaki Onsen, filmed with permission in all locations, including the public bath. Viewers can find links to the TABBIA official online store and Instagram, as well as a travel map for directions. The video provides information on how to book a stay at the ryokan through various platforms like Agoda and Hotels.com. It also details the transportation options available, including a free shuttle bus from Ashinomaki Onsen Station, where a cat stationmaster is present. The cost for two people is approximately 44,300 yen, with prices varying by plan and season. The video includes timestamps for different segments, such as room tours, private baths, a shamisen performance, and dining experiences.' where id = 'n4rOfH6Z1HE3MR7lG_T7z';
update content_bodies set title = '中津川の桜【本町公園の桜】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。こちらは中津川市街地に位置する本町公園の桜で、2021年3月28日にドローンで撮影されました。中津川の桜を4K映像でお楽しみください。詳細は中津川観光協会のホームページをご覧ください。' where id = 'VJjaH8GtUHwFewYkRTGgO';
update content_bodies set title = 'Sakura in Nakatsugawa: Honmachi Park Cherry Blossoms', description = 'This is a series introducing famous cherry blossom spots in Nakatsugawa City, Gifu Prefecture. The cherry blossoms at Honmachi Park, located in the city center of Nakatsugawa, were captured in a drone video on March 28, 2021. Enjoy the cherry blossoms of Nakatsugawa in stunning 4K footage. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'pWDAGAsQ4LZ7KaHrihRAD';
update content_bodies set title = 'けふの下呂温泉', description = '1月14日（土）に行われた『冬の下呂温泉花火物語』の様子をお伝えします。今回は『花餅花火』というテーマで、紅白をイメージした花火が打ち上げられました。正月から少し時間が経過しましたが、まだその雰囲気を楽しむことができました。当日は朝から雨が降っていましたが、花火の時間には天候が回復し、寒い中でも快適に観賞できました。観客からは歓声が上がり、盛り上がりを見せました。次回の花火は1月21日（土）にも行われるので、ぜひお越しください。今後とも下呂温泉をよろしくお願いいたします。' where id = 'RxiHwBIG30bt3GJJ0tI5L';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On January 14th (Saturday), the ''Winter Gero Onsen Fireworks Story'' took place. This time, the fireworks were themed ''Hanamochi Hanabi,'' featuring displays inspired by red and white colors. Although some time has passed since the New Year, the festive atmosphere was still palpable. Despite rain in the morning, the weather cleared up by the time the fireworks started, allowing for a comfortable viewing experience, which elicited cheers from the audience. Fireworks will also be launched next weekend on January 21st (Saturday), so we encourage everyone to come and enjoy the show. We appreciate your continued support for Gero Onsen.' where id = 'LirgM9uVjqox-jITv37_5';
update content_bodies set title = 'けふの下呂温泉', description = '1月7日（土）に『冬の下呂温泉花火物語』が開催されました。『成人花火』と題された花火は、大人の雰囲気の中で20段打ち上げられました。肌寒い中、多くのお客様が訪れました。『花火物語』は3月25日までの毎週土曜日に打ち上げられる予定です。寒い時期こそ温泉に浸かってリラックスしたいですね。今後とも下呂温泉をよろしくお願いいたします。' where id = '4OfKW0CxVh_Rjz0IBVATd';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On January 7th, the ''Winter Gero Onsen Fireworks Story'' was held. The fireworks, titled ''Adult Fireworks,'' celebrated adulthood with a sophisticated atmosphere, featuring 20 launches. Despite the chilly weather, many guests attended the event. The ''Fireworks Story'' is scheduled to continue every Saturday until March 25th. This cold season is perfect for relaxing in the hot springs. We look forward to your continued support for Gero Onsen.' where id = '1WhT-ftpxsxlN27grNbgb';
update content_bodies set title = 'けふの下呂温泉', description = '7月9日（土）に行われた『天壌無窮　悪疫退散　下呂温泉花火物語』の最終回では、彦星と織姫の再会を祝う華やかな花火が夜空を彩りました。多くのお客様に見送られ、花火物語は幕を閉じました。しかし、8月1日（月）から4日（木）までの「下呂温泉まつり」では、毎日花火が打ち上げられる予定です。また、7月23日（土）からは「いでゆ夜市」が「サマーフェスティバルin下呂温泉」として開催されます。下呂温泉の夏はイベントが盛りだくさんですので、ぜひお楽しみください！詳細は下記のHPをご覧ください。https://www.gero-spa.com/ 下呂温泉をよろしくお願いいたします！' where id = 'FFB9GkFhKau_u4rQ7DG2F';
update content_bodies set title = 'Gero Onsen Today', description = 'On July 9th (Saturday), the final event of ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' took place. Colorful fireworks lit up the night sky to celebrate the reunion of Hikoboshi and Orihime. Many guests attended, marking the end of the fireworks story. However, as previously announced, fireworks are scheduled to be launched daily during the ''Gero Onsen Festival'' from August 1st (Monday) to August 4th (Thursday). Additionally, from July 23rd (Saturday), the ''Ideyu Night Market'' will be transformed into the ''Summer Festival in Gero Onsen.'' Gero Onsen''s summer is packed with events, so please enjoy them! For more details, visit the website: https://www.gero-spa.com/. Don''t miss out on Gero Onsen!' where id = 'usfufRH-gm4-Ny_TGO47Q';
update content_bodies set title = '近鉄沿線で奈良の魅力を見つけよう', description = '奈良は近鉄鉄道でアクセスできる有名な観光地です。この動画では、奈良公園の「鹿」から隠れた素晴らしいスポットまで、さまざまな地元の魅力を紹介します。詳細情報については、東大寺、春日大社、天川村、金峯山寺のリンクを参照してください。また、近鉄鉄道沿線の観光には、観光特急「青い夜」や「ブルーシンフォニー」に乗ることをお勧めします。' where id = '0jwMOG0hVNqefeE2K8koI';
update content_bodies set title = 'Find charms along Kintetsu lines in NARA', description = 'Nara, accessible via Kintetsu Railway, is renowned for its attractions. This video showcases various local charms, including the famous Nara Park with its deer and other hidden gems. For more detailed information, links to notable sites such as Todaiji Temple, Kasugataisha Shrine, Tenkawa Village, and Kinpusenji Temple are provided. Additionally, travelers are encouraged to experience the scenic views by taking the Sightseeing Limited Express trains, AONIYOSHI and Blue Symphony, along the Kintetsu Railway.' where id = 'hLBR0f7HtC47AGcRXGnh2';
update content_bodies set title = 'けふの下呂温泉', description = '1月21日（土）に行われた『冬の下呂温泉花火物語』の様子をお伝えします。テーマは「春よ来い来い・寒明け花火」で、大寒の終わりを温かみのある色調の花火で表現しました。寒い夜にもかかわらず、多くのお客様が花火を楽しみに訪れました。新年から3週間が経ち、下呂温泉も活動を開始しています。昨年よりも素晴らしい体験を提供できるよう努めてまいります。次回の花火は1月28日（土）にも打ち上げられますので、ぜひお越しください。今後とも下呂温泉をよろしくお願いいたします。' where id = 'WK45MZej8qABG0REtBS3m';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On January 21st (Saturday), the ''Winter Gero Onsen Fireworks Story'' took place. The theme was ''Spring Come, Come - Cold Ending Fireworks,'' expressing the end of the deep cold with warm-colored fireworks. Despite the chilly night, many visitors came to enjoy the fireworks. Three weeks have passed since the New Year, and Gero Onsen is starting to get into full swing. We are committed to providing an even more wonderful experience at Gero Onsen than last year. Fireworks will also be launched next weekend on January 28th (Saturday), so we invite everyone to come and enjoy them. Thank you for your continued support of Gero Onsen.' where id = 'hxEBFjryuDLZSfqjyzygr';
update content_bodies set title = 'けふの下呂温泉', description = '『天壌無窮　悪疫退散　下呂温泉花火物語』も残すところあと1回、7月9日（土）が最後となります。7月2日（土）に打ち上がった花火のテーマは「清流花火」で、飛騨川のせせらぎをイメージした彩り豊かな花火が咲きました。ラストスパートの連続花火は圧巻でした！ぜひ、動画をご覧ください！暑い日が続きますが、こういう時こそ温泉で汗を流してサッパリしましょう。足湯もおすすめです！下呂温泉をよろしくお願いいたします！' where id = 'IVlhTu4UWXeRPLULDTZ9f';
update content_bodies set title = 'Gero Onsen Today', description = 'The event ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' is down to its final performance, scheduled for July 9th (Saturday). The fireworks launched on July 2nd had the theme ''Clear Stream Fireworks,'' featuring vibrant displays inspired by the gentle flow of the Hida River. The grand finale of continuous fireworks was truly impressive! Be sure to check out the video! Despite the ongoing hot days, it''s the perfect time to relax in the hot springs and refresh yourself. Foot baths are also highly recommended! We appreciate your support for Gero Onsen!' where id = '52aMwDeZTl1xgU4KQYZ7o';
update content_bodies set title = 'けふの下呂温泉', description = '『天壌無窮　悪疫退散　下呂温泉花火物語』も終盤を迎えています。この日のテーマは「父の日花火」で、黄色を基調とした花火が打ち上げられ、家族の愛情や尊厳を表現しました。ダイナミックな花火に感嘆の声が上がり、来場者と共に高揚感を共有しました。残すところあと3回（6月25日、7月2日、9日）となっており、ぜひすべての回をご覧いただきたいと思います。下呂温泉をよろしくお願いいたします！' where id = 'Cih8pSaPmx8AyzlVFFxm_';
update content_bodies set title = 'Gero Onsen Today', description = 'The event ''Tenjo Mukyu: Fireworks Story of Gero Onsen for Epidemic Prevention'' is nearing its end. The theme for this day was ''Father''s Day Fireworks,'' featuring yellow fireworks that express family love and respect in gratitude for fathers. The dynamic display of fireworks drew exclamations of awe from the audience, creating a unique sense of exhilaration as everyone shared in the experience. There are only three more shows left (on June 25, July 2, and July 9), and we hope everyone can attend them all! Thank you for your support of Gero Onsen!' where id = '8GLg5_tDPx8BwGem0J8Ca';
update content_bodies set title = 'けふの下呂温泉', description = '金山町菅田桐洞地内の菅田川へ、ホタルの大群を求めて再訪しました。しかし、今年はホタルが出てくるのが2週間ほど遅れているようで、来週こそ最盛期であろうと教えていただきました。実際、まだホタルはあまりおらず、来週こそはと決意を固めました。その代わりにオオサンショウウオに出会い、初めて生きている姿を見てとても嬉しかったです。来週こそホタルの群れをお届けできるでしょうか？またオオサンショウウオにも再会できるでしょうか？どうかお楽しみに。下呂温泉をよろしくお願いいたします！' where id = 'G7JkRbGOOFwS0nXT_4XwU';
update content_bodies set title = 'Today in Gero Onsen', description = 'I revisited Sugata River in Kanayama Town, hoping to see a large swarm of fireflies. However, it seems that the fireflies are about two weeks late this year. A fellow visitor informed me that next week should be the peak season. Indeed, there were not many fireflies present, so I resolved to return next week. Instead, I encountered a giant salamander, which is known to come out to catch sweetfish. It was my first time seeing a living giant salamander, and I was very excited. I wonder if I will be able to share a swarm of fireflies next week and if I will meet the giant salamander again. Please look forward to it. Thank you for your support of Gero Onsen!' where id = '2xVCIHOFTmVMSBwhUJLcK';
update content_bodies set title = 'けふの下呂温泉', description = 'げるぐんくんの呟きで、ゲンジボタルが見ごろと知り、金山町の菅田川へホタルを見に行きました。しかし、当日は少し寒く、ホタルが飛ぶ条件である蒸し暑く穏やかな気候ではなかったため、あまりホタルが見られませんでした。それでも、葉っぱに止まったホタルを間近で見ることができて嬉しかったです。現地で会った方によると、むしろ今週が見ごろとのことなので、暖かく風のない日を狙って再度訪れようと思います。次こそ、夜空を舞うホタルの群れを見たいです。下呂温泉をよろしくお願いいたします！' where id = 'GoeNKQRXiO0JkXCLB-zb0';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I learned from Gerugun-kun''s tweet that the Genji fireflies are in full bloom, so I went to Sugata River in Kanayama Town to see them. However, the weather was a bit cold, and the conditions for a good firefly display—warm and calm—were not met, resulting in fewer fireflies than expected. Nevertheless, I was delighted to see some fireflies resting on the leaves up close. A local I met mentioned that this week might actually be the best time to see them, so I plan to return on a warm, windless day. I hope to witness a swarm of fireflies dancing in the night sky next time. Please support Gero Onsen!' where id = 'poI4DtgrQVAE3r9j-mdMH';
update content_bodies set title = 'けふの下呂温泉', description = '6月11日（土）に『天壌無窮　悪疫退散　下呂温泉花火物語』が打ち上げられました。テーマは「アジサイ花火」で、梅雨に咲くアジサイをイメージしています。当日は少雨でしたが、逆に花火に彩りを与え、多くのお客様が観賞に訪れました。花火は素晴らしく、一つ一つに歓声が上がりました。夏が近づき、花火の盛り上がりも期待されます。来週の「父の日花火」もお見逃しなく！下呂温泉をよろしくお願いいたします！' where id = '5ZIk9uJz2KSRAO0Tjal7n';
update content_bodies set title = 'Gero Onsen Today', description = 'On June 11th, the ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' was launched. The theme was ''Hydrangea Fireworks,'' inspired by the hydrangeas that bloom during the rainy season. Unfortunately, there was light rain on the day, but this seemed to enhance the beauty of the fireworks. Despite the rain, many guests came to enjoy the show, and each firework elicited cheers from the crowd. As summer approaches, the excitement for fireworks is building. Don''t miss next week''s ''Father''s Day Fireworks''! We appreciate your support for Gero Onsen!' where id = 'YCtGl3UfnnDdVl2bBKeoL';
update content_bodies set title = 'けふの下呂温泉', description = '5月28日（土）に行われた『天壌無窮　悪疫退散　下呂温泉花火』の様子をお伝えします。下呂市の大自然をイメージした色鮮やかな花火が打ち上がり、「新緑花火」というテーマにふさわしい賑わいを見せました。寒さも過ぎ去り、夏の陽気が訪れています。次回の6月4日（土）のテーマは「山開き花火」で、気候もそれにぴったりです。夜の登山は少し危険ですが、高い場所から花火を楽しむのも良いかもしれません。下呂温泉をよろしくお願いいたします！' where id = 'LqyaFgITZU88FH-l0tlQg';
update content_bodies set title = 'Gero Onsen Today', description = 'On May 28th, the ''Eternal Heaven and Earth, Epidemic Dispersal, Gero Onsen Fireworks'' event took place. Colorful fireworks inspired by the great nature of Gero City lit up the sky, showcasing a lively atmosphere that matched the theme of ''Fresh Green Fireworks.'' The cold weather has passed, and the summer warmth is here. The climate is perfect for the next event on June 4th, themed ''Mountain Opening Fireworks.'' While night climbing may be a bit dangerous, it could be a good idea to watch the fireworks from a high vantage point, reminiscent of the mountains. Please support Gero Onsen!' where id = 'dVzPHrk7MaDtldghm5vyb';
update content_bodies set title = '中津川＆下呂PR動画 「Wonderful days」【4K】', description = 'この動画は下呂市と中津川市のPR映像で、観光スポットを紹介しています。付知峡や不動滝、宮島キャンプ場などの自然の美しさが映し出され、下呂温泉の魅力や素肌美人スイーツなどの地元の特産品も紹介されています。また、苗木城跡やサイクリングコース、五平餅作り体験など、歴史や文化に触れることができるスポットも含まれています。各観光地の詳細情報へのリンクも提供されており、視聴者にこの地域の魅力を探求することを促しています。' where id = 'vhwkeUwPAnY5-9xNdl3zg';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Days'' [4K]', description = 'This video is a promotional film for Gero City and Nakatsugawa City. It showcases various tourist attractions in the area, including scenic spots like Tsukechi Gorge, Fudo Falls, and Miyajima Campground. The video also features Gero Onsen, famous for its hot springs, and local delicacies such as Suhada Bijin sweets. Other highlights include cycling routes, historical sites like Naegi Castle Ruins, and cultural experiences like Gohei Mochi making. The video provides links to more information about each location, encouraging viewers to explore the beauty and charm of these regions.' where id = 'hedZqX2fMqcZ641VhqeDa';
update content_bodies set title = 'けふの下呂温泉', description = '4月16日（土）に行われた『天壌無窮　悪疫退散　下呂温泉花火』の様子をお伝えします。テーマは飛騨小阪の滝開きを記念した『滝開き花火』で、天候にも恵まれ、多くのお客様が訪れ、歓声が上がっていました。下呂温泉では毎週花火が打ち上げられていますので、ぜひお越しください。花火だけでなく、温泉も天下一品です！下呂温泉をよろしくお願いいたします！' where id = 'CrCpogmhJn4qsCMpI8lmm';
update content_bodies set title = 'Gero Onsen Today', description = 'On April 16th (Saturday), the event ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks'' took place. The theme was ''Waterfall Opening Fireworks'' to commemorate the opening of the Hida Kosaka waterfall. The weather was favorable, and many guests attended, cheering with excitement. Fireworks are launched every week at Gero Onsen, so please come and enjoy. Not only the fireworks but also the hot springs are exceptional! We appreciate your support for Gero Onsen!' where id = 'H8cJPboPRZjBUo1gY1jnU';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉のしらさぎ緑地公園での桜の様子を紹介します。天候に恵まれ、暖かい風に包まれながら桜を楽しむことができました。満開の桜を眺めながらの散策は格別で、甘く爽やかな花の香りにはリラックス効果があります。さらなるリラックスを求めて温泉に浸かるのも良いですね。桜を見た後は、ぜひ温泉に入ってください。下呂温泉をよろしくお願いいたします！' where id = 'j3Vm5f6ZcUlUKWf8FTO-e';
update content_bodies set title = 'Today at Gero Onsen', description = 'This is a description of the cherry blossoms at Shirakagi Green Park in Gero Onsen. The weather was pleasant, allowing us to enjoy the cherry blossoms surrounded by a warm breeze. Strolling while admiring the fully bloomed cherry blossoms is a unique experience. The sweet and refreshing scent of the flowers seems to have a relaxing effect. For further relaxation, soaking in the hot springs is also a great idea! After enjoying the cherry blossoms, be sure to take a dip in the onsen. We appreciate your support for Gero Onsen!' where id = 'DufrLwkpYgv5xQIUeNqKe';
update content_bodies set title = '志摩地中海村【ドローン撮影】(志摩市)｜観光三重｜三重県の観光・旅行情報', description = 'インスタ映えスポットとして人気急上昇中の「志摩地中海村」をドローンで撮影しました。このリゾート宿泊施設は、三重県の伊勢志摩半島の豊かな自然の中に突然現れるスペインの雰囲気を漂わせています。撮影は特別に許可を得て行っており、通常営業時には撮影ができないことをご了承ください。' where id = '89OLXGyB9G7zZt2E1rue6';
update content_bodies set title = 'Shima Mediterranean Village [Drone Footage] (Shima City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Shima Mediterranean Village is rapidly gaining popularity as an Instagram-worthy spot! This resort accommodation, exuding a Spanish atmosphere, suddenly appears amidst the rich nature of the Ise-Shima Peninsula in Mie Prefecture. The drone footage was taken with special permission, and please note that filming is not allowed during regular business hours.' where id = 'ti3PY8nSeEzqwrzxyLhPR';
update content_bodies set title = 'けふの下呂温泉', description = '3月19日（土）から21日（月）にかけて、3夜連続で『天壌無窮　悪疫退散　下呂温泉花火』が開催され、夜空を華やかに彩りました。寒い夜にもかかわらず、『卒業・旅立ちの応援花火』をテーマにした花火を見に多くのお客様が訪れ、337拍子などで期待感を高めるお祝いの花火が打ち上げられました。見事な花火に歓声が上がり、寒さを吹き飛ばす勢いでした。今週末の26日（土）、27日（日）にも花火が予定されており、さらに4月2日（土）から7月9日（土）までの毎週土曜日にも花火が打ち上がる予定です。下呂温泉で花火を楽しみながら温泉を堪能するのは格別です。下呂温泉をよろしくお願いいたします！' where id = '5t9dvMvZj-xvLr54umEm4';
update content_bodies set title = 'Gerō Onsen Fireworks', description = 'From March 19th (Saturday) to 21st (Monday), the ''Tenjō Mukyū, Epidemic Dispersal, Gerō Onsen Fireworks'' event illuminated the night sky with fireworks over three consecutive nights. Despite the chilly weather, many visitors came to enjoy the spectacular display themed ''Graduation and Departure Support Fireworks,'' featuring exciting fireworks that filled the air with celebration. The impressive fireworks drew cheers from the crowd, dispelling the cold. This weekend, on the 26th (Saturday) and 27th (Sunday), and every Saturday from April 2nd to July 9th, more fireworks are scheduled to be launched. Experience the continuous blooming of fireworks in the night sky at Gerō Onsen, where enjoying the hot springs while watching the fireworks is truly exceptional. We appreciate your support for Gerō Onsen!' where id = 'dzpHwlRTuRmv57GORbKqe';
update content_bodies set title = 'けふの下呂温泉', description = 'お待たせしました！『天壌無窮悪疫退散下呂温泉花火物語』が再開しました。3月12日（土）・13日（日）には『ホワイトデー花火』が打ち上げられ、男性から女性への感謝の気持ちを込めた白を基調とした花火が夜空を彩りました。久しぶりの花火は感無量です。夜風も温かくなり、防寒具なしでも過ごせるほどです。こんな陽気の日は、温泉に浸かるのが一番ですね！下呂温泉をよろしくお願いいたします。' where id = 'BoHG7X3mBSIdSMB9JiLg8';
update content_bodies set title = 'Today''s Gero Onsen', description = 'The long-awaited ''Tenjo Mukyu Akki Taisan Gero Onsen Fireworks Story'' has finally resumed! The ''White Day Fireworks'' were launched on March 12th and 13th, featuring white-themed fireworks that expressed gratitude from men to women in front of many guests. The long-awaited fireworks were truly moving! The night breeze has become pleasantly warm, making it comfortable without winter clothing. On such a lovely day, soaking in the hot springs is the best choice! We appreciate your support for Gero Onsen.' where id = '01PvUZwiJVlWmnmbeqHtV';
update content_bodies set title = 'けふの下呂温泉', description = '1月15日（土）に行われた『花餅花火』の様子をお伝えします。紅白の花火が打ち上げられ、花餅を表現していました。雪が降った後の開催で、雪に反射する紅白の光がとても美しかったです。花火は通常夏に行われるため、雪の中での打ち上げは特別な体験でした。次回の1月22日（土）の花火でも、雪の中で楽しめるでしょうか？下呂温泉をよろしくお願いいたします！' where id = 'sPuPtHprYIOzW27q_O0d5';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On January 15th (Saturday), the ''Hanamochi Hanabi'' event took place. The fireworks displayed red and white colors, symbolizing the Hanamochi. The event was held right after a snowfall, creating a beautiful reflection of the colors against the snow. Fireworks are typically held in summer, so witnessing them in the snow was a unique experience. Looking ahead, will we be able to enjoy more fireworks in the snow on January 22nd (Saturday)? We appreciate your support for Gero Onsen!' where id = 'QYcvPRXc_rr1JnKthPTH4';
update content_bodies set title = 'けふの下呂温泉', description = '新年あけましておめでとうございます。今年も下呂温泉をよろしくお願いいたします。1月8日（土）には『成人花火』が行われ、多くのお客様が訪れました。年明け最初の花火ということで、盛況でした。コロナウイルス感染症の影響が続く中、感染症対策を徹底し、下呂温泉はお客様をお待ちしております。2月からは日曜日や祝日にも花火が打ち上がる予定ですので、ぜひご覧ください。下呂温泉をよろしくお願いいたします！' where id = 'ybfMQreIBfja_R-BhGnF7';
update content_bodies set title = 'Gero Onsen Today', description = 'Happy New Year! We look forward to your continued support for Gero Onsen this year. On January 8th (Saturday), we held the ''Adult Fireworks'' event, attracting many visitors as it was the first fireworks display of the year. Although the situation regarding COVID-19 remains uncertain, we are committed to thorough infection control measures and are ready to welcome guests to Gero Onsen. Starting in February, fireworks are also scheduled to be launched on Sundays and public holidays, so please come and enjoy them. Thank you for your support of Gero Onsen!' where id = 'Y5aEM-jYjnkHmieIzK5af';
update content_bodies set title = 'けふの下呂温泉', description = '12月25日（土）に行われた天壌無窮悪疫退散の下呂温泉花火物語の様子です。今年の打ち上げはこれで最後で、少し遅くなりましたが『クリスマス花火』をテーマに夜空を彩りました。次回は1月8日（土）の『成人花火』ですので、楽しみにお待ちください。今年一年もあっという間に過ぎました。来年もよろしくお願いいたします。これからも下呂温泉をよろしくお願いいたします！' where id = 'OX5IvAblCYZOBqhHmo_mP';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On December 25th (Saturday), the Gero Onsen Fireworks Story took place, themed ''Christmas Fireworks.'' This was the last fireworks display of the year, which beautifully lit up the night sky. The next event will be the ''Coming of Age Fireworks'' on January 8th (Saturday), so please look forward to it. This year has flown by, and we appreciate your support. We look forward to your continued patronage of Gero Onsen in the coming year!' where id = 'dFW5MPrFhhfnv1HzgQ6oU';
update content_bodies set title = 'けふの下呂温泉', description = '12月18日（土）に開催された『天壌無窮悪疫退散　下呂温泉花火物語』の様子をお伝えします。テーマの「冬至花火」に合わせて、冷え込んだ夜空に柚子やかぼちゃ、温泉のカラーの花火が映し出され、お客様たちを楽しませました。来週の土曜日のイベントも楽しみですね。週一の楽しみとしての花火に加え、毎日の楽しみとして数多くの温泉があります。お気に入りの温泉を探してみるのも良いでしょう。下呂温泉をよろしくお願いいたします！' where id = '5KN63VTwZiaXwUMcPMz8O';
update content_bodies set title = 'Gero Onsen Today', description = 'On December 18th (Saturday), the event ''Tenjo Mukyu Akueki Taisan: Gero Onsen Fireworks Story'' took place. The theme ''Winter Solstice Fireworks'' matched the chilly night, as fireworks in the shapes of yuzu, pumpkin, and the colors of the hot springs delighted the audience. Next Saturday''s event is also highly anticipated. While fireworks are a weekly joy, the numerous hot springs provide daily enjoyment. It''s a great idea to explore your favorite hot springs. We appreciate your support for Gero Onsen!' where id = 'MTBe2qf4YY8FKzfrcr-rH';
update content_bodies set title = 'けふの下呂温泉', description = '金山町にある『岩屋ダム』周辺の紅葉を撮影しました。雄大な景色の中に紅葉の赤や黄色が混じり、とても美しいです。多くのお客さんが訪れ、写真を撮ったり和気あいあいと過ごしていました。いつまでも眺めていたい光景ですが、霜が降りると葉が落ちてしまうため、早めの訪問をお勧めします。紅葉を楽しんだ後は、下呂温泉での入浴もお忘れなく！' where id = 'VmrPYeEedr74dv5kklUcw';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I visited the area around Iwaya Dam in Kanayama Town to capture the autumn leaves. The vibrant reds and yellows of the foliage blend beautifully with the majestic scenery. Many visitors were present, enjoying the view and taking photos in a cheerful atmosphere. It''s a sight you could gaze at forever, but with frost approaching, the leaves may soon fall, so it''s advisable to visit soon. Don''t forget to take a dip in Gero Onsen after enjoying the autumn colors!' where id = 'lg_9N1HucmYti7pjVkSDE';
update content_bodies set title = 'けふの下呂温泉', description = '11月13日（土）に開催された「天壌無窮　悪疫退散　下呂温泉花火物語」の様子をお伝えします。テーマは『七五三花火』で、節句を祈念し、3発・5発・7発の連続花火が打ち上げられました。冷え込んだ夜でしたが、多くのお客様が訪れ、寒さを忘れるほどの歓声が上がりました。下呂温泉ではまだまだ花火が楽しめます！花火の後は温泉で冷えた体を温めてください。下呂温泉をよろしくお願いいたします！' where id = 'zYLGpHsrqf-j8AJgetTy4';
update content_bodies set title = 'Gero Onsen Today', description = 'On November 13th (Saturday), the ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' event took place. The theme was ''Shichi-Go-San Fireworks,'' featuring a series of fireworks launched in groups of three, five, and seven to celebrate the seasonal festival. Despite the chilly night, many visitors attended, cheering loudly enough to dispel the cold. Fireworks will continue to be enjoyed at Gero Onsen! After the fireworks, guests can warm up in the hot springs. We appreciate your support for Gero Onsen!' where id = 'O2KpfNZS6_1_Tj-cTYWOa';
update content_bodies set title = 'けふの下呂温泉', description = '紅葉が見ごろということで、合掌村と初矢峠へ行ってきました。少し前まではまだ緑だった木々が、見事に赤く染まっていて感動しました。寒さもそれほど厳しくなく、散策を楽しむことができました。数日間は晴天が続くようなので、さらに紅葉を撮影したいと思います。合掌村には足湯があり、紅葉と温泉を同時に楽しむことができる風情ある場所です。下呂温泉をぜひよろしくお願いいたします！' where id = '4iRKRWeaKaMILNQxS91wa';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I visited Gassho Village and Hatsuya Pass to enjoy the beautiful autumn foliage. The trees, which I thought were still green a little while ago, have turned a stunning red. It''s truly moving to see such vibrant colors created by nature. The weather has been relatively mild, allowing me to take a leisurely stroll and fully appreciate the fall colors. With several days of clear skies ahead, I look forward to capturing even more autumn scenery. Gassho Village also features a foot bath, allowing visitors to enjoy both the autumn leaves and the hot springs at the same time, creating a charming atmosphere. I highly recommend Gero Onsen!' where id = 'fLXVRYZofsDvymxLaZsSz';
update content_bodies set title = 'けふの下呂温泉', description = '10月30日（土）に開催された『ありがとう！下呂駅開業91周年花火』をテーマにした「天壌無窮　悪疫退散　下呂温泉花火物語」の様子をお伝えします。列車をイメージしたオレンジカラーと卒寿を象徴する紫色の花火が打ち上げられ、これまでとは異なる趣の催しとなりました。次の100周年、200周年の花火も楽しみです。また、適度に温泉につかることが長生きの秘訣の一つとされています。花火の後は温泉で健康と長寿を目指しましょう！下呂温泉をよろしくお願いいたします！' where id = 'h6Hp2rVc07MPVPWUUEduA';
update content_bodies set title = 'Gero Onsen Today', description = 'On October 30th, a fireworks event themed ''Thank You! Gero Station''s 91st Anniversary Fireworks'' took place, featuring the ''Tenjo Mukyu, Evil Spirits Dispersed, Gero Onsen Fireworks Story.'' The fireworks displayed an orange color reminiscent of trains and a purple hue symbolizing the 90th anniversary, creating a unique atmosphere. The hope is to witness the fireworks for the 100th and 200th anniversaries in the future. Additionally, there is a belief that soaking in hot springs moderately contributes to longevity. After the fireworks, let''s aim for health and longevity by enjoying the hot springs! Please support Gero Onsen!' where id = '3hrCGI7HkUE7CZ1UcTrsF';
update content_bodies set title = '舞鶴サンセットクルーズ', description = '舞鶴ならではの護衛艦と夕日に染まる幻想的な風景を楽しむことができます。日没と共に艦船の自衛艦旗が降下される様子を見ることができるかもしれません。' where id = 'uOuPUEUsdZJ-XRxpS9n9X';
update content_bodies set title = 'Maizuru Sunset Cruise', description = 'Experience the unique scenery of Maizuru, featuring a destroyer and a fantastical sunset. You might even witness the lowering of the Self-Defense Force flag as the sun sets!' where id = 'oGqXuZaV8LRvzT5O3Vg54';
update content_bodies set title = 'けふの下呂温泉', description = '10月23日（土）に行われた「天壌無窮　悪疫退散　下呂温泉花火物語」の様子をお伝えします。肌寒い夜にもかかわらず、多くのお客様が訪れ、花火を楽しんでいました。テーマの『ハロウィン花火』に沿ったかぼちゃのオレンジや紫、黄色をイメージした花火が打ち上げられ、ワクワクするひと時を提供しました。ハロウィンの起源は紀元前にさかのぼると言われており、古くからの行事が今も続いていることに感慨深さを感じます。また、下呂温泉の起源も1000年前にさかのぼると言われています。これからも多くのお客様に温泉を楽しんでいただきたいと思います。下呂温泉をよろしくお願いいたします！' where id = 'l8u_FoZ95wUX9SXzT2Lb_';
update content_bodies set title = 'Gero Onsen Today', description = 'On October 23rd (Saturday), the event ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' took place. Despite the chilly night, many guests enjoyed the fireworks. Following the theme of ''Halloween Fireworks,'' the displays featured colors reminiscent of pumpkins, such as orange, purple, and yellow, creating an exciting atmosphere. The origins of Halloween are said to date back to ancient times, which is a profound reminder of how traditions have persisted through the ages. Similarly, Gero Onsen is believed to have origins that trace back 1,000 years. We hope many more visitors will continue to enjoy the hot springs! Thank you for your support of Gero Onsen!' where id = 'RQotlNXldUehjyNeTDgKc';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉は日々涼しさが増し、長袖が必要な肌寒さになっています。紅葉スポットの雨情公園（阿多野谷）を訪れましたが、まだ紅葉には早いようです。しかし、所々で葉が赤くなっている場所もあり、もうすぐ真っ赤な紅葉の中を散策できるでしょう。冷え込みが急なほど紅葉が美しくなるという説もあるため、今年の紅葉には期待が持てそうです。また、寒い中での温泉も健康に良く、楽しみです。下呂温泉をよろしくお願いいたします！' where id = '35Ym5SyWG44cLqgVQsDUX';
update content_bodies set title = 'Today’s Gero Onsen', description = 'Gero Onsen is becoming cooler, requiring long sleeves to stay warm. I visited the autumn foliage spot, Ujō Park (Atadon Valley), but it seems too early for the leaves to change color. However, there are some areas where the leaves are turning red, indicating that soon we will be able to enjoy a stroll amidst vibrant autumn colors. It is said that the more sudden the drop in temperature, the more beautiful the autumn foliage becomes, so this year’s colors are promising. Additionally, the hot springs, which provide warmth in this chilly weather, are also highly anticipated for their health benefits. Please enjoy Gero Onsen!' where id = 'aKvGyGMz-wwlltqtWigJN';
update content_bodies set title = 'けふの下呂温泉', description = '10月16日（土）に開催された「天壌無窮　悪疫退散　下呂温泉花火物語」の様子をお伝えします。『豊作感謝花火』をテーマにした花火が夜空に打ち上げられ、収穫の秋や田園風景をイメージした美しい光景が広がり、多くのお客様に楽しんでいただきました。来週の10月23日（土）にも同様のイベントが予定されています。涼しくなってきたものの、下呂温泉ではまだまだ花火を楽しむことができます。花火の後は温泉で体を温めて、心身ともにリフレッシュしましょう。下呂温泉をよろしくお願いいたします！' where id = 'xMOH5TKSYq0hAN0RNXCOw';
update content_bodies set title = 'Gero Onsen Today', description = 'On October 16th (Saturday), the event ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' took place. The fireworks, themed ''Harvest Gratitude Fireworks,'' were launched into the night sky, depicting the imagery of autumn harvest and rural landscapes, delighting many visitors. Another event is scheduled for next week on October 23rd (Saturday). Although the weather is getting cooler, fireworks can still be enjoyed at Gero Onsen! After the fireworks, warm up in the hot springs! We appreciate your support for Gero Onsen!' where id = 'pm0MKY3jvqY_e-jag1UV3';
update content_bodies set title = 'けふの下呂温泉', description = '涼しさが増し、秋の気配が感じられる下呂温泉を訪れました。紅葉シーズンが近づいており、温泉寺という紅葉スポットに行きましたが、まだ紅葉には早かったようです。しかし、青い葉の中に黄色くなりかけているものが見受けられました。紅葉期間中にはライトアップも予定されており、その様子を動画に収めたいと思っています。また、同じく紅葉スポットである雨情公園にも近々行く予定です。涼しくなると温泉がより一層心地よく感じられます。下呂温泉をよろしくお願いいたします！' where id = 'N_ubQXpqBs1GFvjJxWUhy';
update content_bodies set title = 'Today’s Gero Onsen', description = 'Gero Onsen is feeling cooler, signaling the arrival of autumn. As the season of autumn leaves approaches, I visited one of the popular spots, Onsen-ji Temple. Although it was still early for full autumn colors, I noticed some leaves starting to turn yellow among the green. There are plans for light-up events during the peak of the autumn foliage, and I hope to capture some videos of that. I also plan to visit Ujo Park, another famous autumn spot, for filming soon. As the weather cools, the hot springs feel even more enjoyable. Please continue to support Gero Onsen!' where id = 'FNWsczkE7Qa_CbGZya6px';
update content_bodies set title = 'けふの下呂温泉', description = '10月9日（土）に、精霊流しのイベントがチャップリン像付近で開催されました。精霊流しは、お盆にやってきた精霊を送り返す行事で、今回は紙灯篭を用いましたが、わらや木でつくった舟に供物を乗せて川や海へ流すこともあるそうです。お客様に作っていただいた紙灯篭にはイラストが描かれており、その場で紙灯篭へイラストを描いて作成できるコーナーも設けられ、多くのお客様にご参加いただきました。来年もこの光景が見られるとよいですね。下呂温泉をよろしくお願いいたします！' where id = 'DdyIEJuthWFofXmQY3luA';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On October 9th (Saturday), a spirit sending event was held near the Chaplin statue. The spirit sending ceremony is a tradition to send back the spirits that visit during the Obon festival. This time, paper lanterns were used, but traditionally, offerings are placed on boats made of straw or wood and sent down rivers or out to sea. Guests were able to create their own paper lanterns, which featured illustrations, and there was a corner set up for attendees to draw on the lanterns. Many guests participated in this activity. We hope to see this beautiful scene again next year. Thank you for your support of Gero Onsen!' where id = '89LV6RxcV7g-WkMYActng';
update content_bodies set title = 'けふの下呂温泉', description = '「天壌無窮　悪疫退散　下呂温泉花火物語」が開催されました！今回のテーマは『スポーツ花火』で、スポーツの秋や平和の祭典をイメージした花火が打ち上げられました。参加者の歓声も多く聞かれ、楽しんでいただけたと思います。来週の10月16日（土）にも開催される予定で、次回のテーマは『豊作感謝花火』です。下呂温泉をよろしくお願いいたします！' where id = 'lOwHTxLadbLf1uqT41pQ3';
update content_bodies set title = 'Gero Onsen Today', description = 'The event ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' was held! This time, the theme was ''Sports Fireworks.'' Fireworks inspired by the autumn of sports and the festival of peace were launched. Many cheers from participants were heard, indicating that they enjoyed the event. Another event will be held next week on October 16 (Saturday), so please look forward to it! The next theme will be ''Harvest Gratitude Fireworks.'' We appreciate your support for Gero Onsen!' where id = 'Kh3gHv6QRSxHslrKnb7O8';
update content_bodies set title = 'けふの下呂温泉', description = '「天壌無窮　悪疫退散　下呂温泉花火物語」が再開されました！今回のテーマは『#Light It Blue花火』で、医療従事者への感謝を込めた青を基調とした花火が打ち上げられました。多くのお客様が感染拡大防止対策を徹底しながら花火を楽しむことができました。次回は10月9日（土）にも開催される予定ですので、ぜひお楽しみに！温泉に浸かりながら花火を眺めるのも素晴らしい体験です。下呂温泉へのご支援をよろしくお願いいたします！' where id = 'CbMta3C1KvqQKCJXDn1YB';
update content_bodies set title = 'Gero Onsen Today', description = 'The ''Tenjo Mukyu, Epidemic Dispersal, Gero Onsen Fireworks Story'' has resumed! This time, the theme is ''#Light It Blue Fireworks'', featuring blue-themed fireworks to express gratitude to healthcare workers. Many guests attended while adhering to infection prevention measures, allowing them to enjoy the fireworks safely. Another event is scheduled for October 9th (Saturday), so please look forward to it! Watching fireworks while soaking in the hot springs is a delightful experience! We appreciate your support for Gero Onsen! Visit the Gero Onsen Tourism Association website for more information.' where id = 'qGu1rHpATYbMId2Rmkyy3';
update content_bodies set title = 'けふの下呂温泉', description = '旅行情報雑誌『じゃらん』の公式キャラクター“にゃらん”と下呂温泉がコラボしたグルメが登場！現在、下呂温泉では『にゃらんグルメ』が楽しめます。水明館のロビーラウンジ『エビアン』では、話題のマリトッツォを可愛くアレンジした『にゃらトッツォ』が販売中。もちもちの生地にたっぷりの生クリームが詰まったこのスイーツは、チョコでできた耳とうるうるの瞳が特徴で、見た目も味も楽しめる逸品です。1日先着10食限定で、1人2個まで予約可能。価格は単品660円、ドリンクセット1100円、テイクアウト648円です。販売期間は9月1日から11月30日まで。『にゃらトッツォ』を味わった後は、温泉を楽しみながら他の『にゃらんグルメ』も探してみてください。下呂温泉で素敵な旅行を！' where id = 'sw8J9YiD4Pi-vkNQfKaVi';
update content_bodies set title = 'Today''s Gero Onsen', description = 'The official character of the travel magazine ''Jalan'', ''Nyarann'', collaborates with Gero Onsen for a gourmet experience! Currently, Gero Onsen offers a must-try ''Nyarann Gourmet'' selection. At the lobby lounge ''Evian'' in Suimeikan, you can find the ''Nyarattozzo'', a cute transformation of the popular Italian dessert, Maritozzo, featuring a brioche dough filled with whipped cream. With chocolate ears and sparkling eyes, it''s irresistibly adorable! Limited to 10 servings per day, you can reserve up to two per person. Prices are ¥660 for a single item, ¥1100 for a drink set, and ¥648 for takeout. The ''Nyarann Gourmet'' is available from September 1 to November 30, so don''t miss out! After enjoying the ''Nyarattozzo'', relax in the hot springs and search for more ''Nyarann Gourmet'' options. Visit Gero Onsen for a delightful travel experience!' where id = 'rZnjjGFjO9I9DL6vcJTyJ';
update content_bodies set title = 'けふの下呂温泉', description = '下呂駅から車で約25分の場所にある「初矢峠の石畳」を訪れ、森林浴と軽いウォーキングを楽しむことができます。この石畳は、東美濃と飛騨を結ぶ南北街道の一部で、幅約2メートル、長さ約70メートルが残っています。いつ作られたかは不明ですが、冬の凍結による通行の支障を和らげるために作られたと考えられています。明治24年（1891年）頃まで使用され、別ルートの開拓によりその役割を終えました。歴史を感じながら、同じく歴史ある下呂温泉に入りたくなることでしょう。昔の人々もこの石畳を通って下呂に至り、温泉で疲れを癒したのかもしれません。変わらぬ温泉がここにあります！' where id = 'bJsdyeM0pOzgQfLsD_1WY';
update content_bodies set title = 'Today’s Gero Onsen', description = 'About a 25-minute drive from Gero Station, you can park your car and enjoy forest bathing and light walking while visiting the ''Iwaya Pass Stone Pavement.'' This stone pavement, part of the north-south road connecting East Mino and Hida (also known as Kamakura Road), measures approximately 2 meters wide and 70 meters long, allowing visitors to feel its historical significance. Although the exact date of its construction is unknown, it is believed to have been created to alleviate the difficulties of travel during winter when the mountain pass would freeze. It was in use until around 1891, when its role ended with the development of alternative routes. Reflecting on history, one might feel inclined to soak in the historic Gero Onsen, where travelers of the past likely rested after traversing the Iwaya Pass stone pavement. The timeless hot springs of Gero Onsen await you!' where id = 'XTsstbmzEbL_EV47vE-oI';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉の温泉街に位置する「下呂プリン」は、初のプリン専門店です。店内は湯船をイメージした懐かしい雰囲気が漂っています。国産の卵と牛乳、天然のバニラビーンズを使用した手作りのプリンはどれも絶品で、特に「下呂プリン（レトロ）」は昔ながらの固めのプリンを再現し、素材の味を引き立てています。季節限定の「下呂プリン（マンゴー）」や、地元産の下呂牛乳を使った「下呂プリン（まろやか）」も人気です。また、「下呂プリン（珈琲ゼリー）」はコーヒーゼリーとプリンを混ぜた新しい味わいで、「下呂プリン（抹茶）」は最高級の宇治抹茶を使用し、黒豆の苦味が引き立ちます。「下呂プリン（メロンソーダ）」は懐かしいメロンソーダを再現した一品です。プリンを楽しんだ後は、近くの「鷺の足湯」でリラックスし、そのまま温泉に入るのもおすすめです。' where id = 'RiokuLFcm-5i2ewAJAPDA';
update content_bodies set title = 'Gero Onsen Today', description = 'Located in a corner of the hot spring town, ''Gero Pudding'' is the first pudding specialty shop in Gero Onsen. The shop has an atmosphere reminiscent of a hot spring bath, filled with nostalgic vibes. Each pudding is handmade using domestic eggs, milk, and natural vanilla beans, resulting in exquisite flavors. Notably, the ''Gero Pudding (Retro)'' recreates the traditional firmer pudding that enhances the taste of the ingredients. Seasonal offerings include ''Gero Pudding (Mango),'' which uses juicy mangoes, and the base flavor ''Gero Pudding (Mellow)'' made with local Gero milk. Other varieties include ''Gero Pudding (Coffee Jelly),'' which combines coffee jelly and pudding for a coffee milk taste, ''Gero Pudding (Matcha)'' featuring premium Uji matcha and Tanba black beans, and ''Gero Pudding (Melon Soda),'' which recreates nostalgic melon soda with a cherry on top. After enjoying the pudding, visitors can relax at the nearby ''Sagi Foot Bath'' before heading to the hot springs.' where id = 'M5z6moKfcPQvNext7WxIF';
update content_bodies set title = 'けふの下呂温泉', description = '久々に晴れ間がのぞいた下呂温泉です。気温も一気に高くなっていて、まだまだ夏だと実感します。せっかくの晴天ということで、合掌村へと歩を進め、しばらく体験できなかった「森のすべり台」を堪能しました。全長約175Mというこのすべり台は、スピード感とスリル満点で、吹き付ける風がとても心地よいです。何度でも体験したくなる楽しさで、ついつい2回、3回とすべりたくなりますね。（3歳以上1回100円、別途合掌村入場料（高校生以上800円、小中学生400円）必要）すべり台のあとは温泉にゆきましょう！合掌村内にも「合掌の足湯」があるので、こちらにもぜひ浸かってみてください！レジャーと温泉の街、下呂温泉をよろしくお願いいたします！' where id = 'njj4D1QqY25EtJUH0q_fQ';
update content_bodies set title = 'Today in Gero Onsen', description = 'Gero Onsen has finally seen some sunny weather after a long time. The temperature has risen significantly, reminding us that summer is still here. Taking advantage of the clear skies, I headed to the Gassho Village and enjoyed the ''Forest Slide,'' which I hadn''t experienced in a while. This slide is approximately 175 meters long and offers an exhilarating speed and thrill, with a refreshing breeze that feels wonderful. It''s so much fun that I found myself wanting to slide down multiple times. (The fee is 100 yen per slide for ages 3 and up, plus an entrance fee for Gassho Village: 800 yen for high school students and above, 400 yen for elementary and middle school students.) After sliding, it''s time to relax in the hot springs! There is also a ''Gassho Foot Bath'' within the village, so be sure to try it out! Gero Onsen is a town of leisure and hot springs, so please come and enjoy!' where id = 'DFjS5lbVdKkpahTac43hL';
update content_bodies set title = 'けふの下呂温泉', description = '温泉街から徒歩約10分、いでゆ朝市の近くにある飛騨牛茶寮神月で、素肌美人スイーツを楽しめます。その名も和パフェ「朏」。地元のブランド米「銀の朏」を使ったババロアに、抗酸化作用のあるリコピンたっぷりのトマトジュレ、アイスクリーム、餡子がトッピングされています。酸味と甘みの絶妙なバランスが楽しめる贅沢な和スイーツです。温泉もお忘れなく！湯船で手足を動かすと血行が良くなり、効能がアップすると言われています。安らぎを求めるなら、ぜひ下呂温泉へ！' where id = '6URnkR6dhPKiKZ4NaV3KM';
update content_bodies set title = 'Today''s Gero Onsen', description = 'About a 10-minute walk from the hot spring town, near the morning market, you can enjoy the beautiful skin sweets at Hida Beef Restaurant Kangei. The signature dish is the ''Nagomi'' parfait called ''Mikazuki.'' It features bavarois made from local brand rice ''Gin no Mikazuki,'' topped with tomato jelly rich in lycopene, ice cream, and sweet red bean paste. The perfect balance of acidity and sweetness makes it a luxurious Japanese dessert that delights the palate. You might find yourself reaching for another serving! Don''t forget to enjoy the hot springs as well! Moving your limbs while soaking in the bath is said to improve blood circulation and enhance the benefits. If you''re seeking relaxation, this is the place to be! Please enjoy Gero Onsen!' where id = '8px2xFH6EOBHbs-cZEpU4';
update content_bodies set title = 'けふの下呂温泉', description = '8月21日（土）に開催された「いでゆ夜市サマーフェスティバルin下呂温泉」の様子です。今年最後の開催となり、雨が心配されましたが、開始時間には雨が上がり、多くのお客さんが訪れ、大いに盛り上がりました。新しいひよこのマスコットキャラクター「げろピー」も参加し、あまびえとのツーショットを披露しました。出演者はオカリナ演奏の「エーデルワイス」、ダンスの「ポッケダンスサークル」、バンド「ヨッタリーズ」など、熱のこもったパフォーマンスを行いました。いでゆ夜市に参加してくださった皆様に感謝申し上げます。来年の開催も楽しみにしています。温泉にもぜひお立ち寄りください！イベントも温泉も天下一品です！下呂温泉をよろしくお願いいたします！' where id = 'PdvDxVtTf7mLtLYZuWOsW';
update content_bodies set title = 'Gero Onsen Today', description = 'The ''Ideyu Night Market Summer Festival in Gero Onsen'' was held on August 21st (Saturday). This was the last event of the year, and although there were concerns due to rain, it cleared up by the start time. Many guests attended, creating a lively atmosphere. The new chick mascot ''Gero-Pee'' also participated, showcasing a photo opportunity with Amabie. Performers included the ocarina group ''Edelweiss,'' the dance group ''Pokke Dance Circle,'' and the band ''Yottariz,'' all delivering passionate performances. We would like to express our gratitude to everyone who attended the Ideyu Night Market. We look forward to next year''s event. Don''t forget to enjoy the hot springs when you visit! Both the event and the hot springs are exceptional! Please continue to support Gero Onsen!' where id = 'lKScLsR4xFOHTm-uUIfwN';
update content_bodies set title = 'けふの下呂温泉', description = '下呂駅から徒歩3分のレストラン「Rigolo×Rigolo」で、素肌美人スイーツ「下呂茶ップリン」を楽しめます。このスイーツは、クッキーやアイス、チョコレートでユニークに飾られ、見た目にも楽しめる逸品です。ヨーグルトと甘酒のティラミスと下呂茶プリンの二層仕立てで、美肌効果のあるコウジ酸やカテキン、整腸作用のあるヨーグルトが含まれています。ほどよい甘さと酸味、滑らかな舌触りが特徴です。温泉街の白鷺橋近くで味わうのも良いでしょう。その後は、温泉で美肌効果をさらに高めることができます。入浴時間は額が汗ばむくらいが理想とされています。温泉もスイーツも素晴らしい下呂温泉をぜひお楽しみください！' where id = '5zyeH4UOO3p_31F8lVscI';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Just a 3-minute walk from Gero Station, you can enjoy the beautiful skin dessert ''Gero Chappurin'' at the restaurant ''Rigolo×Rigolo''. This unique dessert is decorated with cookies, ice cream, and chocolate, making it visually appealing as well. It features a two-layer structure of yogurt and sweet sake tiramisu, combined with Gero tea pudding, which is said to promote beautiful skin due to the presence of kojic acid and catechins, along with the digestive benefits of yogurt. The perfect balance of sweetness and acidity, along with its smooth texture, makes it a must-try! It would be delightful to enjoy this treat near the Chaplin statue on the Shirakabe Bridge in the hot spring town. Afterward, you can enhance the beauty benefits gained from ''Gero Chappurin'' by soaking in the hot springs. It is said that the ideal bathing time is when you start to sweat on your forehead. Both the hot springs and the sweets are exceptional! Please enjoy Gero Onsen!' where id = 'xNYpU6vkmjKroyCfMMLmJ';
update content_bodies set title = 'けふの下呂温泉', description = '雨の中の下呂温泉でしたが、現在は小雨程度になり、雲の間から陽光も見えてきました。温泉街には被害がなく、暑さも和らいでいます。今日は下呂駅から徒歩15分の温泉寺へ向かいました。静寂に包まれ、雨音だけが聞こえる中、境内をじっくりと回ることができました。温泉寺は、かつて温泉の湧出が止まった際、白鷺が源泉の場所を教えてくれたことから始まったと言われています。白鷺を探しましたが、姿は見えず、また探しに来ようと思います。伝説を聞いた後の温泉は格別です！じめじめを吹き飛ばしましょう！下呂温泉をよろしくお願いいたします！' where id = 'gKXhmN9xXSPEQqfo-WjvE';
update content_bodies set title = 'Today at Gero Onsen', description = 'Despite the rain at Gero Onsen, it has now lightened to a drizzle, and sunlight is breaking through the clouds. There has been no damage to the hot spring town, and the heat has eased, making it more comfortable as the humidity decreases. Today, I walked to Onsen-ji Temple, a 15-minute walk from Gero Station. The temple was enveloped in tranquility, with only the sound of rain accompanying my exploration of the grounds. Onsen-ji is said to have been established when a white heron, believed to be a messenger of Yakushi Nyorai, revealed the source of the hot spring when it had stopped flowing. I looked for the heron, but it was nowhere to be found, perhaps sheltering from the rain. I plan to return to search for it again. After hearing such legends, soaking in the hot springs feels even more special! Let''s blow away the recent humidity! Gero Onsen is rich in history and gratitude!' where id = 'ol3wyMJWapxXXn23OOdXg';
update content_bodies set title = 'けふの下呂温泉', description = '今日は少し遠出をして、下呂温泉街から車で約20分の萩原町にある諏訪神社を訪れました。この神社は鎌倉時代にできたとされ、かつての諏訪城の城壁跡も残っています。広々とした境内には高い木々が茂り、木陰で暑さを和らげながらゆっくりと見回ることができました。昔話によると、築城中に現れたへびが片目をつぶされて追い払われた後、梅が育たなくなったと言われています。そのへびは諏訪明神の使いともされ、今でも神社周辺に住んでいるそうです。探してみましたが、へびの姿は見つけられず、暑さに参ってどこかで涼んでいたのかもしれません。歴史と昔話、温泉がたっぷり詰まった街、下呂温泉をよろしくお願いいたします！' where id = '9w_E_GIVVxetwY0i8SapS';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, I took a short trip to Suwa Shrine in Hagiwara Town, about 20 minutes by car from Gero Onsen. This shrine, believed to have been established during the Kamakura period, features remnants of the former Suwa Castle walls. The interior is spacious, with tall trees providing shade and relief from the heat, allowing for a leisurely exploration. According to an old tale, a snake appeared during the castle''s construction, and after being driven away with one eye injured, plum trees ceased to grow in the area. This snake is said to be a messenger of Suwa Myojin, and it is rumored that a one-eyed snake still resides around the shrine. I searched for it but couldn''t find it, perhaps it was hiding from the heat. Reflecting on the past made me crave a soak in the hot springs. It''s possible that the snake from Suwa Shrine has also enjoyed the hot springs in secret. A town rich in history, folklore, and hot springs! Please visit Gero Onsen!' where id = '91yKgzBckCJQLqh9WWMfp';
update content_bodies set title = '大淀ふれあいキャンプ場（三重県明和町）｜【公式】観光三重', description = '三重県明和町の海沿いに位置する大淀ふれあいキャンプ場は、美しい自然に囲まれたアウトドアスポットで、海釣りも楽しめます。テントのほか、エアコン完備のバンガローやカーサイトもあり、アウトドア初心者でも気軽にキャンプを楽しむことができます。夏にはキャンプ場の目の前に広がる真っ青な海での海水浴が人気で、遠浅で波も穏やかなため、子ども連れの家族にも最適です。バーベキュー食材セットの予約も可能です。また、伊勢、鳥羽、志摩などの人気観光地にも近く、家族の思い出作りにおすすめのキャンプ場です。' where id = 'cR219_OC_a6sqUk4ADwcu';
update content_bodies set title = 'Oyodo Fureai Campground (Meiwa Town, Mie Prefecture) | Official Mie Tourism', description = 'Located along the coast in Meiwa Town, Mie Prefecture, Oyodo Fureai Campground is a recommended leisure spot surrounded by beautiful nature, perfect for outdoor activities and sea fishing. The campground offers not only tents but also air-conditioned bungalows and car sites, making it accessible for beginners to enjoy camping. In summer, the clear blue sea right in front of the campground is popular for swimming, ideal for families with children due to its shallow waters and calm waves. Barbecue ingredient sets can also be reserved. The campground is close to popular tourist destinations in Mie Prefecture, such as Ise, Toba, and Shima, making it a great place for family memories.' where id = 'IsYc4SbQqVHO78B-Z3Maj';
update content_bodies set title = '伊勢神宮から生中継した「介護施設向けオンラインツアー」アーカイブ動画', description = '2021年2月25日、伊勢神宮の内宮前から介護施設向けのオンラインツアーが生中継されました。このツアーは三重県と東京トラベルパートナーズ株式会社の協力により実現しました。当日は北海道から沖縄まで、7000名以上の参加者が高画質で参加型の「旅」を楽しみました。伊勢神宮（内宮）編では収録映像も交えられました。専用視聴システムのチャットを通じて、参加者からの質問にリポーターが答えたり、「どのおみくじを引きますか？」といったアンケートを行ったりすることで、参加者が積極的に関与できるオンラインツアーとなりました。' where id = '892qW-6KUcLsNSAHq4hlS';
update content_bodies set title = 'Live Broadcast of Online Tour for Nursing Facilities from Ise Jingu Archive Video', description = 'On February 25, 2021, an online tour for nursing facilities was live broadcasted from in front of Ise Jingu''s Naiku. This tour was organized by Mie Prefecture in collaboration with Tokyo Travel Partners Co., Ltd. On the day of the event, over 7,000 participants from Hokkaido to Okinawa enjoyed a high-quality, interactive ''journey'' through the live broadcast. The Ise Jingu (Naiku) segment included recorded footage. Participants could engage through a dedicated viewing system''s chat, where reporters answered questions and conducted polls, such as ''Which omikuji would you like to draw?'' This made the online tour a participatory experience.' where id = 'Z8E3GXwiKNel8EWjfEfWz';
update content_bodies set title = 'オール三重で進める安全・安心な観光地づくりの取り組み～三重の観光ニューノーマル推進事業のご紹介～', description = '三重県では、旅行者が安心して楽しめる観光地づくりを目指し、「安全・安心な観光づくりのための三重の観光ニューノーマル推進事業」を進めています。この取り組みでは、観光事業者への感染症対策アドバイザーの派遣や、三重の自然を活用したワーケーションや自然体験プログラムを提供しています。また、安全・安心な観光を実現するための事例集も作成されており、観光業界の感染症対策の徹底を図っています。' where id = 'WysShArtirn9w46nsHTMV';
update content_bodies set title = 'Initiatives for Creating Safe and Secure Tourist Destinations in Mie - Introduction to Mie''s New Normal Tourism Promotion Project', description = 'Mie Prefecture is committed to creating a safe and secure tourism environment for travelers through the ''Mie''s New Normal Tourism Promotion Project.'' This initiative includes the dispatch of infection control advisors to tourism businesses to ensure thorough infection prevention measures. Additionally, it offers unique programs that utilize Mie''s natural environment for workation and nature experiences. The project aims to provide travelers with a reassuring experience, and a collection of case studies has been created to offer insights into continuing safe and secure tourism practices.' where id = '5keWiIjsk5VOop3zzgyzr';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉を代表する老舗旅館、水明館のロビーラウンジ「エビアン」で、素肌美人スイーツの「下呂シューパルフェ」を楽しむことができます。このスイーツは、甘酒や抹茶スポンジ、フレークを使った5層の上に、贅沢なクッキーシューがのっています。地元産の素材で作られたカスタードクリームやシューには、肌に良いアミノ酸が豊富に含まれています。一口ごとに異なる甘みと食感が楽しめ、やみつきになる美味しさです。食べ終わったら、そのまま温泉へ直行し、水明館の温泉に浸かり、湯上りに再度「下呂シューパルフェ」を味わうのもおすすめです。温泉とスイーツを同時に楽しめるのは下呂温泉ならではの魅力です。' where id = 'z95-wYKewWRBLPUXj15A4';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Let''s visit the lobby lounge ''Evian'' of the long-established ryokan Suimeikan, a representative of Gero Onsen, to enjoy one of their beautiful skin sweets, the ''Gero Shoe Parfait.'' This impressive dessert features five layers made with plenty of sweet sake, matcha sponge, and flakes, topped with a luxurious cookie shoe. The custard cream and shoe are made from locally sourced ingredients and are rich in amino acids, essential for creating beautiful skin. Each bite offers a different sweetness and texture, making it irresistibly delicious. After finishing it, you can head straight to the hot springs! It’s a great idea to soak in Suimeikan''s onsen and enjoy another ''Gero Shoe Parfait'' afterward. Enjoying both hot springs and sweets is a unique experience at Gero Onsen!' where id = 'V41ZUeIGmVpcLR7KcIFtx';
update content_bodies set title = 'けふの下呂温泉', description = '7月31日（土）に「いでゆ夜市サマーフェスティバルin下呂温泉」が開催されました。天候に恵まれ、前回以上に盛り上がりました。出店で販売されているドリンクやスナックを楽しみながら、チアダンスの「ユニークスタイルクラブデリシャス」、女性太鼓の「華響」、子供太鼓の「龍神子供太鼓」などの素晴らしいパフォーマンスを観覧しました。どの演技も素晴らしく、あっという間に時間が過ぎました。次回は8月7日（土）に開催予定ですので、ぜひお越しください。夜市を楽しんだ後は、温泉でリフレッシュしましょう。次回の開催が待ち遠しいです！下呂温泉をよろしくお願いいたします！' where id = 'zh_CzrCeq_Qqj2piybth6';
update content_bodies set title = 'Gero Onsen Today', description = 'The ''Ideyu Night Market Summer Festival in Gero Onsen'' was held on July 31st (Saturday). The weather was favorable, leading to an even more lively atmosphere than before. Attendees enjoyed drinks and snacks from various stalls while watching impressive performances by the cheer dance group ''Unique Style Club Delicious,'' the women''s taiko group ''Hanakyo,'' and the children''s taiko group ''Ryujin Kodomo Taiko.'' Each performance was captivating, making time fly by. Another event is scheduled for August 7th (Saturday), so everyone is encouraged to attend. After enjoying the night market, visitors can relax in the hot springs. The anticipation for the next event is already building! Gero Onsen offers the best of both events and hot springs!' where id = 'jk9zkpivggTrKRrkj1yy6';
update content_bodies set title = 'けふの下呂温泉', description = '「下呂温泉　素肌美人スイーツ」に舌鼓をうちましょう。今日お邪魔したのは「GEROGEROみるくスタンド」さん。地元飛騨の下呂牛乳を100％使用したドリンクやスイーツが並ぶ店内で、「飛騨りんごと馬瀬のとちみつのスムージー」を注文しました。濃厚なミルクのスムージーに、飛騨りんごの爽やかな酸味がトッピングされ、肌に嬉しいビタミンB2が豊富な馬瀬産のとちみつも入っています。一口飲むと、ひんやりしたミルクスムージーにリンゴの食感と酸味が加わり、口の中はまさに口福です。他にも様々なスイーツがあり、ぜひ味わってみたくなりました。温泉あがりに飲むのも良し、入る前に飲むのも良しで、温泉とも相性抜群のスイーツです！スイーツと温泉のコラボレーションが楽しめる街、下呂温泉をよろしくお願いいたします！' where id = 'rcURJS3Ykree1VbugUuWH';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Let''s indulge in the ''Gero Onsen Skin Beauty Sweets.'' Today, I visited ''GEROGERO Milk Stand,'' which offers drinks and sweets made from 100% local Gero milk. I ordered the ''Hida Apple and Mase Honey Smoothie.'' This rich milk smoothie is topped with the refreshing acidity of Hida apples and includes Mase honey, which is rich in skin-friendly vitamin B2. With the first sip, the cool milk smoothie combined with the texture and acidity of the apple creates a delightful experience. There are various other sweets available that I am eager to try. It''s perfect for cooling down after a hot spring bath or enjoying before entering the onsen, making it a great match for the hot springs. Gero Onsen is a town where you can enjoy the collaboration of sweets and hot springs!' where id = 'IRJqcSsOZ4I-nD9pWrynw';
update content_bodies set title = 'けふの下呂温泉', description = '飛騨川沿いの遊歩道を散策しました。川沿いのため、暑い日でも涼しく歩くことができました。しばらく歩くと、「塚田の渡し」と書かれた石碑に出会いました。調べると、奈良時代から重要な渡し船の拠点だったことがわかりました。大正時代に六ツ見橋ができてからは廃止され、その名残が残っています。対岸にも同様の石碑があるようですが、今回は気づかず通り過ぎてしまいました。次回はぜひ見に行きたいと思います。過去を思いながら温泉に浸かるのもまた一興ですね。下呂温泉をよろしくお願いいたします！' where id = 'yucLngRA-u3jiVugYP3uH';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I took a stroll along the promenade by the Hida River. Thanks to its riverside location, I was able to enjoy a refreshing walk even in the heat. After walking for a while, I came across a stone monument that read ''Tsukada no Watashi.'' Upon researching, I found that it had been an important ferry point since the Nara period. It was discontinued after the construction of the Mutsumi Bridge in the Taisho era, leaving behind some remnants. There seems to be a similar monument on the opposite bank, which I unfortunately passed by this time without noticing. I hope to visit it next time. Reflecting on the past while soaking in the hot springs is also a delightful experience. I look forward to Gero Onsen!' where id = 'Ou8LuoPEnpWjL8Thiqq7J';
update content_bodies set title = '伊勢忍者キングダム(旧伊勢安土桃山城下街)｜観光三重｜三重県の観光・旅行情報', description = '伊勢安土桃山城下街では、「忍法！むささびの術」という新しいアトラクションが登場しました。広い場内をワイヤーでつなぎ、ジップラインで駆け抜けることができます。忍者衣装に変身して空を飛ぶことで、忍者気分を楽しむことができます。このアトラクションは、地元の役者である斉藤やすさんと伊藤廣道さんによって紹介されました。' where id = '5Na-Qyy_BmAsD0I9tu46A';
update content_bodies set title = 'Ise Ninja Kingdom (Former Ise Azuchi Momoyama Castle Town) | Mie Prefecture Tourism', description = 'Ise Azuchi Momoyama Castle Town features a new attraction called ''Ninja Technique! Musasabi no Jutsu,'' where visitors can zip line across the expansive grounds. Dressed in ninja costumes, guests can experience the thrill of soaring through the air like a ninja. The attraction was introduced by local actors Yasushi Saito and Hiroshi Ito.' where id = 'fmzjmbBIPpCfdSmfjT8N-';
update content_bodies set title = 'けふの下呂温泉', description = '7月24日（土）に開催された「いでゆ夜市サマーフェスティバルin下呂温泉」の動画です。コロナ禍の影響で例年より規模を縮小しましたが、活気に満ちた2時間でした。この日は「龍神子供太鼓」と「飛騨萩原御前太鼓」の2チームが参加し、素晴らしい太鼓演奏を披露しました。出店では飛騨牛コロッケや手羽先が販売され、来場者は美味しさに舌鼓を打っていました。次回は7月31日（土）で、その後も毎週土曜日に8月7日、14日、21日に開催されます（雨天の場合は中止）。祭りと温泉の街、下呂温泉をよろしくお願いいたします！' where id = '5DQ3gkzpMNIgLLCqHlzQF';
update content_bodies set title = 'Gero Onsen Today', description = 'This is a video of the ''Ideyu Night Market Summer Festival in Gero Onsen'' held on July 24th (Saturday). Due to the COVID-19 pandemic, the event was scaled down compared to previous years, but it was filled with energy and excitement for two hours! On this day, two teams, ''Ryujin Kodomo Taiko'' and ''Hida Hagiwara Gozen Taiko,'' performed impressive taiko drumming. Food stalls offered Hida beef croquettes and chicken wings, delighting the attendees. The next event will be on July 31st (Saturday), followed by weekly events on August 7th, 14th, and 21st (Saturdays). The festival may be canceled in case of rain. We appreciate your support for Gero Onsen, a town of festivals and hot springs!' where id = '3oS-YwxWVo8iWr28c0D3F';
update content_bodies set title = 'けふの下呂温泉', description = '夕焼け空に染まる下呂温泉の美しさを伝えています。夕陽に照らされた街や川は非常に美しく、太陽が沈むにつれて周囲の景色も変わっていく様子は、まさに自然の芸術のようでした。もう少し早く撮影していれば、また違った風景が見られたかもしれません。次回はその機会を狙いたいと思います。その前に、夕焼けを眺めながら温泉に浸かる予定です。夕焼け空を見ながらの露天風呂は格別で、昼夜を問わず楽しめる下呂温泉の魅力を再確認しました。' where id = '97I7dJePkjVD6JVDYutvP';
update content_bodies set title = 'Gero Onsen Today', description = 'Gero Onsen is beautifully colored by the sunset sky. The town and river, illuminated by the setting sun, were stunning. As the sun gradually sank, the surrounding scenery transformed, creating a moment that felt like a natural work of art. I realized that if I had taken photos a bit earlier, I might have captured a different landscape. I look forward to trying again next time. Before that, I plan to enjoy the hot springs while being watched over by the sunset! Soaking in an outdoor bath while gazing at the sunset sky is truly exceptional! Gero Onsen is a place to enjoy at any time of day or night!' where id = '6chkgdH4jJJ0P259SfUsA';
update content_bodies set title = 'けふの下呂温泉', description = '夜の下呂温泉を散策しました。昼間とは異なる雰囲気で、慣れた道も新しい場所のように感じられました。田の神の足湯は静かで、足をつけると落ち着きました。街灯のおかげで暗すぎず、安心して腰を下ろせました。散策の後は温泉に入り、足湯も温泉も最高でした。毎日入りたいと思います。昼も夜も楽しめる下呂温泉をよろしくお願いいたします。' where id = 'ZyeBlIFDzJ9wKM24rll6Y';
update content_bodies set title = 'Evening Stroll in Gero Onsen', description = 'The atmosphere of Gero Onsen at night is distinctly different from during the day, making familiar paths feel like new places. The foot bath at Tanokami, which I have used many times, was peaceful, and soaking my feet brought a sense of calm. The streetlights provided enough illumination to feel safe while sitting down. After my stroll, I enjoyed the hot springs, and both the foot bath and the onsen were fantastic—something I would love to experience every day! Gero Onsen is enjoyable both day and night.' where id = 'r5VEpDSfElAY_2vgHbmsz';
update content_bodies set title = 'けふの下呂温泉', description = '高台から見渡す下呂温泉の風景は素晴らしく、山の向こうまで簡単に行けそうな気がします。普段通り過ぎる場所も、違った視点から見ると新鮮に感じます。晴れ間が見え、陽光が強いですが、空には大きな雲が集まっており、雨が降りそうな雰囲気です。そんな時は、雨宿りがてら温泉に入るのが一番です。雨が止むまで、のんびりと温泉を楽しみましょう。どんな天気でも、下呂温泉の素晴らしい体験が待っています！' where id = '7EierNgswhb6fTQ9X5xz9';
update content_bodies set title = 'Today''s Gero Onsen', description = 'The view of Gero Onsen from a high vantage point is breathtaking. It feels as if one could easily reach the mountains beyond. Even familiar places appear different from this perspective. Although the sun is shining brightly, large clouds are gathering in the sky, suggesting that rain may come soon. In such weather, the best option is to enjoy the hot springs while waiting for the rain to stop. No matter the weather, the exceptional hot springs of Gero Onsen await you!' where id = 'JT1q3fqPYUTZ3uJCjnQrp';
update content_bodies set title = 'けふの下呂温泉', description = 'またまたスイーツを求めて、幸月本家さんへお邪魔しました。お目当ては下呂温泉素肌美人スイーツのひとつ、“和”ＭＯＲＩ盛りパフェ。和の素材をふんだんに取り入れた特製スイーツで、イソフラボンやビタミンＣといった美肌に欠かせない栄養素もたっぷり。和と洋、果物の甘さのぜいたくなコラボレーションに、スプーンが止まらずあっという間に食べ終えてしまいました。そのあと温泉に入っている間にも、その味が忘れられませんでした！明日にでもまた食べにいきたいですね！美肌とスイーツといえば下呂温泉！よろしくお願いいたします！' where id = '-rgQYVS7t6F8wtVh0xOx0';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I visited Kougetsu Honke again in search of sweets. My target was the ''Wa'' MORI parfait, one of the Gero Onsen beautiful skin sweets. This special dessert incorporates plenty of Japanese ingredients and is rich in essential nutrients for beautiful skin, such as isoflavones and vitamin C. The luxurious collaboration of Japanese and Western flavors, along with the sweetness of fruits, made it impossible to stop eating, and I finished it in no time. Even while soaking in the hot spring afterward, I couldn''t forget the taste! I want to go back and have it again tomorrow! When it comes to beautiful skin and sweets, Gero Onsen is the place to be!' where id = 'x_JRSRe7j5EBuNwCHcb3G';
update content_bodies set title = 'けふの下呂温泉', description = 'スイーツを求めて、幸月本家さんへお邪魔しました。和菓子も洋菓子も扱っているお店で、どのお菓子もとてもおいしそうです。今日は、おまんじゅうのげろじまんと幸月の生どらを賞味。どちらも絶品でしたが、より印象に残ったのは生どらでした。ふかふかの生地に、生クリームとつぶあんがミックスされていて和と洋のコラボレーションを一度に味わえます。思わず二つ目に手が伸びてしまいそうでした。甘いもののあとは温泉へ入りたくなりますね！テイクアウトして、温泉あがりに食べるのもおいしそうです！下呂温泉をよろしくお願いいたします！' where id = 'bgsQ0c6QMHhRAploLlRTp';
update content_bodies set title = 'Today''s Gero Onsen', description = 'I visited Kougetsu Honke in search of sweets. This shop offers both Japanese and Western confections, all of which look delicious. Today, I tried the ''Gero-jiman'' steamed bun and the ''Kougetsu''s fresh dorayaki.'' Both were exquisite, but the fresh dorayaki left a stronger impression on me. The fluffy dough combined with fresh cream and sweet red bean paste creates a delightful fusion of Japanese and Western flavors. I found myself wanting a second one! After enjoying sweets, I felt the urge to relax in the hot springs. Taking them to enjoy after a soak in the onsen sounds delightful! Please take care of Gero Onsen!' where id = 'XoL-6oNk2dGRMc5uCXyZy';
update content_bodies set title = 'けふの下呂温泉', description = '7月3日（土）に開催された「天壌無窮 悪疫退散 下呂温泉花火物語」では、七夕花火をテーマに、彦星と織姫の再会を祝う見事な花火が打ちあがりました。天候にも恵まれ、迫力ある花火が間近で楽しめ、色とりどりの美しい花火に心を奪われました。花火の後は温泉に入り、花火と温泉の贅沢な組み合わせはやみつきになりそうです。下呂温泉をよろしくお願いいたします！' where id = 'KfXEMGmf27-ExZH5FCZL1';
update content_bodies set title = 'Gero Onsen Today', description = 'On July 3rd (Saturday), the Gero Onsen Fireworks Festival was held, themed ''Tanabata Fireworks'' to celebrate the reunion of Hikoboshi and Orihime. The weather was favorable, allowing for a spectacular display of fireworks that felt incredibly close, creating a thrilling experience. The colorful fireworks were beautiful, making spectators want to watch them endlessly. After the fireworks, it was natural to enjoy the hot springs. The luxurious combination of fireworks and hot springs is sure to become addictive! Both the hot springs and fireworks are eternal! Please support Gero Onsen!' where id = 'WiFLtCWLVYFWRxECkmLs1';
update content_bodies set title = 'けふの下呂温泉', description = '暮れ時の下呂温泉の様子を描写しています。夕焼けには出会えませんでしたが、見慣れた風景が新鮮に感じられました。街灯の光も普段より明るく、安心感を与えてくれました。その後、さるぼぼ七福神社内のさるぼぼ黄金の足湯へ向かい、豪華な外装に囲まれながら足湯を楽しみました。運気が上がっていくように感じ、さらに温泉に入って運気を高めようと決意しました。運気UPの下呂温泉を楽しみたいと思います！' where id = 'c6A1DlcZWkhgqkeCN1g-l';
update content_bodies set title = 'Today at Gero Onsen', description = 'This is a description of Gero Onsen during the evening. Although I didn''t encounter a sunset, the familiar scenery appeared refreshingly new. The streetlights seemed brighter than usual, providing a comforting feeling. I then headed to the Sarubobo Seven Lucky Gods Shrine, where I enjoyed a foot bath at the Sarubobo Golden Foot Bath. Surrounded by the luxurious decor inspired by the Sarubobo and gold, I felt my luck increasing. To further enhance my fortune, I decided to take a dip in the hot spring. Here''s to the luck-boosting experience at Gero Onsen!' where id = 'g2OYeZPcM50WMbo4fFh2l';
update content_bodies set title = 'けふの下呂温泉', description = '今日は下呂温泉の足湯、ゆあみ屋さんにお邪魔しました。ゆったりと腰をおろせるスペースで、ほど良い温かさのお湯に浸かりながらリラックスできました。お店ではお土産やドリンク、スイーツが販売されており、それを片手に足湯を楽しむのもおすすめです。次回はそのスイーツを味わってみたいと思います。たくさんの種類があり、どれもおいしそうで目移りしてしまいます。足湯を楽しんだ後は、温泉にも入りたくなりました！足湯と温泉、スイーツ！下呂温泉をよろしくお願いいたします！' where id = 'TjZUsvg0UHneEqnQvvlSs';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, I visited the foot bath at Yuyamiya in Gero Onsen. The space allows for a relaxing experience as you sit back and soak in the pleasantly warm water. The shop offers souvenirs, drinks, and sweets, making it a great idea to enjoy the foot bath while savoring a treat. I am looking forward to trying the sweets next time, as there are many delicious options that are hard to choose from. After enjoying the foot bath, I felt the urge to take a dip in the hot spring! Foot baths, hot springs, and sweets—please enjoy Gero Onsen!' where id = '1GDK4huqc2scDGuo0sujj';
update content_bodies set title = 'けふの下呂温泉', description = '雨上がりの下呂温泉を散歩しました。街のあちこちにあじさいの花が咲いており、青や紫の花が多く見られます。しらさぎ緑地は雨の後、より緑が映えていました。晴れの日の散策も良いですが、こうした中を歩くのも趣があって楽しいです。こういう日は温泉に入って気分一新するのが最高です。雨音を聞きながら温泉に浸かるのも良い感じです。晴れの日も雨の日も温泉三昧を楽しみましょう！' where id = 'cUI_i3_eCthFIa296xD-9';
update content_bodies set title = 'Today in Gero Onsen', description = 'I took a walk in Gero Onsen after the rain. Hydrangeas are blooming all over the town, with many blue and purple flowers. What colors do you prefer? The Shirakawa Green Space looked even greener after the rain. While walking on sunny days is nice, strolling in this weather has its own charm. On such days, soaking in the hot springs is the best way to refresh oneself! Listening to the sound of rain while enjoying the hot springs is quite pleasant. Whether it''s sunny or rainy, indulging in the hot springs is wonderful! Please enjoy Gero Onsen!' where id = 'kenBel0v9uRVG-mYSYMys';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～ダイジェスト版', description = '熊野古道は、日本各地から和歌山県の熊野三山（熊野速玉大社、熊野那智大社、熊野本宮大社）を目指して歩かれた古道です。「熊野古道伊勢路」は、伊勢神宮と熊野三山を結ぶ世界遺産の巡礼路であり、その歴史と魅力が紹介されています。語り部は、自然の中に神々が存在し、岩や木、水の流れにも神が宿ると語り、日本人が感じる神様の力を強調しています。この道を歩くことで、神々とのつながりを感じることができるとされています。' where id = '_9C8uf_GWvYvKRkp06SM1';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Digest Version', description = 'The Kumano Kodo is an ancient pilgrimage route that leads from various regions of Japan to the Kumano Sanzan (Kumano Hayatama Taisha, Kumano Nachi Taisha, and Kumano Hongu Taisha) in Wakayama Prefecture. This route, known as ''Kumano Kodo Iseji,'' connects two of Japan''s major sacred sites: Ise Jingu and the Kumano Sanzan. The narrative emphasizes the spiritual connection between nature and the divine, highlighting how Japanese people perceive gods in natural elements like rocks, trees, and flowing water. The description invites readers to explore the history and allure of this UNESCO World Heritage pilgrimage path.' where id = 'qEEkRNyJ27_EjXcYtRrC7';
update content_bodies set title = 'けふの下呂温泉', description = '街を歩いていると、おいしそうな匂いにつられて、GEROGERO BUTTER STANDに引き寄せられました。店内には自家製バターや様々な品物が並び、おしゃれな外装や車のオブジェ、バターミルクの足湯などが目を引きます。持ち帰り可能なお菓子や食べ物、ドリンクも販売しており、この日はサクサクのクッキーとぜいたくなバタークリームのバターサンドを楽しみました。また、かつおぶしがアクセントの焼きおにぎりも美味しかったです。他の商品も試してみたいです。お土産を買い、足湯を楽しんだ後は温泉へ行きましょう！下呂温泉をよろしくお願いいたします！' where id = 'g28UgZLrI92JRimZF__-1';
update content_bodies set title = 'Today''s Gero Onsen', description = 'While walking through the town, I was drawn to GEROGERO BUTTER STAND by a delicious aroma. Inside the shop, there were homemade butters and various items on display, along with stylish decor, car sculptures, and a buttermilk foot bath that caught the eye. They sell take-home snacks, food, and drinks, including crispy cookies and luxurious butter cream butter sandwiches. I also enjoyed grilled rice balls with a delightful aroma of butter and soy sauce, accented with bonito flakes. I look forward to trying more products. After buying souvenirs, filling my stomach, and enjoying the foot bath, it''s time to head to the hot springs! Please take care of Gero Onsen!' where id = 'sEVVm-GBR-8l1DOBIqhFk';
update content_bodies set title = 'けふの下呂温泉', description = '下呂発温泉博物館を訪れました。館内には温泉を科学と文面から紹介するコーナーがあり、楽しくわかりやすく温泉について学べます。意外な発見や温泉に関連する産業の解説もあり、時間を忘れてしまうほどです。学んだ後は、館内の足湯でリラックスしましょう。熱いお湯と冷たい水で構成され、歩行浴を楽しめます。温度差と運動によって血行が促進され、頭脳にも健康にも良い施設です。さらに滋養するために温泉へ行くことをお勧めします。全身を浸かることで、効果がさらに高まるかもしれません。頭脳と健康のお供に下呂温泉をぜひご利用ください！' where id = 'xlXwpdQlcu_Kib2wwHPDn';
update content_bodies set title = 'Today at Gero Onsen', description = 'I visited the Gero Onsen Museum. Inside, there is a section that introduces hot springs through science and literature, making it enjoyable and easy to learn about them. There are also explanations about surprising discoveries and industries related to hot springs, which can make you lose track of time. After learning, you can relax in the foot bath located in the museum. It consists of hot water and cold water, allowing you to enjoy a walking bath. The temperature difference and movement promote blood circulation, benefiting both your mind and health. To further nourish yourself, a visit to the hot springs is recommended! Soaking your whole body may enhance the effects even more. Gero Onsen is a great companion for your mind and health!' where id = '-UdGiTR7YdsHe0aP-3hWw';
update content_bodies set title = 'けふの下呂温泉', description = '6月26日（土）に行われた「天壌無窮　悪疫退散　下呂温泉花火物語」の花火の様子をお伝えします。下呂大橋からの眺めは素晴らしく、夜空に咲く花火はとても美しかったです。打ち上げ時間は約10分でしたが、もっと長く続いてほしいと感じました。色とりどりの花火はまるで生き物のようでした。花火は9月4日（土）まで毎週土曜日に開催される予定で、次回は7月3日（土）夜8時30分からです。花火の後は温泉でゆっくりとくつろぎましょう。夏の土曜日は下呂温泉でお楽しみください！' where id = 'sVpVWEK7i__JD6oCoW1Si';
update content_bodies set title = 'Gero Onsen Fireworks', description = 'On June 26th, the ''Tenjō Mukyū, Epidemic Dispersal, Gero Onsen Fireworks Story'' showcased beautiful fireworks from the Iideyu Bridge. The display lasted about 10 minutes, leaving viewers wanting more. The colorful fireworks resembled living creatures in the night sky. Fireworks will continue every Saturday until September 4th, with the next show scheduled for July 3rd at 8:30 PM. After enjoying the fireworks, visitors can relax in the hot springs. Summer Saturdays at Gero Onsen are highly recommended!' where id = 'X7tgHhTiRIIQ9TXhKDLRT';
update content_bodies set title = 'けふの下呂温泉', description = '今日は鷺の足湯へ行ってみました。下呂温泉で最初に誕生した足湯で、ヒノキ造りの湯船と屋根があり、じっくりとつかることができます。その前に、すぐそばにある加恵瑠神社へお参りするのもいいですね。たくさんのかえるたちが出迎えてくれます。足湯につかると、ぽかぽかしてなんだか眠くなってきます……夢に出てきたのは鷺とかえると温泉！これは吉兆！温泉へ行きましょう！温泉と神秘に彩られた下呂温泉をよろしくお願いいたします！' where id = 'FHOZS0ewuToKubmN0UBKM';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, I visited the Sagi foot bath, the first foot bath established in Gero Onsen. It features a cypress wood bath and a roof, allowing for a relaxing soak. Before that, it''s nice to visit the nearby Kaeru Shrine, where many frogs greet you. Soaking in the foot bath makes me feel warm and a bit sleepy, leading me to dream of herons, frogs, and hot springs! This is a good omen! Let''s head to the hot springs! Please enjoy the mystique and charm of Gero Onsen!' where id = 'GbqeKSZhS-SK4IsYgZlTf';
update content_bodies set title = 'けふの下呂温泉', description = '晴れ間から雲が出て、現在はしとしと雨降りの下呂温泉です。雨が降る前に、乗政にあるしだれ栗の群生地へ遠出しました。この群生地は全国でも数か所しかない希少なもので、100年を超える個体もあり、濃い緑が美しかったです。遠出の後は温泉に入るのが一番で、温泉パワーでしだれ栗のような長寿を願っています。下呂温泉をよろしくお願いいたします！' where id = 'L3z4zNG0-Aav_GRqpsPAv';
update content_bodies set title = 'Today''s Gero Onsen', description = 'The weather in Gero Onsen has changed from a sunny afternoon to a gentle rain. Before the rain started, I took a trip to the Shidare Kuri grove in Norimasa, known for its drooping branches. This rare grove, one of only a few in the country, features chestnut trees that are over 100 years old, showcasing beautiful deep green foliage. After such an outing, there''s nothing better than soaking in the hot springs. May the power of the onsen grant us longevity like the Shidare Kuri!' where id = 'nPMqJMgEgM4WY21L1YasG';
update content_bodies set title = 'けふの下呂温泉', description = '納涼を求めて歩いているうちに、いつの間にか雨情公園にたどり着きました。暑い中でも川のせせらぎのおかげで涼しい空気に包まれ、流した汗も引いて散策には最適です。泳ぐには支障がありそうですが、手を浸すと涼しさが全身に広がります。この後は温泉に入れば、暑さも吹っ飛ぶでしょう。下呂温泉をよろしくお願いいたします！' where id = '4-GeHtWxiOSoJei0AYIwj';
update content_bodies set title = 'Today''s Gero Onsen', description = 'While seeking relief from the heat, I found myself at Ujō Park. Despite the hot weather, the cool air from the flowing river made it pleasant. The sweat I had worked up began to dissipate, making it a perfect time for a stroll. Although swimming might be difficult, dipping my hands in the water spread a refreshing coolness throughout my body. After this, a soak in the hot springs will surely wash away the heat. Please enjoy Gero Onsen!' where id = 'CJ4ay9H3DQE1OS0R90jyK';
update content_bodies set title = 'けふの下呂温泉', description = 'カラッと晴れ間が広がっている下呂温泉です。市街にあるデジタルフォトラリーのスポットをいくつか撮影して回りました。けふも暑くなりそうと思っていると、午後から急に激しい雨が降り始めました。ついさっきまで晴れていたのが嘘のように、窓から雨が降り注いでいます。突然の雨には、折り畳み傘と雨宿り、そして温泉が欠かせません。濡れて冷えた体をホットに回復させましょう！下呂温泉をよろしくお願いいたします！' where id = 'gz2-GuftkDC2eRP-KUO72';
update content_bodies set title = 'Today in Gero Onsen', description = 'Gero Onsen is experiencing clear skies today. I visited several spots in the city for a digital photo rally. Just when I thought it would be a hot day, a sudden heavy rain started in the afternoon! The scene outside the window, with rain pouring down, seems like a lie after such clear weather. For unexpected rain, a folding umbrella, a place to take shelter, and a hot spring are essential! Let''s warm up our chilled bodies with some hot water! Please enjoy Gero Onsen!' where id = 'WbTdC-Wj83j_PUVtrbSRG';
update content_bodies set title = 'けふの下呂温泉', description = '一雨去り、爽やかさと暑さが同居している下呂温泉です。日差しは雲に遮られがちですが、知らず知らずに木陰や水場を求めて歩いていて、夏の暑さがやってきていたのだなあと実感しました。花や虫が暑さに負けずにいる姿を見ると、こちらも暑い暑いとぼやいていてはいけないと、気合が入ります。心機一転、リフレッシュを図るなら温泉がベスト！下呂温泉をよろしくお願いいたします！' where id = 'wc_5ky9OZhN357QdvgjRR';
update content_bodies set title = 'Today at Gero Onsen', description = 'After a rain, Gero Onsen experiences a unique blend of refreshing coolness and summer heat. Although the sunlight is often blocked by clouds, I find myself instinctively seeking shade and water, realizing that summer has indeed arrived. Observing flowers and insects thriving despite the heat motivates me to stay positive and not complain about the warmth. If you''re looking to refresh and rejuvenate, there''s no better place than the hot springs! Please enjoy Gero Onsen!' where id = '9YrKJ6rVoaXjmEZ5--day';
update content_bodies set title = 'けふの下呂温泉', description = '今日は雨の中の下呂温泉です。しっとりとした空気の中、憂鬱とは無縁のさわやかさが感じられます。山の向こうには霧の合間から青空が見え、この雨も長くは続かないと感じさせます。雨の日は気温が下がり、体が冷えるため、あたたかい温泉が最適です。下呂温泉をよろしくお願いいたします！' where id = '70Y1PxoX2mupxo3eybJJL';
update content_bodies set title = 'Today at Gero Onsen', description = 'Gero Onsen is experiencing rain today. Despite the dampness, the atmosphere is refreshing and free from gloom. Beyond the mountains, glimpses of blue sky peek through the mist, suggesting that the rain won''t last long. Rainy days often bring cooler temperatures, making warm hot springs the perfect remedy for a chilled body. We hope you enjoy Gero Onsen!' where id = 'pSdjWYfyCUzvPiXKlZfXg';
update content_bodies set title = 'けふの下呂温泉', description = '6月に入り、暑さが増してきました。下呂温泉では日差しが強く、半そでのシャツにしたくなる季節です。しかし、高所では涼しい風が吹いており、下呂温泉の美しい景色を楽しむことができます。飛騨川を囲むように温泉旅館が立ち並び、見るだけで温泉に入りたくなります。自然、温泉、グルメが楽しめる下呂温泉をぜひ訪れてください！※6月11日に撮影した動画です。' where id = 'suu0HkObLChzKQeJ7m6A8';
update content_bodies set title = 'Today’s Gero Onsen', description = 'As June begins, the weather is getting warmer! Gero Onsen is experiencing strong sunlight, making it the perfect time to switch to short-sleeved shirts. However, at higher altitudes, a gentle breeze provides a refreshing contrast, allowing visitors to enjoy a panoramic view of Gero Onsen. The hot spring inns are lined along the Hida River, and just looking at them makes one eager to take a dip in the hot springs! Gero Onsen is a city rich in nature, hot springs, and gourmet food, so please come and enjoy it! *This video was taken on June 11th.' where id = 'D-Ha-M41FF6vweMVqOUMv';
update content_bodies set title = 'けふの下呂温泉', description = '快晴の下呂温泉です！日差しが強く、夏の到来を感じさせます。暑さに負けず、各所で花が美しく咲いています。セミの声はまだ聞こえませんが、間もなく賑やかな合唱が始まるでしょう。暑い時期には、熱い温泉で汗を流してリフレッシュするのがおすすめです！下呂温泉をよろしくお願いいたします！' where id = 'ZmH1dVtUbEXrCYtQQxD5l';
update content_bodies set title = 'Today at Gero Onsen', description = 'It''s a clear day at Gero Onsen! The strong sunlight makes it feel like summer is finally here. Despite the heat, flowers are blooming beautifully in various places. Although the sound of cicadas hasn''t started yet, it seems that their noisy chorus will begin soon. When it''s hot, soaking in the hot springs to refresh yourself is highly recommended! Please enjoy Gero Onsen!' where id = 'pTJocqUlCaV7u4I9hemc5';
update content_bodies set title = '自然溢れる下呂温泉', description = '飛騨川の流域に湧く下呂温泉は、室町時代の僧万里集九や、徳川家康に仕えた儒学者林羅山によって、日本三名泉の一つとして称されています。下呂温泉は、兵庫県の有馬温泉や群馬県の草津温泉と並ぶ名泉であり、温泉街は飛騨川を中心に賑わいと山里の風情が調和しています。この魅力的な環境が下呂温泉の特長を引き立てています。' where id = 'vPSq-T_E1Zw7VSDak2PkX';
update content_bodies set title = 'Gero Onsen Surrounded by Nature', description = 'Gero Onsen, located in the Hida River basin, is renowned as one of Japan''s three famous hot springs, alongside Arima Onsen in Hyogo Prefecture and Kusatsu Onsen in Gunma Prefecture. This recognition dates back to the Muromachi period, attributed to monks such as Manri Shukyu and Confucian scholar Hayashi Razan, who served four generations of the Tokugawa shogunate. The hot spring town harmoniously blends the lively atmosphere centered around the Hida River with the rustic charm of the surrounding mountains, showcasing the unique appeal of Gero Onsen.' where id = 'EI5hcNUI2ht7IzF3L4_hp';
