update content_bodies set title = '飛騨国　下呂の旅　総集編01', description = 'この総集編は、飛騨国に位置する下呂の旅行体験をまとめたものです。下呂の魅力や文化、特徴を紹介し、旅行先としての重要性を示しています。' where id = 'S6GgaVBSvKdiQpI2dfo9X';
update content_bodies set title = 'Hida Province: Gero Travel Compilation 01', description = 'This is a compilation of travel experiences in Gero, located in Hida Province. The content provides insights into the attractions, culture, and unique features of Gero, showcasing its significance as a travel destination.' where id = 'JqqWH-Gpi_zRS6ypwK-cN';
update content_bodies set title = '冬の飛騨路「料理」編', description = 'この動画では、冬の飛騨路における料理について紹介しています。' where id = 'dxM8J7pz55aOHCJQnWh87';
update content_bodies set title = 'Winter Hida Region: Cuisine Edition', description = 'This video introduces the cuisine of the Hida region during winter.' where id = '3u7ThrapMTgXfSXfzUjei';
update content_bodies set title = '冬の飛騨路「温泉」編', description = 'この動画では、冬の飛騨路における温泉の魅力を紹介しています。温泉は、寒い冬に心身を温めるための素晴らしい場所であり、飛騨路の美しい自然と共に楽しむことができます。' where id = 'VdLGNKLad72NcA_JOE_ke';
update content_bodies set title = 'Winter Hida Region: Onsen Edition', description = 'This video introduces the onsen (hot springs) in the Hida region during winter.' where id = 'ux36FepsWLSOj7WqToD3E';
update content_bodies set title = 'YOSAKOIソーラン日本海下呂温泉大会-CM', description = '2010年10月23日と24日に「YOSAKOIソーラン日本海下呂温泉大会」が開催されます。この大会の模様は、10月31日（日）午後8時54分から「ぎふチャン」で放送される予定です。ぜひご覧ください。' where id = 'cFaBS27IC4922oi0Wsm5u';
update content_bodies set title = 'YOSAKOI Soran Japan Sea Gerohonsen Festival - CM', description = 'The ''YOSAKOI Soran Japan Sea Gerohonsen Festival'' will be held on October 23rd and 24th, 2010. The event will be broadcast on ''Gifu Channel'' (TV) on October 31st (Sunday) at 8:54 PM. Don''t miss it!' where id = 'lDcmYyN05JzOZcReHPHDz';
update content_bodies set title = '冬の下呂温泉　花火物語ＣＭ', description = '日本三名泉の下呂温泉では、2010年1月9日から3月27日までの毎週土曜日に、夕食後のリラックスタイムに「花火の歳時記」を開催します。このイベントでは、日本特有の四季の行事や風習を和の風情ある花火で表現し、下呂温泉を訪れるお客様の旅情を一層高める催し物となっています。' where id = 'vFwGgFWy-dJWGPJHKHASs';
update content_bodies set title = 'Winter Fireworks Story at Gero Onsen', description = 'From January 9 to March 27, 2010, Gero Onsen, one of Japan''s three famous hot springs, will host a special event every Saturday evening after dinner. This event, titled ''Fireworks Almanac of Hida'', will showcase beautiful fireworks that reflect Japan''s unique seasonal traditions and customs, enhancing the travel experience for visitors to Gero Onsen during the winter season.' where id = '7PAP-F_1zzjcX8AFNumaT';
update content_bodies set title = '冬の函館は宝石のような存在', description = 'この動画では、冬の函館を宝石のような存在として紹介しています。冬の季節における函館の美しさや魅力、独自の観光名所や体験に焦点を当てています。' where id = '0prelp5FXz8RMj6sdgh7p';
update content_bodies set title = 'Hakodate in winter is a gem', description = 'This video highlights Hakodate during the winter season, presenting it as a hidden gem. The focus is on the beauty and charm of the city in winter, showcasing its unique attractions and experiences.' where id = 'vd_V-E8eHob1vhtdrvLAC';
update content_bodies set title = '函館の冬：居心地の良いカフェ、海鮮市場、ジンギスカンBBQ！❄️🍖', description = '北海道函館の冬の魅力を体験しませんか？新鮮なジンギスカンのラムBBQや、居心地の良い市場のカフェでの手作りコーヒーを楽しむことができます。この旅行は、美味しい食べ物、スロートラベル、家族との心温まる瞬間に焦点を当てました。函館のトラムに乗ったり、隠れたバーを見つけたり、函館朝市で新鮮な海鮮を味わったり、歴史的な金森赤レンガ倉庫や美しい八幡坂を訪れたりしました。フレックスステイイン函館で快適に過ごし、コメダコーヒーや十字屋コーヒーで美味しいコーヒーを楽しみました。旅行の締めくくりには、大黒でジンギスカンBBQを堪能し、バーシェアズヒシイで居心地の良い夜を過ごしました。冬の函館は、リラックスと美食の冒険が融合した完璧な場所です。' where id = 'JsF1_EjDipEs5JRF4l594';
update content_bodies set title = 'Winter in Hakodate: Cozy Cafes, Seafood Markets & Genghis Khan BBQ! ❄️🍖', description = 'Experience the winter charm of Hakodate, Hokkaido, where you can enjoy freshly grilled Genghis Khan lamb BBQ and handcrafted coffee in cozy cafes. The trip focused on good food, slow travel, and family moments. Highlights included riding the Hakodate tram, discovering a hidden bar, and visiting various attractions such as the Hakodate Morning Market for fresh seafood, the historic Kanemori Red Brick Warehouse, and the scenic Hachiman Zaka Slope. The stay at Flexstay Inn Hakodate provided comfort, while cafes like Komeda Coffee and Jujiya Coffee offered delightful brews. The trip concluded with a flavorful Genghis Khan BBQ at Daikoku and a cozy evening at Bar Shares Hishii. Hakodate in winter is a perfect blend of relaxation and culinary adventure.' where id = 'Glm8nV0zuZiHfpTzEzSam';
update content_bodies set title = '大津の静かな楽園と大阪の活気ある魅力を発見 🍁 | 琵琶湖アドベンチャー 🌊', description = '京都の近くにある大津は、琵琶湖の美しさが広がる静かな旅行先で、初秋の探検に最適な楽園です。このブログでは、大津が訪れる価値のある過小評価された宝石であることと、大阪の活気あるエネルギーが旅行の締めくくりにぴったりであることを紹介しています。琵琶湖周辺の景勝地を探索するためにレンタカーを借り、琵琶湖バレーロープウェイでの絶景、神秘的な白髭鳥居の訪問、浮遊する寺院である浮御堂での静かなひととき、八幡堀での美しい夕日を楽しむ様子が描かれています。旅行は大阪での心地よいしゃぶしゃぶディナーやお土産のショッピングで締めくくられ、観光客が少ない場所を紹介することを目的としています。' where id = 'rzC9jeABAn7OEFWUaeyxc';
update content_bodies set title = 'Discover Otsu’s Tranquil Paradise & Osaka’s Vibrant Charm 🍁 | Lake Biwa Adventure 🌊', description = 'Escape to Otsu, a peaceful destination near Kyoto, where the beauty of Lake Biwa offers a tranquil paradise ideal for early autumn exploration. This vlog highlights Otsu as an underrated gem worth visiting, alongside the vibrant energy of Osaka, which makes for a perfect trip finale. The adventure includes renting a car to explore scenic spots around Lake Biwa, riding the Biwako Valley Ropeway for stunning views, visiting the iconic Shirahige Torii shrine, reflecting at the Ukimido floating temple, and enjoying a sunset at Hachiman-bori Moat. The trip concludes in Osaka with a cruise at Shinsaibashi, indulging in shabu-shabu, and shopping for souvenirs. The vlog aims to introduce less touristy places for future travelers to Japan.' where id = 'y6F33dbrd7tGoWFeeQeHy';
update content_bodies set title = '京都の初秋の田舎への小旅行 🍁 | 天橋立', description = 'このVlogでは、賑やかな都市を離れ、初秋の京都の田舎の静かな美しさを発見する旅に誘います。紅葉が始まると、風景は緑、金、赤の美しい混ざり合いで生き生きとします。アラシヤマの竹林を散策し、天橋立の絶景を楽しむためにスカイリフトに乗り、京都丹後鉄道の観光列車で北部の田舎を巡ります。食事は新京極商店街で美味しいラーメンを堪能し、湖の美しい景色を楽しめるびわ湖プリンスホテルに宿泊します。この動画は、京都の秋の魅力を伝え、象徴的な名所や美しい景色、忘れられない食体験を紹介しています。' where id = 'yoxqWhW3VvGxIPMqPpvCS';
update content_bodies set title = 'Kyoto’s Early Autumn Getaway in the Countryside 🍁 | Amanohashidate', description = 'This vlog invites viewers to escape the city and explore the serene beauty of Kyoto''s countryside during early autumn. As the foliage changes, the landscapes transform into a vibrant mix of greens, golds, and reds. The journey includes a stroll through the Arashiyama Bamboo Grove, a scenic chairlift ride at Amanohashidate, and a trip on the Kyoto Tango Railway, showcasing the picturesque northern countryside. The day concludes with a delicious ramen dinner at Shinkyogoku Shopping Street and a stay at the Lake Biwa Prince Hotel, offering stunning views of Japan''s largest lake. This video highlights the charm of Kyoto in autumn, featuring iconic sites, beautiful scenery, and memorable culinary experiences.' where id = '72I-cdwAqPL0FucT8vsxY';
update content_bodies set title = '斎宮プロモーション動画（明和町） ｜観光三重｜三重県の観光・旅行情報', description = '斎宮は1,000年前の日本を体感できる場所で、約700年もの間幻の都とされていましたが、50年前の発掘調査によってその存在が明らかになりました。ここでは貴族たちの華やかな生活を体験しながら、斎宮の歴史と文化を楽しむことができます。また、海岸を歩く「めいわセラピー」などのヘルスツーリズムも提供されており、心と体を整えることができます。明和町ではアウトドアや農業、歴史文化など多彩な体験ができ、心に残る旅が楽しめます。さらに、地元の美味しい食べ物やスイーツを巡ることもでき、伊勢神宮にゆかりのあるこの地域の魅力を存分に味わうことができます。' where id = 'zodQ1hk8ja9135gshJKkk';
update content_bodies set title = 'Saiku Promotion Video (Meiwa Town) | Tourism Mie | Mie Prefecture Travel Information', description = 'Saiku offers a unique opportunity to experience Japan from 1,000 years ago. Once considered a mythical capital for about 700 years, its existence was revealed through excavation efforts that began 50 years ago. Visitors can immerse themselves in the luxurious lifestyle of the nobility while enjoying the rich history and culture of Saiku. The area also promotes health tourism through activities like ''Meiwa Therapy,'' which allows participants to walk along the coast while feeling the history of the Saio. Meiwa Town offers various experiences, including outdoor activities, agriculture, and cultural history, making it a memorable destination. Additionally, visitors can explore local delicacies and sweets, enhancing their journey through this historically significant area connected to Ise Jingu.' where id = 'g9uTgxOVrViAch7WA30zE';
update content_bodies set title = '京都の初秋の魅力 🍁 | 二年坂、祇園、嵯峨野ロマンティックトレイン', description = '初秋の京都はまさに魔法のような美しさです。紅葉が始まり、鮮やかな緑、燃えるような赤、黄金色の葉が織りなす色彩のカレイドスコープが広がります。このブログでは、二年坂や三年坂の歴史的な街並みを散策し、伝統的な木造家屋や居心地の良いお店が時を超えた雰囲気を醸し出しています。白花カフェでのほうじ茶ラテとマドレーヌ、My Only Fragrance清水でのオリジナル香水作り、夜の祇園町南川の魅力を堪能しました。また、旬のすき焼き料理を楽しみ、嵯峨野ロマンティックトレインでの美しい景色も体験しました。京都古伝町花伝荘温泉旅館でのリラックスしたひとときも魅力的です。このブログは、秋の京都を夢見る人や訪れる予定の人にとって、完璧なガイドです。' where id = 'uCSlFfy9U4My24xqmFuLj';
update content_bodies set title = 'Kyoto''s Early Autumn Charm 🍁 | Ninenzaka, Gion & Sagano Romantic Train', description = 'Kyoto in early autumn is a magical experience, with foliage beginning to change into vibrant greens, reds, and yellows. This vlog captures the beauty of Kyoto during this season, showcasing historic streets like Ninenzaka and Sannenzaka, where traditional wooden houses and shops create a nostalgic atmosphere. Highlights include enjoying a hojicha latte and madeleine at Shiroka Cafe, creating a customized fragrance at My Only Fragrance Kiyomizu, and experiencing the enchanting Gionmachi Minamigawa at night. A delicious sukiyaki meal at Junidanya Hanamikoji Street and a scenic ride on the Sagano Romantic Train add to the charm. The stay at Kyoto Kodenmachi Kadensho Onsen Ryokan offers relaxation after a day of exploration. This vlog is a perfect guide for anyone dreaming of or planning a trip to Kyoto in autumn.' where id = 'n2_zZ2NyNA389AeLmtVLG';
update content_bodies set title = '日本探訪：津山から神戸、六甲山と有馬温泉！🇯🇵 2日目の旅', description = '私たちの日本の旅の2日目は、津山の魅力的な町を探索し、地元のカフェでブランチを楽しんだ後、岡山に戻り、神戸行きの電車に乗ります。神戸では、公共バスで六甲山のケーブルカー駅に向かい、山頂からの素晴らしい景色を楽しみます。また、リラックスできる雰囲気の有馬温泉の町にも立ち寄ります。日が沈む頃、六甲ガーデンテラスの展望台で神戸港の美しい夜景を堪能し、最後にしゃぶしゃぶレストランで温かいおもてなしと美味しい料理を楽しんで、素晴らしい一日を締めくくります。次の日の冒険もお楽しみに！' where id = 'rlXVwBiCAG2B6MXeywnZG';
update content_bodies set title = 'Exploring Japan: Tsuyama to Kobe, Mount Rokko and Arima Onsen! 🇯🇵 Day 2 Journey', description = 'On Day 2 of our journey through Japan, we explore the quaint town of Tsuyama, enjoy brunch at a local café, and then travel to Okayama to catch a train to Kobe. In Kobe, we take a bus to the Mount Rokko Cable car station, where we ascend to enjoy stunning views. We also visit the charming Arima Onsen town, known for its relaxing hot springs. As the day ends, we visit the Mount Rokko Garden Terrace observatory for a breathtaking night view of Kobe port. Our day concludes with a delightful dinner at a shabu shabu restaurant, where we experience warm hospitality and delicious food. Stay tuned for Day 3 of our adventure!' where id = 'qepdY3h5G5P_HHSNeoLDU';
update content_bodies set title = 'Kuretake Gansai Tambi 48色水彩セットで描く日本の街 | ハイパーラプスペインティング', description = 'この動画では、アーティストがKuretake Gansai Tambi 48色水彩セットを使用して、日本の色鮮やかな街の風景を描く様子を紹介しています。制作には約8時間を要し、街の独特な色合いを再現する過程を楽しんだと語っています。視聴者は、この作品のデジタルプリントを購入できることが案内されており、購入後すぐにダウンロード可能です。また、アーティストはチャンネルへの「いいね」や登録を通じてのサポートを呼びかけており、ファッションやファッションデザイナーとしての生活に関するコンテンツを共有しています。コラボレーションやハンドメイドファッションアイテムに興味がある方のために、ウェブサイトやSNSのリンクも提供されています。' where id = 'Vzr8bjQFBA48p7ldjPi_8';
update content_bodies set title = 'Painting Street in Japan with Kuretake Gansai Tambi 48 Watercolor Set & Review | Hyperlapse painting', description = 'In this video, the artist shares their experience of painting a vibrant street scene in Japan using the Kuretake Gansai Tambi 48 Watercolor Set. The process took around 8 hours, and the artist expresses their enjoyment in recreating the unique colors of the street. Viewers are invited to purchase digital prints of the artwork, which will be available for immediate download. The artist encourages support through likes and subscriptions to their channel, where they share content related to fashion and their life as a fashion designer. Links to their website and social media are provided for those interested in collaborations or handmade fashion items.' where id = 'k81Rj3sgtoWqeJ46enWKN';
update content_bodies set title = 'Kuretake Gansai Tambi 48色水彩セットとアクリルで描く銀河 | ハイパーラプスペインティング', description = 'このブログでは、アーティストが銀河の鮮やかな色にインスパイアされた最新の水彩画を紹介しています。使用したのは日本製のKuretake Gansai Tambi 48色セットで、塩やアセトン、アルコール、アクリルなどのさまざまな媒介を使って実験しながら描いたプロセスが映し出されています。これは有料プロモーションではなく、個人的な体験として紹介されています。視聴者は、提供されたEtsyのリンクを通じてこの作品のデジタルプリントを購入することができます。アーティストは、ファッションやデザイナーとしての生活に関するさらなるコンテンツのために、いいねやチャンネル登録を通じてのサポートを呼びかけています。また、彼らの作品やソーシャルメディアへのリンクも共有されています。' where id = 'PU63TGme3qdhAiJWocEpz';
update content_bodies set title = 'Painting Galaxy with Kuretake Gansai Tambi 48 Watercolor Set & Acrylic | Hyperlapse painting', description = 'In this vlog, the artist shares their latest watercolor artwork inspired by the vibrant colors of a galaxy, created using the Kuretake Gansai Tambi 48 color set from Japan. The video showcases the painting process, which includes experimenting with various mediums like salt, acetone, alcohol, and acrylic. The artist emphasizes that this is not a paid promotion but rather a personal experience with the watercolor set. Viewers can purchase digital prints of the artwork through a provided Etsy link. The artist encourages support through likes and subscriptions for more content related to fashion and their life as a designer. Additional links to their work and social media are also shared.' where id = 'BvjrdcQrZEgyLUSs5fHt7';
update content_bodies set title = '初めて猫の服を作りました | 猫の服作り', description = 'この動画では、10月に迎える猫のブルーの2歳の誕生日を祝うために、彼のためにクールな服を作った経験を共有します。ペット用の服を作るのは初めてで、特にブルーのサイズを測るのに苦労しました。彼はメジャーが嫌いだからです。それでも、ゼロから服をデザインし、制作する過程を楽しみました。私の思考過程、デザイン、制作、フィッティングのプロセスを紹介しますので、最後まで見て、ブルーがどれほどスタイリッシュに見えるかを確認してください。パターンに興味がある方は、コメントを残してください。チャンネルをサポートするために、いいねと登録を忘れずに！' where id = '819qrX6r1X3FrAsaF5dFN';
update content_bodies set title = 'I made an outfit for my cat for the first time | Make Cat Clothes', description = 'In this video, I share my experience of making a cool outfit for my cat, Bleu, in celebration of his upcoming 2nd birthday this October. It was my first attempt at creating pet clothing, and I faced challenges, especially with taking Bleu''s measurements since he dislikes the measuring tape. Despite the struggles, I enjoyed the creative process of designing and producing the outfit from scratch. I will walk you through my thought process, design, production, and fitting process, so make sure to watch until the end to see how stylish Bleu looks in his new outfit. If you''re interested in the pattern, feel free to leave a comment. Don''t forget to like and subscribe to support my channel!' where id = 'rvXW9ggVqtORiGCHAkp6t';
update content_bodies set title = 'Vlog: パンデミックがファッションデザイナーとしての私に与えた影響', description = 'このVlogでは、マレーシアのファッションデザイナーがパンデミック中の体験を共有し、ビジネスや私生活にどのように影響を与えたかを詳述しています。オンラインストアへの移行や、マレーシアのデザイナーが直面する課題、新しい常態に適応するための努力について語ります。また、ファイザーのワクチン接種体験や新しいプロジェクト、他のクリエイターとのコラボレーションの重要性についても触れています。困難な状況にもかかわらず、彼女は自分の仕事を続ける決意を示し、視聴者にチャンネルをサポートするよう呼びかけています。動画には、仕事と生活のバランスの取り方や、他の人々に自分のストーリーを共有するよう促すセグメントも含まれています。' where id = 'KOpA7aFPSci7bpdb6__y5';
update content_bodies set title = 'Vlog: How Did Pandemic Affected Me As A Fashion Designer', description = 'In this vlog, a Malaysian fashion designer shares her experiences during the pandemic, detailing how it has impacted her business and personal life. She discusses her transition to an online store, the challenges faced by designers in Malaysia, and her efforts to adapt to the new normal. The designer also talks about her experience with the Pfizer vaccination, new projects, and the importance of collaboration with other creatives. Despite the difficulties, she remains determined to continue her work and encourages viewers to support her channel. The video includes various segments, such as her work-life balance methods and an invitation for others to share their stories.' where id = 'KbnvZrrcO6M87s7yM12B1';
update content_bodies set title = 'Kuretake Gansai Tambi 48色水彩セットで風景画を描く | ハイパーラプスペインティング', description = 'このVlogでは、アーティストが日本製のKuretake Gansai Tambi 48色水彩セットを使用して、3日間にわたって水彩画を制作する過程を共有しています。動画には、作品のスケッチや水彩セットのカラーチャート、使用する紙や作業スペースの設定についての詳細が含まれています。スピードペインティングのプロセスが紹介され、使用した道具やKuretakeのカラーパンのレビューも行われています。アーティストは、ロックダウン中に絵を描く楽しさを表現し、作品のデジタルプリントを購入するよう視聴者に促しています。また、アーティストのファッションデザイン作品やSNS、他のハンドメイドファッションVlogへのリンクも紹介されています。' where id = '3fZshJ07OPAk7C14bLoKK';
update content_bodies set title = 'Painting Scenery with Kuretake Gansai Tambi 48 Watercolor Set & Review | Hyperlapse painting', description = 'In this vlog, the artist shares their experience of creating a watercolor painting over three days using the Kuretake Gansai Tambi 48 color set, made in Japan. The video includes a sketch of the artwork, a color chart of the watercolor set, and details about the paper and workspace setup. The speed painting process is showcased, along with a review of the tools used and the Kuretake color pans. The artist expresses their enjoyment of painting during the lockdown and encourages viewers to purchase digital prints of the artwork. The vlog also promotes the artist''s fashion design work and provides links to their social media and other handmade fashion vlogs.' where id = 'qtm3Go-2sFhNWsD-kfY3S';
update content_bodies set title = '[Vlog] Kuretake Gansai Tambi 48色水彩セットの開封とカラーチャートでの色テスト', description = '今週のVlogでは、ロックダウン中に購入したKuretake Gansai Tambi 48色水彩セットの開封体験を共有しています。日本製のアイテムが好きなクリエイターは、この中級者向けの水彩セットを試すことにワクワクしています。このセットには48色の豊富な色が揃っており、色のテクスチャーや色合いを示すカラーチャートを作成する様子が収められています。Vlogは、パレットに興味がある視聴者にとって有益であり、他の人にとっても楽しめる内容になることを願っています。また、ファッションデザインの作品や他のクリエイティブプロジェクトへのリンクも提供しています。' where id = 'N5Hvx6pykJXdDzcRlcUwA';
update content_bodies set title = '[Vlog] Unbox Kuretake Gansai Tambi 48 Watercolor Set and Testing the Colors on Color Chart', description = 'In this week''s vlog, the creator shares their experience of unboxing the Kuretake Gansai Tambi 48 watercolor set, which they purchased during an extended lockdown. As a fan of Japanese products, they were excited to try this intermediate-level watercolor set, which features a wide range of 48 colors. The video includes a demonstration of creating a color chart to showcase the textures and colors of the paints. The creator hopes the vlog will be informative for viewers interested in the palette and enjoyable for others. Additionally, they provide links to their fashion design work and other creative projects.' where id = 'MooGLOBLbZnxF3wLov_M4';
update content_bodies set title = 'スタンドカラー付き日本風ボクシー長シャツの縫い方 | 簡単な縫製チュートリアル', description = 'このビデオチュートリアルでは、スタンドカラー付きのボクシー日本風長シャツを紙パターンを使って作る方法を紹介しています。プレゼンターは、古いデザインを新しい生地に移すプロセスを共有し、視聴者に自宅で自分のシャツを作ることを奨励しています。ビデオでは、視聴者が自分の作品をソーシャルメディアで共有するよう呼びかけており、ワークショップやハンドメイドデザインへのリンクも提供しています。また、持続可能なファッションや他の縫製チュートリアルに関するコンテンツを受け取るための購読を促しています。' where id = 'Xos2FfShvENktUspAmvcs';
update content_bodies set title = 'How to Sew A Japanese Style Boxy Long Shirt With Stand Collar | Easy Sewing Tutorial', description = 'This video tutorial demonstrates how to create a boxy Japanese-style long shirt with a stand collar using paper patterns. The presenter shares the process of transferring an old design onto new fabrics, encouraging viewers to follow along and try making their own shirts at home. The video invites viewers to share their creations on social media and provides links to workshops and handmade designs. Additionally, it promotes subscriptions for more content related to sustainable fashion and other sewing tutorials.' where id = '2BFfXMkMhtw5tlveR1Zzo';
update content_bodies set title = 'ファッションデザイナーブログ: エピソード4: 在宅勤務の生活', description = 'このファッションデザイナーブログのエピソード4では、MCO2ロックダウンの初日々を振り返り、自宅でミシンやプロジェクトをセットアップする様子を紹介します。また、私のペットのブルーとヒロも登場します。ファッション業界で働いている方々との交流も楽しみにしています。手作りのサステナブルファッションに関するコンテンツをもっと見たい方は、ぜひチャンネル登録をお願いします。' where id = 'nm0_uOT0TPzJpzawZ0xrI';
update content_bodies set title = 'Fashion Designer Vlog: Epi 4: Life Working From Home', description = 'In episode 4 of my fashion designer vlog, I share my experiences during the initial days of the MCO2 lockdown, where I had to set up my sewing machines and projects at home. I introduce my pets, Bleu and Hiro, and invite others in the fashion industry to connect with me. I encourage viewers to subscribe for more content related to handmade sustainable fashion and to follow my social media for updates.' where id = 'XgLO_Pnv0M3lvYZ7Px7pS';
update content_bodies set title = 'ファッションデザイナーYJのVlogエピソード3: 自宅でのロックダウン', description = 'このエピソードでは、MCOによるロックダウンの初日を過ごす様子をお届けします。すべてのミシンとプロジェクトを自宅に持ち帰り、作業を続けることになりました。また、私の愛らしいペットも登場します！ファッション業界で働いている方がいれば、ぜひお話ししたいです。手作りのサステナブルファッションやデザインに関するコンテンツをもっと見たい方は、チャンネル登録をお忘れなく！' where id = '89SZYJjJxSsy6g6aN7hZd';
update content_bodies set title = 'Fashion Designer YJ''s Vlog Episode 3: Lockdown at Home', description = 'In this episode of my fashion designer vlog, I share my experience of the first day in lockdown due to the MCO. I had to bring all my sewing machines and projects home to continue my work. You''ll also meet my furry friend! If you work in the fashion industry, I would love to connect with you. Don''t forget to subscribe for more content related to handmade sustainable fashion and fashion design!' where id = 'JGzk0kOr6ktHnMf0wewu_';
update content_bodies set title = '斎宮プロモーション動画【学芸員の解説編】（明和町） ｜観光三重｜三重県の観光・旅行情報', description = '斎宮は1,000年前の日本を体感できる場所で、約700年もの間幻とされていましたが、50年前の発掘調査でその存在が明らかになりました。ここでは貴族たちの華やかな生活を体験しながら、斎宮の歴史と文化を楽しむことができます。取材レポートでは、海岸を歩きながら斎王の歴史を感じる「めいわセラピー」などのヘルスツーリズムが紹介されています。また、明和町ではアウトドアや農業、歴史文化を楽しむことができ、心に残る体験が待っています。さらに、地元の美味しい食べ物やスイーツを巡ることもでき、伊勢神宮にゆかりのある斎宮の魅力を存分に味わえる旅が提案されています。' where id = 'mt7ch1qiUn1sTmDns2yTh';
update content_bodies set title = 'Saiku Promotion Video [Curator''s Explanation] (Meiwa Town) | Tourism Mie | Mie Prefecture Travel Information', description = 'Saiku offers a unique opportunity to experience Japan from 1,000 years ago. Once considered a mythical capital, its existence was revealed through excavation efforts that began about 50 years ago. Visitors can immerse themselves in the luxurious lifestyle of the nobility while enjoying the rich history and culture of Saiku. The report highlights health tourism activities like ''Meiwa Therapy,'' which allows participants to walk along the coast while feeling the history of the Saio. Meiwa Town also offers outdoor activities, agricultural experiences, and cultural history, making it a memorable destination. Additionally, visitors can explore local delicacies and sweets, enhancing their experience in this historically significant area associated with Ise Jingu.' where id = 'cZUD_MXSaTftVooUyUrKK';
update content_bodies set title = 'ファッションデザイナーとしての一日 | XP-Pen Artist 12 Proのレビュー | タイムラプスイラスト', description = 'このVlogでは、YJがファッションデザイナーとしての生活を紹介しています。彼女の一日はファッションプロジェクトだけで構成されているわけではなく、最近の仕事やプロジェクトの合間にどのように時間を過ごしているかを語ります。また、XP-Pen Artist 12 Proの描画タブレットについての個人的な体験を簡単にレビューし、広告ではないことを強調しています。興味のある方は製品をチェックするように促しています。動画には、彼女の衣装の出所や他の関連動画へのリンクも含まれており、DIYプロジェクトや縫製チュートリアルを紹介しています。' where id = 'shJGGXjf5mZTH_QWyTMeV';
update content_bodies set title = 'A Day At Work as Fashion Designer | Review on XP-Pen Artist 12 Pro | Timelapse Illustration', description = 'In this vlog, YJ shares a glimpse into her life as a fashion designer, highlighting that her day isn''t solely focused on fashion projects. She discusses her recent work and how she spends her time between different projects. Additionally, YJ provides a brief review of the XP-Pen Artist 12 Pro drawing tablet, sharing her personal experience without it being an advertisement. Viewers are encouraged to check out the product if they are interested. The video also includes links to her outfit source and other related videos, showcasing her DIY projects and sewing tutorials.' where id = 'X1m7jOyTKOmeItde0tbCh';
update content_bodies set title = '[HD] Aラインリネンドレスの縫い方 | ドレス作り | 縫製チュートリアル', description = 'この動画では、クライアントのために作られたAラインのリネンドレスの縫製チュートリアルを紹介します。クライアントは50代で、仕事に着ていけるシンプルで快適なデザインを希望しています。このドレスは、エレガントで女性らしさを引き立てるAラインのシルエットと柔らかいフレアスリーブが特徴です。動画では、全体の制作過程を5分でスピード再生し、縫製のコツも紹介しています。完成品を見るために最後まで視聴することが推奨されています。また、ワークショップや購入可能なハンドメイドデザインのリンクも紹介されています。' where id = 'Z1-7186UREHGnPvMFEVY_';
update content_bodies set title = '[HD] How to sew A-line Linen Dress | Dress making | Sewing Tutorial', description = 'This video presents a sewing tutorial for creating a made-to-measure A-line linen dress designed for a client in her 50s. The dress features a simple and comfortable design suitable for work, with an elegant A-line silhouette and soft flared sleeves. The video includes a 5-minute speed-through of the entire making process, along with sewing tips. Viewers are encouraged to watch until the end to see the finished product. Additionally, the video promotes workshops and handmade designs available for purchase, along with links to follow for updates and other related content.' where id = 'tqT9zns6pDZTSpVkEPQ0j';
update content_bodies set title = 'デザイナーYJとのタイダイ | ファッションデザイナー ワークショップ | テキスタイルデザインワークショップ', description = 'デザイナーYJによるユニークなタイダイワークショップに参加し、鮮やかな色彩で満たされた手作りアイテムを作りましょう。このワークショップは贈り物の季節に最適で、大切な人への特別なギフトを作ることができます。基本的なタイダイ技術や、自分のパターンや色をデザインする方法を学びます。ファッションデザイナーが各ステップを指導し、必要なツールや方法を理解できるようサポートします。また、色浴を作成し、布地を処理して色を持続させる方法も学べます。この機会を逃さず、新しいスキルを身につけて自分だけのユニークなデザインを作りましょう。定員に限りがあるため、今すぐ予約を！' where id = '2-QeKN2zieY6793Wp37Cs';
update content_bodies set title = 'Tie Dye with Designer YJ | Fashion Designer Workshop | Textile Design Workshop', description = 'Join Designer YJ for a unique tie dye workshop where you can create handmade items filled with vibrant colors. This workshop is perfect for the gifting season, allowing you to make special gifts for loved ones. You''ll learn essential tie dye techniques and how to design your own patterns and colors. The fashion designer will guide you through each step, ensuring you understand the tools and methods needed to achieve your desired results. You''ll also learn how to create color baths and treat fabrics to ensure lasting colors. Don''t miss this opportunity to gain new skills and create your own unique designs. Spots are limited, so book your place now!' where id = 'XCw-KJUpF4V_4ABnBSwAt';
update content_bodies set title = 'シンプルなタイダイ | ひもだけで素晴らしいタイダイTシャツを作る方法', description = '友達との夜のお出かけで目を引くスタイルを求めているが、普通のオーバーサイズTシャツに飽きてしまった方に最適なガイドです。簡単なステップで、ファッションのレベルを上げ、独自のパターンを作成する方法を紹介します。このチュートリアルを通じて、手軽にスタイリングを楽しむことができます。また、ファッションワークショップに参加することで、ユニークなデザインを作るためのさらなるヒントやテクニックを学ぶことができます。ぜひ、いいねやチャンネル登録をして、ファッション制作やデザイナーブログの最新情報をチェックしてください！' where id = '7b7WtofXfdQK9MIX6AC1T';
update content_bodies set title = 'Simple Tie Dye | How To Make Stunning Tie Dye T-shirts With Just a String', description = 'This guide offers a simple way to create stunning tie-dye T-shirts using just a string. If you''re tired of plain oversized T-shirts and want to elevate your fashion game for a night out with friends, this tutorial is for you. It provides easy steps to make unique patterns and enhance your outfit effortlessly. Additionally, you can join a fashion workshop to learn more tips and techniques for creating one-of-a-kind designs. Don''t forget to like and subscribe for more fashion-making content and designer vlogs!' where id = 'g3BlkV9eT1Ia0xS_fTXOn';
update content_bodies set title = 'トラペーズシルエットラッフルドレスの作り方', description = 'このプロジェクトでは、顧客のためにトラペーズラッフルドレスを作成しました。オックスフォード生地を使用し、重みがあり、ギャザー部分に構造的なドレープを生み出しています。その結果、ドレスは非常にボリューム感のある仕上がりになりました。制作過程はスムーズでユニークな体験でした。制作者は、フィードバックや問い合わせをソーシャルメディアを通じて受け付けており、FacebookやInstagramのリンク、ファッションデザインワークショップやハンドメイドアイテムのショップへのリンクも提供しています。' where id = 'UobAxyPXb-QNMgfBfHuBU';
update content_bodies set title = 'How to Make Trapeze Silhouette Ruffles Dress', description = 'This project involved creating a trapeze ruffles dress for a customer, utilizing oxford fabric that adds weight and structure to the gathered areas, resulting in a voluminous appearance. The experience was smooth and unique, showcasing the beauty of handmade fashion. The creators invite feedback and inquiries through their social media platforms, including Facebook and Instagram, and provide links to their fashion design workshop and shop for handmade items.' where id = 'PUBPaogoTI6qxID65HaG6';
update content_bodies set title = 'デザイナーYJによる5分間のシンプルメイク | サステナブルビューティー | 商品レビュー', description = '忙しい朝に時間をかけずに見栄えを良くしたい方に向けて、デザイナーYJが効率的な5分間のメイクルーチンを紹介します。このルーチンでは、肌に優しい天然成分を使用した手頃な価格のサステナブルビューティー製品が取り入れられています。メイクの効率性と倫理的な美しさを重視したこのアプローチは、サステナビリティを意識しながらビューティールーチンを簡素化したい人に最適です。今後のファッションやビューティー関連のコンテンツを楽しむために、チャンネルの登録をお勧めします。' where id = 'L00Z50eYU4jn4NAjx6wP3';
update content_bodies set title = '5-Min Simple Make Up With Designer YJ | Sustainable Beauty | Product Review', description = 'Designer YJ shares her quick 5-minute makeup routine for those busy mornings when you want to look good without spending too much time. The routine features affordable, sustainable beauty products made with natural ingredients that are beneficial for the skin. This approach to makeup emphasizes efficiency and ethical beauty, making it perfect for anyone looking to streamline their beauty routine while being mindful of sustainability. For more fashion and beauty content, viewers are encouraged to subscribe to the channel.' where id = '5cisLKjUI-uWSLdsduuUD';
update content_bodies set title = 'サテンラッフルブラウスの作り方 | ステップバイステップの縫製チュートリアル | 中級レベル', description = 'このチュートリアルでは、サテンラッフルブラウスの作成プロセスを紹介しています。このデザインは、パターンの実行と生産において非常に複雑です。制作者たちは、顧客からの注文を満たした後、最終製品に満足していることを表現しています。他の人々にカスタム注文のために訪問または連絡するよう呼びかけ、個別のアイテムを作成するためのデザインワークショップへの参加を促しています。また、ファッション制作、ブログ、持続可能な美容に関するコンテンツをもっと見るために、ソーシャルメディアチャンネルをフォローするように促しています。' where id = 'bh0hjqvDsRFGCp9LHEiVF';
update content_bodies set title = 'How to Make Satin Ruffles Blouse | Step by Step Sewing Tutorial | Intermediate Level', description = 'This tutorial showcases the process of creating a satin ruffles blouse, which is a complex design in terms of pattern execution and production. The creators express their satisfaction with the final product after fulfilling a customer order. They invite others to visit or contact them for custom orders and encourage participation in their design workshops to create personalized items. Additionally, they promote their social media channels for more content related to fashion making, vlogs, and sustainable beauty.' where id = '5wtx4GbQG0qJjZ3Oz9SNb';
update content_bodies set title = 'まちの駅たぬみせ納豆工房「松阪牛納豆」(松阪市) |観光三重|三重県の観光旅行情報', description = '納豆レストラン「たぬみせ」の自信作である「松阪牛納豆」は、松阪牛をすきやき風に味付けし、国産赤豆を発酵させた特殊な赤豆納豆と合わせて煮込んだ逸品です。この料理は瓶詰めされており、松阪牛の品質を引き立てるフュージョンの味わいを楽しむことができます。' where id = 'gQZa3bcR2vFMFPIxcPwTO';
update content_bodies set title = 'Matsusaka Beef Natto at Tanumise Natto Factory (Matsusaka City) | Tourism Mie | Mie Prefecture Travel Information', description = 'The Tanumise natto restaurant offers a unique dish called ''Matsusaka Beef Natto.'' This dish features Matsusaka beef seasoned in a sukiyaki style, combined with a special fermented red bean natto made from domestic red beans. The dish is simmered and then bottled, providing a fusion of flavors that highlights the quality of Matsusaka beef.' where id = 'e_fn6hTjxdhqpGlzWWBKV';
update content_bodies set title = '年齢に合わせて思いっきり遊べちゃう! 子どもたちが大好きな「三重県立みえこどもの城」で一日満喫! その２', description = '「三重県立みえこどもの城」は、年齢に応じた遊びができる施設で、子どもたちに大人気です。ここでは、自由に遊びながら楽しい一日を過ごすことができます。観光三重のホームページには、この施設の体験やアトラクションについての詳細なレポートが掲載されています。' where id = 'T5a3Q08WQzSRpccEBdODh';
update content_bodies set title = 'Enjoy a Day at Mie Children''s Castle Tailored to All Ages!', description = 'Mie Children''s Castle is a beloved destination for children, offering activities that cater to various age groups. The facility allows kids to play freely and enjoy a day filled with fun. A detailed report is available on the Kankomie website, providing insights into the experiences and attractions at this popular location.' where id = 'EL1_HC1hkmfjkzleMHwZ7';
update content_bodies set title = '10分で作るサステナブルマスク | フィルターマスク | 3D布マスクチュートリアル | PDFマスクパターン', description = 'IIJYNは、ファッションを通じてサステナビリティを促進することに情熱を注ぐファッションブランドです。彼らは、快適さ、フィット感、美しさを重視し、環境に優しい素材を使用したDIYサステナブルマスクパターンを開発しました。このチュートリアルは、個人のサステナビリティの取り組みを支援しつつ、自宅でマスクを作ることを奨励しています。IIJYNは、サステナブルマスク、オーダーメイド、パターン作成、ファッションデザインなど、さまざまなサービスを提供しています。彼らは製品やプラットフォームを通じてサステナビリティの意識を高めることを目指しています。詳細はウェブサイトを訪れ、SNSでフォローしてください。' where id = 'MMmHhlr_60jbbqlZ0M4xy';
update content_bodies set title = 'How to Make Sustainable Mask in 10 MINS | Filter Mask | 3D Cloth Mask Tutorial | PDF Mask Pattern', description = 'IIJYN is a fashion label dedicated to promoting sustainability through fashion. They have developed a DIY sustainable mask pattern that emphasizes comfort, fit, and aesthetics while using eco-friendly materials. This tutorial encourages individuals to create their own masks at home, supporting both personal sustainability efforts and the small business. IIJYN offers various services, including sustainable masks, custom measurements, pattern making, and fashion design. They aim to raise awareness about sustainability through their products and platforms. For more information, visit their website and follow them on social media.' where id = '6pxfc8Q4Ip_R2c_UMIqZC';
update content_bodies set title = 'レイヤードプリーツのフィット＆フレアブラウスの縫い方', description = 'この動画チュートリアルでは、ウエストラインとシルエットを引き立てるフィット＆フレアブラウスの作り方に焦点を当てています。デザインは、下部パネルにレイヤードプリーツを施し、クリーンなカットと構造的なボリュームを強調しています。シンプルでエレガントなボートネックが特徴です。視聴者には、このブラウスを作る挑戦をすることが奨励されています。ファッションワークショップやオーダーメイドサービスに興味がある方は、ウェブサイトやSNSで詳細を確認できます。' where id = 'KNTdn-9C8jR-mYgRmRP7F';
update content_bodies set title = 'How to Sew Fit and Flare Blouse with Layered Pleats', description = 'This video tutorial focuses on creating a fit and flare blouse that enhances the waistline and silhouette. The design features layered pleats on the bottom panel, emphasizing clean cuts and structural volume. The blouse is designed with a simple and elegant bateau neckline. Viewers are encouraged to challenge themselves to make this blouse. For those interested in fashion workshops or made-to-measure services, additional information is available on the website and social media platforms.' where id = 'u-Ii3EAubzoZcLO6lSzS3';
update content_bodies set title = 'スリットワイドレッグサテンパンツの縫い方と完璧に仕上げるための縫製のコツ！', description = 'この動画では、XSサイズのお客様のために作られたスリットワイドレッグサテンパンツの作り方を紹介しています。美しいワインレッドのサテン生地を使用し、デザインから製作までの詳細な手順を示し、ファッション制作における細部へのこだわりを強調しています。視聴者にはコメントや友人へのシェア、オーダーメイドや縫製ワークショップに興味のある方への情報提供を促し、SNSや公式ウェブサイトでの問い合わせも歓迎しています。ファッションデザインと制作に関する貴重な情報を提供し、今後の関連コンテンツの購読を呼びかけています。' where id = 's9Wy6z9j57aOuytyO_wUH';
update content_bodies set title = 'How to sew Slit Wide Legged Satin Pants with sewing tips to make it perfect!', description = 'This video demonstrates how to create Slit Wide Legged Satin Pants tailored for an XS customer, featuring a luxurious wine red satin fabric. It includes detailed instructions on the design and production process, emphasizing meticulous craftsmanship in fashion production. Viewers are encouraged to engage by commenting, sharing with friends interested in made-to-measure clothing or sewing workshops, and reaching out via social media or the official website for inquiries. The video aims to provide valuable insights into fashion design and production, inviting subscriptions for more related content.' where id = '-BVVokA-3iVKV52A-At0P';
update content_bodies set title = '[DIY with ISA] 一日で完売した逆箱ひだスカートの縫い方', description = 'このガイドでは、逆箱ひだスカートの縫い方について詳しい手順を提供しています。パターン生地のカットから最終的な縫製プロセスまでをカバーし、完璧な形を実現することに重点を置いています。チェック柄の生地を使用することで独特の外観を得られることが強調されており、さまざまな種類の生地で作成できることも述べられています。制作者は読者からの質問を歓迎しています。' where id = '6D2Fa-IOVYTenupvabkF_';
update content_bodies set title = 'DIY with ISA: How to sew Inverted Box Pleat Skirt that sold out in one day.', description = 'This guide provides detailed instructions on how to sew an inverted box pleat skirt, covering everything from pattern fabric cutting to the final sewing process. The tutorial emphasizes achieving a perfect shape and suggests using plaid fabrics for a unique appearance. It also notes that the skirt can be made with various types of fabrics. The creators encourage questions from readers.' where id = 'rlVXv_d3oXgO1-bnjOS-b';
