update content_bodies set title = '日本の品格、栃木', description = '栃木県は、日本の品格を静かに保ち続けており、荘厳な文化と豊かな自然が調和しています。この地域は、心を豊かにする上質な体験を提供し、訪れる人々をその独自の魅力で魅了します。' where id = 'rT58V2w1P9VlirOK6inO7';
update content_bodies set title = 'The Grace of Japan, TOCHIGI', description = 'Tochigi Prefecture quietly maintains the elegance of Japan, showcasing its majestic culture and rich natural beauty. This region offers a serene environment that enriches the heart and soul, inviting visitors to experience its unique charm.' where id = 'JlhRljV9cFsFdvx8DxnGO';
update content_bodies set title = '地理的美食「日本の品格、栃木」', description = '栃木県は、日本の品格を静かに保ち続ける場所です。荘厳な文化と豊かな自然が調和し、心を溶かす魅力を持っています。栃木は、心の豊かさを上質に満たすための美意識を大切にし、訪れる人々に深い感動を与えます。' where id = 'XX2poDefUdArOTaElRUvq';
update content_bodies set title = 'Geo Gastronomy ''The Grace of Japan, TOCHIGI''', description = 'Tochigi Prefecture embodies the grace of Japan, characterized by its serene nature and rich historical culture that captivates the heart. The region maintains a quiet dignity, showcasing majestic cultural heritage, abundant natural beauty, and a refined aesthetic sense. It offers a fulfilling experience for the soul.' where id = 'lXq9eSzh-XiBVVs8jZS90';
update content_bodies set title = '日本の品格、栃木', description = '栃木県は、日本の品格を静かに保ち続けています。荘厳な文化と豊かな自然が調和し、心を打つ美しさを提供します。栃木の穏やかな環境と歴史的な意義は、心の豊かさを上質に満たしてくれるでしょう。' where id = 'ytdD2x2rUXszrRvJdzI_S';
update content_bodies set title = 'The Grace of Japan, TOCHIGI', description = 'Tochigi Prefecture quietly maintains the elegance of Japan, showcasing its majestic culture and rich natural beauty. The serene environment and historical significance of Tochigi are sure to touch your heart, offering a refined sense of fulfillment and appreciation for nature and culture.' where id = 'JlfQBp_zV4XOLW_3du0Ar';
update content_bodies set title = '文化の源。"日本の品格、栃木"', description = '栃木県は、心ある手仕事や温かい人々、哲学のある生活を体現しています。シンプルで優雅な暮らしが特徴で、素朴な日常風景が広がっています。穏やかな自然と荘厳な文化が調和し、訪れる人々に豊かな体験を提供します。栃木は日本文化の品格を静かに保ち続けており、豊かな自然環境と美意識が心を満たしてくれます。栃木の優雅さと文化遺産をぜひ体験してください。' where id = 'eoz04sPdwcTNgnSzEE9XU';
update content_bodies set title = 'Source of culture. "The Grace of Japan, TOCHIGI"', description = 'Tochigi, a region in Japan, embodies a unique blend of heartfelt craftsmanship, warm-hearted people, and a life steeped in philosophy. It promotes a simple yet elegant lifestyle, characterized by its rustic everyday scenery. The area is known for its peaceful nature and majestic historical culture, which together create an enriching experience for visitors. Tochigi quietly maintains the dignity of Japanese culture, offering a rich natural environment and a refined aesthetic that fills the heart with a sense of abundance. Discover the grace of Tochigi and its cultural heritage.' where id = 'yZxrrRDkT4sN67SvYzunq';
update content_bodies set title = 'ワイルドウィンターアクティビティ。「日本の品格、栃木」', description = '日光国立公園でのプレミアムな冬の体験。森の中でのスノーシューや、雄大な白い景色の中でのスノーボードを楽しむことができます。氷瀑の前に佇む日本旅館の独特な雰囲気を味わい、新鮮な冬の味覚を堪能してください。この冬の冒険は、静かな自然と豊かな歴史文化が心を温める栃木の本質を体現しています。' where id = 'hFaZWroOcYgSeImWMEAg1';
update content_bodies set title = 'Wild Winter Activity. "The Grace of Japan, TOCHIGI"', description = 'Experience a premium winter in Nikko National Park, Tochigi. Engage in snowshoeing through serene forests and snowboarding amidst breathtaking white landscapes. Enjoy the unique ambiance of a traditional Japanese ryokan located near an icefall, and savor fresh winter delicacies. This winter adventure encapsulates the essence of Tochigi, where the tranquil nature and rich historical culture create a heartwarming experience.' where id = 'M31sGRFlYbGev5lt1JPDO';
update content_bodies set title = '歴史的文化。「日本の優雅さ、栃木」', description = '栃木は、山伏と呼ばれる巡礼の山の仏教僧たちの伝統に根ざした古来の文化に満ちています。この地域には、世界遺産に登録された美しい日光東照宮、8世紀の重要な輪王寺、そして二荒山の三つの聖なる山を祀る二荒山神社があります。訪れる人々は、煌びやかな金箔の木製像や、風光明媚な巴波川沿いに立ち並ぶ伝統的な蔵を楽しむことができます。また、現代の浮世絵師によって描かれた栃木の歴史的な絵図もあり、その豊かな文化遺産を感じることができます。' where id = '32MKQuLR7zV7BYKzcwn5w';
update content_bodies set title = 'Historical Culture. "The Grace of Japan, TOCHIGI"', description = 'Tochigi is steeped in ancient culture, rooted in the traditions of the traveling mountain Buddhist monks known as Yamabushi. The region is home to UNESCO World Heritage sites, including the beautifully adorned Toshogu Shrine, the important 8th-century Rinnoji Temple, and the Futarasan Shrine, which honors Nikko''s three sacred mountains. Visitors can admire the exquisite gold lacquered wooden statues and the traditional Kura storehouses that line the scenic Uzumagawa River. Additionally, a modern Ukiyo-e artist has created a historical depiction of Tochigi, capturing its rich cultural heritage.' where id = 'G8t3YY5IQXpBFLyijp7hf';
update content_bodies set title = '【ひらり平川びより】盛美園と農家庭園', description = 'この動画では、盛美園と農家庭園について紹介しています。盛美園は美しい庭園で、訪れる人々に自然の美しさを提供しています。また、農家庭園では、農業の魅力や地域の特産品について学ぶことができます。これらの場所は、観光客や地元の人々にとって、リラックスできる空間となっています。' where id = 'By-fDZZHtFdq1XFDg9N6D';
update content_bodies set title = 'Hirari Hirakawa Biyori: Seibi-en and Agricultural Garden', description = 'This video introduces Seibi-en and the Agricultural Garden.' where id = 'r784Xk4X3cDIA20SfTIpD';
update content_bodies set title = 'ひらり平川びより', description = 'この文章では、平川の温泉めぐりについて触れていますが、特に新屋温泉が閉業したことが記されています。温泉の魅力や観光スポットについての詳細は記載されていないため、平川の他の温泉についての情報は含まれていません。新屋温泉の閉業は、訪れる人々にとって残念なニュースであり、平川の温泉文化に影響を与える可能性があります。' where id = 'bVKwWM0mCj__mVtto-yTh';
