update content_bodies set title = '【ひらり平川びより】世界一の扇ねぷた', description = 'この動画では、世界一の扇ねぷたについて詳しく紹介しています。扇ねぷたは、特にその美しさと独自のデザインで知られており、地域の文化や伝統を反映しています。視聴者は、この素晴らしいアートの背後にあるストーリーや制作過程を知ることができ、扇ねぷたの魅力を再発見することができます。' where id = 'bPrJgpvFtDQEAkwGPm5eu';
update content_bodies set title = 'Hirari Hirakawa Biyori: The World''s Best Fan Nebuta', description = 'This video introduces the world''s best fan nebuta.' where id = '34IryHKqseXANExZh-7V5';
update content_bodies set title = '【ひらり平川びより】猿賀公園の蓮', description = 'この動画では、猿賀公園に咲く蓮の魅力を紹介しています。蓮は美しい花を咲かせることで知られ、多くの人々に親しまれています。猿賀公園はその蓮の名所としても有名で、訪れる人々に癒しのひとときを提供しています。' where id = 'Q1VGppYGIvIBWNFDCU1Wk';
update content_bodies set title = 'Hirari Hirakawa Biyori: Lotus at Saruka Park', description = 'This video introduces the lotus flowers at Saruka Park.' where id = 's1kUmk7dF_eugsy-bvN8m';
