update content_bodies set title = '【ひらり平川びより】平川の桃', description = 'この動画では、平川の桃について紹介しています。平川の桃はその特性や魅力を伝える内容となっており、視聴者に地域の特産品としての桃の魅力を知ってもらうことを目的としています。' where id = 'OPVyPHDgrDKTG155SWZbn';
