update content_bodies set title = '【ひらり平川びより】平川サガリ', description = 'この動画では、平川サガリについて紹介しています。平川サガリは、特定の地域や文化に関連する内容であり、視聴者にその魅力や特徴を伝えることを目的としています。' where id = 'K1wD7IT-5ZX9KQud18_SD';
update content_bodies set title = 'Hirari Hirakawa Biyori: Hirakawa Sagari', description = 'This video introduces Hirakawa Sagari.' where id = 'Ols7MPSMfV0iupfJawbx5';
update content_bodies set title = '弘南鉄道の夕景', description = 'この動画では、弘南鉄道の美しい夕景を紹介しています。夕暮れ時の風景は、鉄道の魅力を引き立て、訪れる人々に感動を与えます。特に、夕日が沈む瞬間や、周囲の自然との調和が見どころです。弘南鉄道の沿線には、四季折々の風景が広がり、夕景はその中でも特に印象的です。この動画を通じて、弘南鉄道の夕景の美しさを感じていただければ幸いです。' where id = 'Dk8gzPkx49D51xDyvP6yy';
update content_bodies set title = 'Evening Scenery of Konan Railway', description = 'This video introduces the evening scenery of the Konan Railway.' where id = 'WQOBzlSHQnmyyKGjtPH9P';
update content_bodies set title = '観光編～いいとこいっぱい平川市', description = '平川市は四季折々の魅力にあふれています。春には猿賀公園の池が桜の花で覆われ、絵のような美しさを見せます。夏には活気あふれるねぷた祭りが開催され、華やかな山車や伝統的なパフォーマンスが楽しめます。秋は実りの季節で、美味しい地元の食材が笑顔をもたらします。冬には寒さを和らげる多くの温泉があり、津軽平野のこの町で温かさと癒しを提供しています。' where id = '4h3bkyWm4r_BxwAg8GAj6';
update content_bodies set title = 'Tourism Edition - Plenty of Good Places in Hirakawa City', description = 'Hirakawa City offers a variety of attractions throughout the year. In spring, the pond at Saruka Park is covered with cherry blossoms, creating a picturesque scene. Summer brings the energetic Neputa Festival, showcasing vibrant floats and traditional performances. Autumn is a time for harvest, with delicious local produce that brings smiles to faces. In winter, the cold is alleviated by numerous hot springs, providing warmth and relaxation in this Tsugaru Plain town.' where id = 't4ZVlRB6fAB8lp2pxU9Ke';
update content_bodies set title = '物産編～うめぇものいっぱい平川市', description = '津軽平野の豊かな自然と寒暖の中で育まれた米、りんご、桃、高冷地野菜が揃う平川市は、美味しさがいっぱいあふれています。地元の特産品は、自然の恵みを受けた高品質な食材として、多くの人々に愛されています。' where id = 'rHmxv1vduyWZmanDHMb0Y';
update content_bodies set title = 'Local Delicacies of Hirakawa City', description = 'Hirakawa City is rich in delicious foods, nurtured by the abundant nature of the Tsugaru Plain and the variations in temperature. The area is known for its high-quality rice, apples, peaches, and highland vegetables.' where id = 'koifsH-ZBxsi8eeDFdBpn';
update content_bodies set title = '移住編～便利な田舎（青森県平川市）', description = '平川市のキャッチフレーズは「時と水ゆったり流れる平川市」です。このイメージ通り、広々とした充実した生活環境が整っており、「住みよさランキング」でも高い評価を得ています。' where id = 'lyTvY6aww7EgS-UTJiOGV';
update content_bodies set title = 'Migration Edition - Convenient Countryside (Hirakawa City, Aomori Prefecture)', description = 'Hirakawa City''s catchphrase is ''Time and water flow gently in Hirakawa City.'' True to this image, the city offers a spacious and fulfilling living environment, which has received high ratings in the ''Livability Ranking.''' where id = 'eCkqfqwanatlQ_Ed4Ei7b';
update content_bodies set title = '大槌ジビエツーリズム：英語ver】ジビエを通じて命を学ぶ', description = '2022年ゴールデンウィークプランの参加者を募集中です。プロハンターによる狩猟同行（5/4-5）、ハンター直伝の解体体験（5/7）、アニマルトラッキング（5/3）、若手ハンターとのプチ狩猟体験とジビエBBQランチ（5/1・22）などの活動があります。2021年から本格的に始まったこのジビエツーリズムは、「三陸・大槌の自然を体感し、ジビエを通じて命を学ぶ。」をキャッチコピーに、参加者の感想やツーリズムのコンセプト、スタッフからのメッセージを通じてその様子をお伝えします。' where id = 'xSZ8ZHnqedIM3y1dhXwok';
update content_bodies set title = 'Otsuchi Game Tourism: Learning About Life Through Game', description = 'The Otsuchi Game Tourism program is currently recruiting participants for the 2022 Golden Week plans. Activities include hunting with professional hunters from May 4-5, a butchering experience on May 7, animal tracking on May 3, and a mini hunting experience with young hunters along with a game BBQ lunch on May 1 and 22. Launched in 2021, the program aims to immerse participants in the natural beauty of Sanriku and teach them about life through game. The tourism concept is shared through participant feedback, the program''s philosophy, and messages from the staff.' where id = '3CSm3XhGsPMMWL_q-jD9t';
update content_bodies set title = '佐渡で遊ぶ・体験する編', description = '今回のテーマは『佐渡で遊ぶ・体験する』です。佐渡の魅力を存分に楽しむための情報が提供されています。観光情報は、公式サイトの https://www.visitsado.com で確認できます。また、旅行プランを立てる方は https://www.visitsado.com/tabiiro/ を、旅行中の方はリアルタイム情報を https://www.visitsado.com/realtime/ でチェックしてください。' where id = 'DSWkiFa0dhOFpgSNSgBSo';
update content_bodies set title = 'Experiencing and Playing in Sado', description = 'The theme of this content is ''Experiencing and Playing in Sado.'' Enjoy the charm of Sado as you explore various activities and experiences available on the island. For more information on Sado''s attractions, visit https://www.visitsado.com. If you''re planning a trip to Sado, check out travel plans at https://www.visitsado.com/tabiiro/. For those currently traveling in Sado, real-time information can be found at https://www.visitsado.com/realtime/.' where id = 'uP4BUnbvzxx0z_oyZUiIb';
