update content_bodies set title = '『佐渡に暮らすように旅する』Eバイクの旅　両津編', description = '佐渡市では、コロナ禍における人との接触を避け、環境負荷の少ない持続可能な旅行形態やアウトドアへのニーズに応えるため、Eバイクを活用した新たな観光ビジネスモデルの構築を目指す補助事業を実施しています。『佐渡に暮らすように旅する』をテーマに、首都圏の独身男女に向けて、動画やSNSを通じて観光意欲を促進します。物語は、佐渡在住の「りか」とその友人「マルタ」を中心に展開されます。両津編では、マルタが両津港に到着し、観光案内所でEバイクをレンタルしてりかと合流。二人はEバイクで加茂湖を一周しながら、おすすめスポットを紹介します。' where id = 'GcG6C1qmEx5ubz0SrKARa';
update content_bodies set title = 'Traveling Like Living in Sado: E-Bike Journey - Ryotsu Edition', description = 'In Sado City, a new tourism business model utilizing E-bikes is being developed in response to the increased demand for sustainable travel, outdoor activities, and minimizing contact during the COVID-19 pandemic. The initiative, themed ''Traveling Like Living in Sado,'' targets single men and women from the Tokyo metropolitan area, promoting tourism through videos and social media. The story revolves around ''Rika,'' a local resident, and her friend ''Marta.'' In the Ryotsu edition, Marta arrives at Ryotsu Port, rents an E-bike at the tourist information center, and meets Rika. Together, they cycle around Kamo Lake, introducing recommended spots along the way.' where id = 'mfMT8r2yFR65ee2NeCloZ';
update content_bodies set title = '『佐渡に暮らすように旅する』Eバイクの旅　小木編', description = '佐渡市では、コロナ禍における人との接触を避け、環境負荷の少ない持続可能な旅行形態やアウトドアへのニーズに応えるため、Eバイクを活用した新たな観光ビジネスモデルの構築を目指す補助事業を実施しています。『佐渡に暮らすように旅する』をテーマに、首都圏の独身男女に向けて、動画やSNSを通じて観光意欲を促進します。物語は、佐渡在住の「りか」とその友人「マルタ」を中心に展開され、マリンプラザ小木でEバイクをレンタルし、矢島や経島、宿根木集落などのフォトスポットを紹介します。' where id = 'pW5qt_WaPQzxWjZVq1cus';
update content_bodies set title = 'Traveling Like Living in Sado: E-Bike Journey - Ogi Edition', description = 'In Sado City, a new tourism business model utilizing E-bikes is being developed in response to the increased demand for sustainable travel methods, outdoor activities, and minimizing contact during the COVID-19 pandemic. The initiative, themed ''Traveling Like Living in Sado,'' targets single men and women from the Tokyo metropolitan area, promoting tourism interest through videos and social media. The story revolves around ''Rika,'' a local resident, and her friend ''Marta,'' who rent E-bikes at Marine Plaza Ogi. They explore and introduce photo spots such as Yajima, Keishima, and the Sukune village.' where id = 'OXEnlrbuRJ_TDhffZGgED';
update content_bodies set title = '『佐渡に暮らすように旅する』Eバイクの旅　相川編', description = '佐渡市では、コロナ禍における人との接触を避け、環境負荷の少ない持続可能な旅行形態やアウトドアへのニーズに応えるため、Eバイクを活用した新たな観光ビジネスモデルの構築を目指す補助事業を実施しています。『佐渡に暮らすように旅する』をテーマに、首都圏の独身男女に向けて、動画やSNSを通じて観光意欲を促進します。物語は佐渡在住の「りか」とその友人「マルタ」を中心に展開され、相川編では、きらりうむ佐渡からスタートし、佐渡金山や北沢浮遊選鉱場跡、京町通りをEバイクで巡ります。' where id = 'Q2jYOA6kiIRzk8k8JT8i-';
update content_bodies set title = 'Traveling Like Living in Sado: E-Bike Journey - Aikawa Edition', description = 'In Sado City, a new tourism business model utilizing E-bikes is being developed in response to the increased demand for sustainable travel, outdoor activities, and minimizing contact during the COVID-19 pandemic. The initiative, themed ''Traveling Like Living in Sado,'' targets single men and women in the Tokyo metropolitan area, promoting tourism through videos and social media. The story revolves around ''Rika,'' a Sado resident, and her friend ''Marta.'' The Aikawa edition begins with cycling around the Aikawa area, starting from Kirarirum Sado, and includes visits to Sado Kinzan, the Kitazawa Flotation Concentration Plant ruins, and Kyomachi Street.' where id = 'oeApymrjR4iXNlvT4ytLw';
update content_bodies set title = '佐渡市クルーズ船寄港の様子', description = '佐渡島は新潟県沖合に位置し、面積約855平方キロメートル、海岸線約280kmを持つ日本海側最大の離島です。島の気候は沖合の海流の影響で温暖で、降雪量も少なく、様々な植物が自生しています。また、海産物や米、果樹など多様な農産物が豊富で、年間を通じて食材に恵まれています。2024年7月27日には佐渡の金山が世界文化遺産に登録され、見どころが多く、クルーズ船で訪れるお客様にも心に残るおもてなしを目指しています。クルーズ船の運用者には、ぜひ佐渡島への寄港を計画していただきたいです。' where id = 'LkIJ8IFrTp9Lld0Su5p0o';
update content_bodies set title = 'Cruise Ship Port Call in Sado City', description = 'Sado Island, located off the coast of Niigata Prefecture, is Japan''s largest offshore island, covering approximately 855 square kilometers with a coastline of about 280 km. The island enjoys a milder climate compared to the mainland due to the influence of ocean currents, resulting in less snowfall. It is home to a diverse range of flora and boasts an abundance of seafood, rice, and various agricultural products throughout the year. On July 27, 2024, Sado''s gold mine will be registered as a UNESCO World Heritage Site, offering numerous attractions. The aim is to provide memorable hospitality to visitors arriving by cruise ship. We encourage cruise operators to plan port calls to Sado Island.' where id = 'sdmx7qOe3L5H2B4x0O5Ff';
update content_bodies set title = '佐渡島、忘るべからず。二ツ亀編', description = 'この動画は、佐渡島の魅力を伝える内容で、特に二ツ亀に焦点を当てています。佐渡島はその美しい自然や文化的な背景で知られており、視聴者にその魅力を再認識させることを目的としています。' where id = '3RnywIw8GjmnL7pM0_2dS';
