update content_bodies set title = 'Sado''s Delicious Cuisine', description = 'Discover the unique culinary offerings of Sado Island, located in Niigata, Japan. This destination promises a delightful experience for food lovers, showcasing the rich flavors and diverse dishes that Sado has to offer. For more information, visit the official website.' where id = 'Uwv3JonxwaHH1d6wTB2tH';
