update content_bodies set title = 'Marvelous Sado', description = 'Discover Sado Island, a unique destination in Niigata, Japan. Experience an unparalleled island life that offers a different perspective of Japan.' where id = 'jgGDqAVSUvacUpEq82ouc';
update content_bodies set title = '佐渡島で体験するミニ日本', description = '佐渡島では、美しい景色と自然を楽しみながら、ミニ日本を体験できます。焚き火での能のパフォーマンスや、美味しい海鮮料理を味わうことができ、鬼の舞で知られるこの島の文化的な雰囲気に浸ることができます。' where id = 'zRuCGyGsVXSQIz9sOP2Ri';
update content_bodies set title = 'Mini Japan right here at Sado Island', description = 'Sado Island offers a unique experience of a mini Japan, featuring beautiful scenery and nature. Visitors can enjoy bonfire noh performances and indulge in delicious seafood, all while being immersed in the cultural atmosphere of the island known for its demon dance.' where id = 'UEecm11oneOoTZz40rMHM';
update content_bodies set title = '佐渡島で体験するミニ日本', description = '佐渡島では、美しい景色と自然を楽しむことができるミニ日本の体験が待っています。訪れる人々は、焚き火での能楽のパフォーマンスを楽しんだり、美味しい海鮮料理を味わったりしながら、鬼の舞で知られるこの島の文化遺産に浸ることができます。' where id = '2_SNGGcB9xZWH04CJwd93';
update content_bodies set title = 'Mini Japan right here at Sado Island', description = 'Sado Island offers a unique experience of a mini Japan, featuring stunning scenery and nature. Visitors can enjoy bonfire noh performances and savor delicious seafood, all while immersing themselves in the cultural heritage of the island known for its demon dance.' where id = 'hK7K_OLGacD8JqKNH3XCP';
update content_bodies set title = '佐渡市クルーズ船寄港地', description = '佐渡島は新潟県の沖合に位置し、日本海で最大の島で、面積は約855平方キロメートル、海岸線は約280キロメートルです。対馬暖流の影響により、佐渡島の気候は温暖で、内陸部に比べて降雪が少ないです。島には寒暖両方の気候に適した多様な植物が生息し、海産物や米、果物などの農産物も豊富で、年間を通じて食に恵まれています。2024年7月27日には佐渡島の金山がユネスコ世界遺産に登録され、島の魅力がさらに増しました。私たちは、クルーズ船やその他の手段で訪れるゲストに思い出に残るおもてなしを提供することを目指しています。ツアーオペレーターやクルーズ船の主催者には、佐渡島を将来の寄港地として検討することをお勧めします。' where id = 'gvhmlxgSRkyFlMAFsk2k1';
update content_bodies set title = 'Sado City Cruise Ship Port of Call', description = 'Sado Island, the largest island in the Sea of Japan, is situated off the coast of Niigata Prefecture, covering approximately 855 square kilometers with a coastline of about 280 km. The island enjoys a milder climate with less snowfall due to the Tsushima Warm Current, supporting a diverse range of both cold and warm climate plants. Sado is rich in marine and agricultural products, including rice and fruits, ensuring a year-round food supply. The Sado Island Gold Mines were added to the UNESCO World Heritage List on July 27, 2024, enhancing the island''s attractions. We aim to provide memorable hospitality to our visitors, whether they arrive by cruise ship or other means. We invite tour operators and cruise ship organizers to consider Sado Island as a future port of call.' where id = 'u1lbRhUY6w4PVBBpTy3OL';
update content_bodies set title = '余部鉄橋　最後のサクラ', description = '余部鉄橋の架け替え工事が行われるため、今年の春（平成20年・2008年）でこのサクラの風景が見納めとなります。長年親しまれてきたこの美しい景色が、再び見ることができなくなることを惜しむ声が多く寄せられています。桜の季節に訪れる人々にとって、余部鉄橋のサクラは特別な存在であり、その風景は心に残る思い出となるでしょう。' where id = 'pVMQNqUtDcpmRBAesb-Eh';
update content_bodies set title = 'Last Cherry Blossoms at Ayabe Bridge', description = 'Due to the reconstruction work of the Ayabe Bridge, this spring (2008) will be the last opportunity to see the cherry blossom scenery.' where id = '75YjQ4dFPvuR-lkyF_FNO';
update content_bodies set title = '鉄橋下からの眺め【２８秒】', description = 'この映像は余部鉄橋の下からの眺めを捉えたもので、写っているのはJR山陰本線の普通列車キハ47の2両編成です。浜坂方には加古川色（ブルー）の車両が見えます。転属後しばらくの間は元の塗装で運用されていました。' where id = 'bpDrdbCINyhtSWL_rH6bj';
update content_bodies set title = 'View from Under the Iron Bridge [28 seconds]', description = 'This video captures the view from under the Ayabe Iron Bridge, featuring a two-car train of the JR San''in Main Line, specifically the Kiha 47 series. The train heading towards Hamasaka is painted in the Kakogawa color scheme (blue). After being transferred, the train operated for a while in its original paint scheme.' where id = 'q8_GOMHvRKEWXy85nZwv1';
update content_bodies set title = '町民号サロンカーなにわ【４４秒】', description = 'この映像は、平成19年（2007年）6月15日と16日に行われた香美町町民号旅行で運行された「サロンカーなにわ」を紹介しています。' where id = 'ZduhVmruBfC83ngIajIZq';
update content_bodies set title = 'Town Citizen Train Salon Car Naniwa [44 seconds]', description = 'This video features the ''Salon Car Naniwa'' that was operated during the Kōmi Town citizen trip held on June 15 and 16, 2007.' where id = 'BI8ceuNmzZ7ZvsgPK2Fav';
update content_bodies set title = '晴れの国おかやま', description = '日本の西部に位置する「晴れの国おかやま」は、歴史情緒漂う高梁地域の魅力を紹介します。この地域は、歴史的な魅力と文化的な重要性で知られています。' where id = 'KyVyYF2uEi_v1kghCR8tF';
update content_bodies set title = 'The Land Of Sunshine OKAYAMA', description = 'Okayama, located in western Japan and known as the ''Land of Sunshine,'' is home to the historically rich Takahashi region. This area is celebrated for its historical charm and cultural significance.' where id = 'GZ5qPQ4f0balQdr1n7T7n';
update content_bodies set title = 'さようなら寝台特急「出雲号」～フルバージョン～', description = '寝台特急「出雲号」は昭和47年3月にデビューし、山陰地方と東京を山陰本線経由で結ぶ重要な交通手段として活躍してきました。2006年3月18日（土）朝7時25分、余部鉄橋を少し遅れて通過し、多くのファンに見送られながら走り去りました。この日は「出雲号」の運行終了を惜しむ人々で賑わい、長い歴史に幕を下ろしました。' where id = 'TgVkO32KV6B-o5Q7HjcF0';
update content_bodies set title = 'Farewell to the Sleeper Limited Express ''Izumo'' - Full Version', description = 'The sleeper limited express ''Izumo'' debuted in March 1972, connecting the San''in region to Tokyo via the San''in Main Line. It served as a vital transportation link for locals traveling to Tokyo. On March 18, 2006, at 7:25 AM, the train passed the Ayabe Bridge, slightly delayed, as many fans gathered to bid farewell. The train departed, marking the end of an era for this beloved service.' where id = 'x0v-FfdeylNO47nQKtCW3';
update content_bodies set title = '１月の香美町', description = '2021年1月に撮影されたこの作品は、香美町の風景を紹介しています。香住海岸、和池の大カツラ、うへ山の棚田、かえる島など、町の美しいスポットが含まれています。' where id = '3XbMu10hXrp0JZ635xMJT';
update content_bodies set title = 'Kōbichō in January', description = 'Photographed in January 2021, this piece highlights various scenic spots in Kōbichō, including the Kasumi Coast, the large Katsura tree at Waki, the terraced rice fields of Uhe Mountain, and Kaeru Island.' where id = 'nmLEeWqkdD2tk2FLnxiOT';
update content_bodies set title = '香美体験～山陰海岸ジオパーク～', description = '山陰海岸ジオパークは、京都府京丹後市、兵庫県豊岡市・新温泉町、香美町、鳥取県鳥取市・岩美町の6つの市町から成り、日本海に面しています。その美しい地形や地質の貴重さから、ユネスコ世界ジオパークに認定されています。香美町ならではの体験を、美しい自然の中で楽しむことができます。PR映像でその魅力をお楽しみください。また、香美町をもっと楽しむためには、公式観光アプリの利用をおすすめします。アプリのリンクはこちらです： https://kami-tabi.jp/' where id = 'quve67_8agsKz3e3kBjWx';
update content_bodies set title = 'Kami Experience - San''in Kaigan Geopark', description = 'The San''in Kaigan Geopark consists of six cities and towns facing the Sea of Japan, including Kyotango City in Kyoto Prefecture, Toyooka City, Shinonsen Town, and Kami Town in Hyogo Prefecture, as well as Tottori City and Iwami Town in Tottori Prefecture. It has been designated as a UNESCO Global Geopark due to its beautiful landscapes and valuable geological features. Enjoy unique experiences in the beautiful nature of Kami Town through promotional videos! For more enjoyment in Kami Town, the official tourism app is recommended: https://kami-tabi.jp/' where id = 'rFnr58Ojh-AnpAz705veF';
update content_bodies set title = 'TWILIGHT EXPRESS 瑞風 in 兵庫県香美町', description = 'JR西日本の豪華寝台列車「TWILIGHT EXPRESS 瑞風」は、山陰コースを運行し、画聖応挙と維新の歴史をたどる旅を提供します。2021年10月23日から、兵庫県北部の香美町香住にある大乗寺（応挙寺）が立ち寄り地となり、運行初日の町の歓迎の様子が紹介されています。今後の運行予定日は2月3日、17日、3月30日で、香住駅への到着予定時刻は15時03分です。' where id = 'fvZk5k7-gAdZPbKRxA7vB';
update content_bodies set title = 'TWILIGHT EXPRESS MIZUKAZE in Kamitown, Hyogo Prefecture', description = 'The luxurious sleeper train ''TWILIGHT EXPRESS MIZUKAZE'' operated by JR West offers a journey along the San''in coast, tracing the history of the painter Okyo and the Meiji Restoration. Starting from October 23, 2021, the train makes a stop at Daijoji Temple (Okyo-ji) in Kasumi, Kamitown, located in northern Hyogo Prefecture along the Sea of Japan. This summary highlights the welcoming atmosphere of the town on the train''s inaugural day. Future operation dates include February 3 and 17, and March 30, with the expected arrival time at Kasumi Station being 15:03.' where id = 'f8AZtslo98QtaMxTVvQYX';
update content_bodies set title = '香美町ドローンPR映像（海編）', description = '山陰海岸ジオパークは、京都府京丹後市、兵庫県豊岡市・新温泉町、香美町、鳥取県鳥取市・岩美町の6つの市町から成り、日本海に面した美しい地形や地質の貴重さからユネスコ世界ジオパークに認定されています。このPR映像では、香美町の美しい自然を楽しむことができます。香美町をもっと楽しむためには、公式観光アプリ「kami-tabi」をおすすめします。' where id = 'VmEPpHuQzEY9GE3bcg2Lz';
update content_bodies set title = 'Kōbichō Drone PR Video (Sea Edition)', description = 'The San''in Kaigan Geopark consists of six cities and towns facing the Sea of Japan, including Kyotango City in Kyoto Prefecture, Toyooka City and Shinonsen Town in Hyogo Prefecture, Kōbichō, and Tottori City and Iwami Town in Tottori Prefecture. It has been recognized as a UNESCO Global Geopark due to its beautiful terrain and valuable geological features. Enjoy the stunning natural beauty of Kōbichō through this promotional video. For a more enjoyable experience in Kōbichō, we recommend the official tourism app ''kami-tabi'' at https://kami-tabi.jp/' where id = '_w1RroqvjeDDPexLayofQ';
update content_bodies set title = 'かすみ海上GEO TAXI 90分コースダイジェスト', description = '「かすみ海上GEO TAXI」は、香住の絶景スポットを小型船で巡る体験を提供します。このサービスの大きな特徴は、大きな船では近づくことが難しい洞門や島にアクセスできる点です。' where id = 'f2xORbitCHmOsIeUu57GW';
update content_bodies set title = 'KASUMI Marine GEO TAXI 90-Minute Course Digest', description = 'The ''KASUMI Marine GEO TAXI'' offers a unique experience of exploring scenic spots in Kasumi by small boat. One of its main features is the ability to access caves and islands that are difficult to reach with larger vessels.' where id = 'iARaDiRQqu9q0Pq0Xa_56';
update content_bodies set title = '360°VR動画で但馬を旅しよう！　～かすみ海上 GEO TAXI（ジオタクシー）～', description = 'この動画は360°VR動画で、パソコンでは画面をドラッグすることで全方位を見渡せ、スマホでは傾けることで同様に楽しめます。かすみ海上GEO TAXIは、ユネスコ世界ジオパークに認定された山陰海岸国立公園の中心地、香住海岸の絶景スポットを小型船で巡る観光遊覧です。大型船では近づけない洞門にも入ることができ、自然の神秘を間近で感じることができます。詳細はかすみ海上GEO TAXIのウェブサイトや、たじま旅ネットで但馬の観光情報を検索してください。' where id = 'J0shpX_TcfeFvLtgcCNea';
update content_bodies set title = 'Explore Tajima with 360° VR Video! - Kasumi Marine GEO TAXI', description = 'This video is a 360° VR experience. For those viewing on a computer, you can drag the screen to look around in all directions. If you''re watching on a smartphone, tilting the device allows you to explore the 360° view. The Kasumi Marine GEO TAXI offers a unique sightseeing experience in the center of the San''in Kaigan National Park, a UNESCO Global Geopark. You can tour stunning spots along the Kasumi Coast on a small boat, gaining access to caves that are difficult to approach with larger vessels, allowing you to experience the mysteries of nature up close. For more information, visit the Kasumi Marine GEO TAXI website or search for Tajima tourism information on the Tajima Travel Network.' where id = 'gQkVeMrG806L0XgbmEoBf';
update content_bodies set title = '香美町動画コンテスト　優秀賞　「3つの特性を持つまち　香美町」', description = '香美町動画コンテストで優秀賞を受賞したのは、鳥取県のFJ様による「3つの特性を持つまち　香美町」という動画です。作者は、変化の激しい現代において、変わらないものの価値を重視し、香美町の3つの特性を通じてその価値を表現しました。動画を通じて、視聴者に香美町を訪れたいと思ってもらえることを願っています。講評では、ドローンを駆使した美しい描写や、映像のトーンへの細やかな配慮が評価されました。自然風景の繊細かつ大胆な描写や、テンポの良い画面切り替え、タイトル画面のデザインも高く評価されています。確かな撮影・編集技術が感じられ、香美町の自然や文化を美しく描いたこの作品が多くの人に見られることを期待しています。' where id = 'mj7xsBHndJgNemK_ZGaVI';
update content_bodies set title = 'Kōbichō Video Contest Excellence Award: ''A Town with Three Characteristics - Kōbichō''', description = 'The Kōbichō Video Contest awarded the Excellence Award to the video titled ''A Town with Three Characteristics - Kōbichō'' by FJ from Tottori Prefecture. The creator believes that in a rapidly changing world, the value of unchanging things is significant. Through the three characteristics of Kōbichō, the video expresses this enduring value, hoping to inspire viewers to visit the town. The judges praised the work for its beautiful depiction of the three districts of Kōbichō, utilizing drone footage effectively. The attention to detail in the video’s tone, the delicate yet bold portrayal of natural landscapes, and the well-paced transitions were noted. The design of the title screen also showcased a good sense of aesthetics. The creator demonstrated solid filming and editing skills, and the judges hope that this beautiful representation of Kōbichō''s nature and culture will attract more visitors.' where id = 'Sv4FoLHMpLLKeHoWw63Pr';
update content_bodies set title = '香美町動画コンテスト　特別賞　「緑と青の町」', description = '香美町動画コンテストで特別賞を受賞したのは、西宮市の木下直也氏による「緑と青の町」という作品です。木下氏は、この映像を通じて香美町の自然の豊かさを伝えたいと考え、特にコロナ自粛で疲れた学生をターゲットにしました。彼は香美町の絶景スポットを知ってもらいたいと願い、緑と青に囲まれたリラックスできる町の魅力を表現しました。映像は手持ち撮影とドローン撮影を駆使し、静かな音楽で落ち着いた雰囲気を演出しています。カラーグレーディングは控えめで、香美町の本来の色を映し出しています。このコンテストは、香美町の暮らしや自然の魅力を伝える動画を募集しており、個人やグループ、プロ・アマ問わず応募可能です。' where id = '8BdIe0v4Uwj_gGXtj5tx2';
update content_bodies set title = 'Kōbichō Video Contest Special Award: ''Town of Green and Blue''', description = 'The Kōbichō Video Contest awarded a special prize to the video titled ''Town of Green and Blue'' by Naoya Kinoshita from Nishinomiya City. The creator aimed to showcase the natural richness of Kōbichō, targeting students feeling fatigued from COVID-19 restrictions. Kinoshita wanted to highlight the breathtaking spots in Kōbichō, which he found to be a relaxing town surrounded by greenery and blue skies. The video features dynamic handheld and drone footage, complemented by tranquil music to create a calming atmosphere. Minimal color grading was used to reflect the town''s natural colors. The contest invites videos that convey the charm of Kōbichō''s lifestyle and nature, with submissions accepted from individuals and groups, both professional and amateur, from within and outside the town.' where id = 'lvY5-sHLdodruHr7USDjz';
update content_bodies set title = '香美町動画コンテスト　特別賞　「ふるさと」', description = '香美町動画コンテストで特別賞を受賞したのは、Riiさんが制作した「ふるさと」という動画です。コロナ禍で帰省できない家族に喜んでもらうため、幼少期に見た景色を取り入れ、懐かしさを感じさせる内容に仕上げました。この動画を通じて、香美町に興味を持ち、訪れたり住んだりしたいと思ってもらえることを願っています。香美町動画コンテストは、香美町の暮らしや自然の魅力を伝える動画を募集し、町の魅力を発掘・向上させることを目的としています。応募資格は不問で、2021年7月1日から9月30日までの期間に、30秒から90秒の動画を募集しました。最優秀賞には30万円、優秀賞には10万円、特別賞には各3万円が贈られます。' where id = 'dcalPT2KknmV9OtlAufRg';
update content_bodies set title = 'Kōbichō Video Contest Special Award ''Hometown''', description = 'The Kōbichō Video Contest awarded a Special Award to the video titled ''Hometown'' by Rii, a resident of Kōbichō. The creator aimed to evoke nostalgia for family members who couldn''t return home during the COVID-19 pandemic by incorporating familiar landscapes from their childhood. The video is designed to inspire interest in Kōbichō, encouraging viewers to visit or consider it as a second hometown. The contest seeks videos that showcase the charm of Kōbichō, including its lifestyle, activities, and natural beauty. Open to all, the contest ran from July 1 to September 30, 2021, with video submissions ranging from 30 to 90 seconds in various formats. Awards included a Grand Prize of 300,000 yen, an Excellence Award of 100,000 yen, and three Special Awards of 30,000 yen each.' where id = 'LuUi_5-xWLBj1Ji5RzhRx';
update content_bodies set title = '香美町動画コンテスト 特別賞「Dynamic Kami Town」', description = '香美町動画コンテストは、香美町の暮らしや営み、自然の豊かさを伝える動画を募集し、町の魅力を発掘・向上させることを目的としたコンテストです。応募資格は不問で、個人やグループ、プロ・アマ問わず参加可能で、応募期間は2021年7月1日から9月30日まででした。動画は30秒から90秒以内で、特定のファイル形式と解像度が求められました。最優秀賞には30万円、優秀賞には10万円、特別賞には各3万円が授与されます。特別賞を受賞した「Dynamic Kami Town」は、養父市の米田一之氏によって制作され、空撮の魅力を伝えたいという思いが込められています。' where id = 'qYfOHI17JTzFWgITh7GN3';
update content_bodies set title = 'Dynamic Kami Town - Special Award at the Kami Town Video Contest', description = 'The Kami Town Video Contest aims to showcase the charm of Kami Town, including its lifestyle, activities, and natural beauty, through submitted videos. The contest is open to everyone, regardless of professional status or location, allowing individuals and groups to submit multiple entries, though only one can win an award. The contest ran from July 1 to September 30, 2021, inviting videos between 30 to 90 seconds in length, in specific file formats and resolutions. Awards include a Grand Prize of 300,000 yen for the best entry, a 100,000 yen prize for the excellent entry, and three Special Awards of 30,000 yen each. The special award-winning video, titled ''Dynamic Kami Town,'' was created by Kazuyuki Yoneda from Yabu City, who expressed a desire to convey the allure of aerial photography.' where id = 'KKkvQbye4jCBJzhfZbEAK';
update content_bodies set title = 'Kami360° 吉滝周辺', description = 'ドローンによる空撮VR映像は、まるで神の視点からの体験を提供します。機体が映らない特殊な撮影技術により、360度のパノラマ映像が実現されています。ぜひ、自宅で香美町の空を体験してみてください。高画質での視聴とVRゴーグルの使用を推奨します。' where id = '3vsxgus8EhvI2GQr5oSPA';
update content_bodies set title = 'Kami360° Around Yoshitaki', description = 'Experience breathtaking drone-captured VR footage that offers a divine perspective of Kami (God?). This unique filming technique allows for a seamless 360-degree panorama without any visible equipment. Enjoy the skies of Kamimachi from the comfort of your home. For the best experience, high resolution and VR goggles are recommended.' where id = 'kbgPK2MoSnBu3TxBSMmJy';
update content_bodies set title = 'Kami360°「柤大池」', description = 'Kami360°では、ドローンによる空撮VRを通じて、柤大池の美しい景色を神の視点で体験できます。特殊な撮影技術により、機体が映らない状態で360度のパノラマ映像を実現しています。ぜひ、自宅で香美町の空を楽しんでください。高画質での視聴とVRゴーグルの使用を推奨します。' where id = 'aUi0xg_Hl3TU7Neke648V';
update content_bodies set title = 'Kami360° ''Kama Oike''', description = 'Experience the breathtaking views of Kama Oike from a drone''s perspective with Kami360°. This unique filming technique allows for a seamless 360-degree panorama without the drone being visible. Enjoy the beauty of Kamimachi''s skies from the comfort of your home. For the best experience, high resolution and VR goggles are recommended.' where id = '3msU135IDYFzSaUP0prM-';
update content_bodies set title = 'Kami360°「木の殿堂」', description = 'ドローンによる空撮VRで、まるで神の視点から香美町の美しい風景を体験できます。特殊な撮影技術により、機体が映らない360度のパノラマ映像を実現しました。自宅で香美町の空を楽しんでみてください。高画質での視聴を推奨し、VRゴーグルを使用するとより良い体験ができます。' where id = 'gfYc-6kt27XhjS31GQ_wy';
update content_bodies set title = 'Kami360° ''Hall of Trees''', description = 'Experience the breathtaking views of Kami (God?) from a drone''s perspective with our VR aerial footage. Our unique filming technique allows for a seamless 360-degree panorama without the drone being visible. Enjoy the skies of Kamimachi from the comfort of your home. High quality and VR goggles are recommended for the best experience.' where id = 'X6uxXhrLIKp-xQBdVho6q';
update content_bodies set title = 'Kami360° 久須部渓谷', description = 'ドローンによる空撮VRで、まるで神の視点からの映像を体験できます。機体が映らない特殊な撮影技術を用いて、360度のパノラマ映像を実現しました。ぜひ、おうちで香美町の空を楽しんでください。高画質での視聴とVRゴーグルの使用を推奨します。' where id = '07hZx_tWgi2Ve8ZJlAuV-';
update content_bodies set title = 'Kami360° Kusube Valley', description = 'Experience the breathtaking views of Kami (God?) from a drone''s perspective with our VR aerial footage. Utilizing a special filming technique that eliminates the drone from the frame, we provide a stunning 360-degree panorama. Enjoy the skies of Kami Town from the comfort of your home. For the best experience, high resolution and VR goggles are recommended.' where id = 'P3NhiKMj6RvVxWm3Aoyx2';
update content_bodies set title = '五感を満たす旅　香美町', description = '「五感を満たす旅　香美町」をテーマにした観光PR動画を制作しました。香美町の魅力を、眺め、響き、香り、味、癒しの五つの要素で感じて楽しんでいただけます。この映像は、各五感を表現した15秒のCM映像として作成されています。撮影地には香住漁港、松葉ガニの選別、但馬牛の牛舎、村岡米、香住海岸、吉滝、日本海の波、ゆうなぎの丘、余部橋梁が含まれています。自然の味わい、心に響く眺め、地域を賑わす響き、美しい大地の香り、心穏やかな癒しを、提供されたリンクからご覧いただけます。' where id = 'YlfDhqzCxAAluB9ZHzuk2';
update content_bodies set title = 'A Journey to Satisfy the Five Senses: Kamitown', description = 'We created a promotional video for tourism based on the concept of ''A Journey to Satisfy the Five Senses: Kamitown.'' Enjoy the beauty of Kamitown through its elements: sight, sound, smell, taste, and healing. This video showcases each of the five senses in a 15-second commercial. The filming locations featured include Kasumi Fishing Port, Matsuba crab sorting, Tajima beef barn, Muraoka rice, Kasumi Coast, Yoshitaki, waves of the Japan Sea, Yuunagi Hill, and Ayabe Bridge. Experience the flavors of nature, the resonating views, the vibrant community, the beautiful earth''s scents, and the calming atmosphere through the provided links to the full versions and shorter clips.' where id = 'ezDKYhP1IBFyKrEVU7nd9';
update content_bodies set title = '焼き鳥の美味しさ、新しいステージへ。', description = 'この動画では、焼き鳥の美味しさが新しいステージに進化している様子を紹介しています。' where id = '_bvP1h4W6J13v6VSMfyei';
update content_bodies set title = 'The Deliciousness of Yakitori: A New Stage', description = 'This video introduces the deliciousness of yakitori and how it is reaching a new stage.' where id = 'NvGOa0md7YUJTqJYhBY80';
update content_bodies set title = '本好きの天国…♡ 天井まで本棚が広がる高山の新スポットが話題！「Eat books – 本と、味わう時間」', description = 'この動画では、高山に新しくオープンしたスポット「Eat books – 本と、味わう時間」を紹介しています。ここでは、天井まで広がる本棚が特徴で、本好きにはたまらない空間となっています。' where id = 'W-yJ7KGWm5BPSCgmnUA_O';
update content_bodies set title = 'A Paradise for Book Lovers: A New Spot in Takayama with Bookshelves Reaching the Ceiling - ''Eat books - A Time to Savor Books''', description = 'This video introduces a new spot in Takayama called ''Eat books - A Time to Savor Books''.' where id = 'mDNmO8ywdJysW9p_zUpaa';
update content_bodies set title = '冬の飛騨で育つブランドしいたけ「飛騨やまっこ」', description = 'この動画では、冬の飛騨で育てられるブランドしいたけ「飛騨やまっこ」について紹介しています。「飛騨やまっこ」は寒さに鍛えられた身の締まりと、噛むほどに広がる濃い旨味が特徴です。' where id = 'jQfawkBWWqpE1w376aU5C';
update content_bodies set title = 'Hida Yamako: A Brand Shiitake Mushroom Grown in Winter Hida', description = 'This video introduces ''Hida Yamako,'' a brand of shiitake mushrooms cultivated in the cold winter of Hida. The mushrooms are known for their firm texture, developed through exposure to cold temperatures, and their rich umami flavor that intensifies with each bite.' where id = 'm1S_DU0SVDytTuYsmxQXV';
update content_bodies set title = '五感を満たす旅　香美町', description = '「五感を満たす旅　香美町」をテーマにした観光PR動画を制作しました。香美町の魅力を、眺め、響き、香り、味、癒しの五つの要素で感じて楽しんでいただけます。この映像は「味」に焦点を当てた60秒のものです。映像に登場する撮影地は、香住漁港、松葉ガニの選別、松葉ガニ、村岡米、香住鶴、米地味噌、香住梨、但馬牛の牛舎とステーキ肉などです。その他の要素については、説明文にリンクされた追加の動画でご覧いただけます。' where id = '9IgmemA3LowZXIUvh-zTk';
update content_bodies set title = 'A Journey to Satisfy the Five Senses: Kamitown', description = 'We have created a promotional video for tourism based on the concept of ''A Journey to Satisfy the Five Senses: Kamitown.'' Enjoy the beauty of Kamitown through its elements: view, sound, scent, taste, and healing. This particular video focuses on the ''taste'' aspect and lasts 60 seconds. The filming locations featured in the video include Kasumi Fishing Port, the selection of Matsuba crabs, Matsuba crabs themselves, Muraoka rice, Kasumi Tsuru, rice miso, Kasumi pears, and Tajima beef cattle and steak. You can also explore other aspects of Kamitown through additional videos linked in the description.' where id = 'tCGe0twlFuOkKQeuvNWH7';
update content_bodies set title = '明治28年創業、栃の実せんべいの元祖として知られる前畑点心堂から特別なお菓子を紹介', description = 'この動画では、明治28年に創業し、栃の実せんべいの元祖として知られる前畑点心堂から、特別なお菓子「甘々棒（かんかんぼう）」について紹介しています。甘々棒は、飛騨高山の昔懐かしい駄菓子です。' where id = 'ziAy-wQHnl6aYQzYNs_f5';
update content_bodies set title = 'Introducing a Special Sweet from Maehata Tenshindō, the Originator of Tochi-no-Mi Senbei', description = 'This video introduces a special sweet called ''Kankanbō'' from Maehata Tenshindō, a company established in 1895 and known as the originator of Tochi-no-Mi Senbei. The Kankanbō is a nostalgic traditional candy from Hida Takayama.' where id = 'ltWgcbE0NiWMfu_noofMm';
update content_bodies set title = '秋の絶景2025in #飛騨高山 中橋ライトアップ', description = 'この動画では、2025年の秋の絶景として、飛騨高山の中橋ライトアップを紹介しています。美しい秋の風景とともに、ライトアップされた中橋の魅力を伝えています。' where id = 'i39BeBZxEJKVUSmesaHGs';
update content_bodies set title = 'Autumn Scenic View 2025 in #HidaTakayama Nakabashi Illumination', description = 'This video introduces the autumn scenic view of 2025 in #HidaTakayama, focusing on the illumination of Nakabashi.' where id = 'GSvZna--cEQxbgOZ41LlR';
update content_bodies set title = '🍁東山遊歩道の紅葉 撮影2025.11.13　#飛騨高山', description = 'この動画では、東山遊歩道の美しい紅葉を紹介しています。紅葉の季節に訪れると、色とりどりの葉が織りなす風景が楽しめます。特に、2025年11月13日に撮影された映像では、秋の訪れを感じさせる景色が広がっています。' where id = 'gqkd_Cim-f3OZQHSpsq2O';
update content_bodies set title = 'Autumn Leaves on Higashiyama Walking Path - Filmed on November 13, 2025 #HidaTakayama', description = 'This video introduces the autumn leaves along the Higashiyama walking path.' where id = 'CdWYEO1scE7F9uIbVLK_A';
update content_bodies set title = '秋色に染まる「日枝神社」', description = 'この動画では、秋色に染まる「日枝神社」について紹介しています。神社の美しい風景が秋の色合いで彩られ、訪れる人々に感動を与えています。' where id = 'nZ9VMb4vb5mN0wNo_0G7K';
update content_bodies set title = 'Hie Shrine in Autumn Colors', description = 'This video introduces Hie Shrine, showcasing its beautiful transformation into autumn colors.' where id = '8Wvu4yJyU5Ijwqop2LJIN';
update content_bodies set title = '東海北陸自動車道を通り、高山へ向かう道', description = 'この動画では、東海北陸自動車道を通って高山へ向かう道を紹介しています。トンネルを抜けると広がる美しい紅葉が特徴で、視聴者に安全な旅行を促しています。' where id = '3LPX3QFRJVyUKkfRkAsAr';
update content_bodies set title = 'Road to Takayama via Tokai-Hokuriku Expressway', description = 'This video introduces the road leading to Takayama via the Tokai-Hokuriku Expressway. It highlights the beautiful autumn foliage that unfolds after passing through the tunnel, encouraging viewers to travel safely.' where id = 'UufoLqPLrAS4xIhhq7VWB';
update content_bodies set title = '🍁山も空も染まる、秋の荘川へ', description = 'この動画では、標高約800mの高原地帯に位置する荘川町の秋の風景を紹介しています。澄んだ空気の中、山々が赤や黄に色づき始め、まるで絵画のような美しい秋の景色が広がっています。' where id = 'X3KezyRz-t1kPXz6sgF8R';
update content_bodies set title = 'Autumn in Shokawa: Mountains and Sky Painted in Colors', description = 'This video introduces the autumn scenery of Shokawa, located in the western part of Takayama City at an elevation of about 800 meters. The clear air enhances the beauty of the mountains, which begin to turn red and yellow, creating a picturesque autumn landscape.' where id = '7u0CE4eNH6SXz0eLJduoo';
update content_bodies set title = 'エメラルドの湖に映る、秋の魔法', description = 'この動画では、白川郷近くの御母衣ダムにあるエメラルドの湖に映る秋の魔法を紹介しています。山々は赤や黄に染まり、湖面に溶け込んでいます。風のない朝には、湖面が鏡のように静まり返り、素晴らしい景色が広がります。' where id = 'GaU5yC0-jnf3siOY5Ufyl';
update content_bodies set title = 'The Autumn Magic Reflected in the Emerald Lake', description = 'This video showcases the autumn magic reflected in the emerald lake near Shirakawa-go, specifically at the Gohori Dam. The mountains are adorned in vibrant shades of red and yellow, blending beautifully with the lake''s surface. On calm mornings, the stillness creates a mirror-like reflection, enhancing the breathtaking scenery.' where id = 'q9nxpmcaXx1xblCwmKti6';
update content_bodies set title = '宇津江四十八滝：秋の絶頂', description = 'この動画は「宇津江四十八滝」について紹介しています。現在、紅葉がまさにピークを迎えており、13の滝が連なる渓谷を歩くことで、秋の音と色の深まりを感じることができます。黄金色の木漏れ日や水しぶきに映る紅葉、そして登り切った先に広がる北アルプスの大パノラマが、秋の旋律を奏でています。' where id = 'AmXxq7Z2QRZU24Nq8nAPg';
update content_bodies set title = 'Uzu-e Forty-Eight Waterfalls: Autumn in Full Swing', description = 'This video introduces ''Uzu-e Forty-Eight Waterfalls,'' where the autumn foliage is at its peak. Walking through the valley with 13 cascading waterfalls, one can experience the deepening sounds and colors of autumn. The golden sunlight filtering through the leaves, the reflections of the autumn colors in the water spray, and the breathtaking panorama of the Northern Alps at the end of the trail create a stunning autumn melody.' where id = '_oknUZyaap9uIYEqz5Cp9';
update content_bodies set title = '紅葉と吊橋が織りなす“秋の幻想風景”へ！', description = 'この動画では、岐阜県高山市荘川にある七間飛吊橋と紅葉が織りなす幻想的な秋の風景について紹介しています。山々が燃えるように色づくこの季節に訪れることで、知る人ぞ知る絶景スポットを楽しむことができます。' where id = 'uZ_jqwkcABUdEijGWNvoq';
update content_bodies set title = 'Autumn Fantasy Landscape of Colorful Leaves and Suspension Bridge', description = 'This video introduces the ''autumn fantasy landscape'' created by colorful leaves and the Shichiken-tobi suspension bridge in Shokawa, Takayama City, Gifu Prefecture. This hidden gem is known for its breathtaking views of autumn foliage, where the mountains are painted in vibrant colors during the season.' where id = 'ZS7EoWji9ZpVn-w7hfEcm';
update content_bodies set title = '滝と紅葉が織りなす、秋の楽園「宇津江四十八滝」', description = 'この動画では、滝と紅葉が美しく調和した秋の楽園「宇津江四十八滝」を紹介しています。大小13の滝が連なるこのスポットは、訪れる人々に素晴らしい景観を提供し、特に紅葉の季節には多くの観光客が訪れます。' where id = 'CZoyMdVb4ZQMGqcz5hqUD';
update content_bodies set title = 'Autumn Paradise of Waterfalls and Autumn Leaves: ''Uzu-e Shijuhachi Falls''', description = 'This video introduces ''Uzu-e Shijuhachi Falls'', a popular autumn foliage spot featuring 13 waterfalls of various sizes, creating a picturesque scene of waterfalls and autumn leaves.' where id = 'NY5y7EnBP8pQzi16nff2P';
update content_bodies set title = '今が紅葉の見頃！池に映り込む合掌造りと色づく木々「飛騨の里」', description = 'この動画では、現在紅葉が見頃を迎えている「飛騨の里」について紹介しています。合掌造りの建物と色づく木々が池に映り込み、まるで秋の日本画のような美しい風景が広がっています。' where id = '_TSwCum-zJJzHYX-XbvNJ';
update content_bodies set title = 'The Best Time for Autumn Leaves! ''Hida no Sato'' with Gassho-zukuri Reflected in the Pond and Colorful Trees', description = 'This video introduces ''Hida no Sato,'' which is currently at its peak for autumn foliage.' where id = 'iSEbUGXvZOY0xrYRnivT9';
update content_bodies set title = '秋色に染まる「日枝神社」で開催中の日枝宵灯もみじ祭り', description = 'この動画では、秋色に染まる「日枝神社」で行われている日枝宵灯もみじ祭りについて紹介しています。神社は紅葉に囲まれ、幻想的な光景が広がっています。' where id = 'YTu9HnYjypnZ-encrKPq9';
update content_bodies set title = 'Hie Shrine''s Autumn Festival: Hie Night Lantern Maple Festival', description = 'This video introduces the Hie Night Lantern Maple Festival currently being held at Hie Shrine, which is beautifully adorned in autumn colors.' where id = '5v_susrIDaRN5sa97jp7X';
update content_bodies set title = '飛騨美濃せせらぎ街道！紅葉絶景ドライブへ', description = 'この動画では、飛騨美濃せせらぎ街道をドライブしながら楽しむ紅葉の絶景について紹介しています。美しい自然の中で、色とりどりの紅葉を堪能できるルートを通り、訪れる人々に感動を与える風景が広がっています。' where id = 'Qy3T4MUxk6sv2-8bdfflq';
update content_bodies set title = 'Scenic Drive on Hida-Mino Seseragi Road! Autumn Foliage', description = 'This video introduces a scenic drive along the Hida-Mino Seseragi Road, showcasing the breathtaking autumn foliage.' where id = '2MI1RscKspHzOKFBHRzLC';
update content_bodies set title = '中尾高原と鍋平園地を結ぶ北アルプス大橋', description = 'この動画では、奥飛騨温泉郷に位置する中尾高原と鍋平園地を結ぶ北アルプス大橋について紹介しています。このアーチ橋は全長150m、高さ70mで、笠ヶ岳や焼岳、錫杖岳など北アルプスの名峰を間近に望むことができ、まさに自然が描く絶景の舞台です。' where id = '16bFGaasTdVbtNtbwid0E';
update content_bodies set title = 'Kita Alps Bridge Connecting Nakao Plateau and Nabehei Park', description = 'This video introduces the Kita Alps Bridge, a 150-meter long and 70-meter high arch bridge located in the Okuhida Onsen area. The bridge offers stunning views of famous peaks in the Northern Alps, such as Kasagatake, Yake-dake, and Sujiyou-dake, making it a true ''stage of breathtaking natural scenery.''' where id = 'l8UgsgFsedi2UlYr_BMsy';
update content_bodies set title = '日本唯一の“2階建てゴンドラ”で、天空の紅葉へ！秋の奥飛騨温泉郷へ。標高2,156m、新穂高ロープウェイ。', description = 'この動画では、日本唯一の2階建てゴンドラを利用して、奥飛騨温泉郷の美しい秋の紅葉を楽しむ様子を紹介しています。' where id = 'thNWH_kL-tAC9Fu9jEGXf';
update content_bodies set title = 'Japan''s Only ''Two-Story Gondola'' to the Sky''s Autumn Foliage! To Okuhida Onsen Village in Fall. Elevation 2,156m, Shin-Hotaka Ropeway.', description = 'This video introduces the unique experience of Japan''s only two-story gondola, taking visitors to the breathtaking autumn foliage of Okuhida Onsen Village.' where id = 'VZxxccb4HyqZ55uPVZ8B2';
update content_bodies set title = '飛騨高山　飛騨トマト｜山がつくる、甘みという芸術。｜岐阜・高山市 夏秋トマトの物語', description = '岐阜県高山市で育つ飛騨トマトは、3,000m級の山々に囲まれた環境で、昼夜の寒暖差やミネラル豊富な山の水、澄んだ空気が影響し、濃厚な甘みとほどよい酸味を生み出します。7月から11月にかけて出荷される飛騨トマトは、全国一の夏秋トマト産地として年間約6,300万個が市場に出回ります。376戸の農家が伝統の技を守り、恵まれた自然環境で育てられた香り立つトマトを提供しています。昼夜の寒暖差で甘みが凝縮され、雨よけハウスで栽培され、真っ赤な完熟で収穫されるなど、こだわりの栽培方法が特徴です。昭和20年代から続く伝統産地であり、昭和40年代には全国に先駆けて雨よけハウスを導入し、日本のトマトづくりをリードしてきた誇りがあります。' where id = 'wZjdRCVr1Ah7Qe7SLyIcB';
update content_bodies set title = 'Hida Takayama Hida Tomato | The Art of Sweetness Created by the Mountains | Gifu, Takayama''s Summer and Autumn Tomato Story', description = 'Hida tomatoes are grown in Takayama, Gifu Prefecture, surrounded by 3,000-meter mountains. The significant temperature difference between day and night, mineral-rich mountain water, and clear air contribute to their rich sweetness and balanced acidity. From July to November, approximately 63 million Hida tomatoes are shipped, making it Japan''s leading summer and autumn tomato production area. With 376 farmers preserving traditional techniques and benefiting from a favorable natural environment, these ''fragrant tomatoes'' are delivered fresh. Key features include concentrated sweetness from temperature variations, cultivation in rain-protective houses, harvesting at full ripeness, and prompt shipping to urban areas. The history of Hida tomatoes dates back to the 1940s, with the introduction of rain-protective houses in the 1960s, showcasing a proud legacy in Japanese tomato cultivation.' where id = 'z_YyBE2WLHzWpmFezxjgI';
update content_bodies set title = '飛騨高山　澄んだ空気がつくる、飛騨ほうれん草の極み', description = '飛騨ほうれん草は、標高の高い飛騨の地で育まれた特別な甘さを持つほうれん草です。3月から12月まで、昼は陽ざしを浴びて栄養を蓄え、夜は冷え込むことで甘みを閉じ込めます。この気候が、飛騨ならではのやわらかさと旨みを生み出します。350の農家が守る伝統の栽培技術により、収穫後すぐに予冷し、真空冷却・冷蔵輸送が行われ、関西・中部・関東・北陸の食卓へ届けられます。おすすめの楽しみ方は、おひたし、ベーコン炒め、スープなど。出荷期間は3月から12月で、季節を越えて旬を届ける飛騨の緑です。' where id = 'V6ukKgOn3_SS-yY86jDRm';
update content_bodies set title = 'Hida Takayama: The Ultimate Spinach from Clear Air', description = 'Hida spinach, grown in the high-altitude region of Hida, possesses a unique sweetness developed through significant temperature differences between day and night. From March to December, this spinach benefits from the cool mountain air, absorbing nutrients during the day and locking in sweetness at night. The local climate contributes to its tenderness and flavor. With 350 farmers practicing traditional cultivation techniques, the spinach is quickly pre-cooled after harvest and transported under strict refrigeration to maintain its ''mountain temperature.'' Recommended ways to enjoy Hida spinach include as a side dish, stir-fried with bacon, or in soups. The shipping period is from March to December, ensuring that this seasonal delight reaches tables across Kansai, Chubu, Kanto, and Hokuriku regions.' where id = 'tdE_WTB_zorS1A39tdLCn';
update content_bodies set title = '時を超えて受け継がれる、祈りと誇りの二日間', description = 'この動画では、毎年10月9日と10日に櫻山八幡宮で行われる飛騨高山を代表する祭礼「秋の高山祭」について紹介しています。この祭りは、地域の文化や伝統を大切にし、参加者や観光客にとって特別な意味を持つイベントです。' where id = 'gyA25UvH-x3qvUzHgNZpV';
update content_bodies set title = 'A Two-Day Festival of Prayer and Pride Passed Down Through Time', description = 'This video introduces the ''Autumn Takayama Festival,'' a representative festival of Hida Takayama held annually on October 9th and 10th at Sakurayama Hachiman Shrine.' where id = 'HinXdna0DOjo7IaE9ff_K';
update content_bodies set title = '秋の高山祭 時を越えて受け継がれる「御神幸(祭行列)」まるで江戸時代にタイムスリップしたかのよう', description = 'この動画は秋の高山祭について紹介しています。' where id = 'Urx6Qsg3dzRdxoZ7dJG0J';
update content_bodies set title = 'Autumn Takayama Festival: A Timeless Tradition of ''Mikoshi Procession'' that Transports You Back to the Edo Period', description = 'This video introduces the Autumn Takayama Festival.' where id = 'gAh_4LnbSHHG5xAn3CBsD';
update content_bodies set title = '秋の高山祭「獅子舞」', description = 'この動画では、秋の高山祭で行われる「獅子舞」について紹介しています。高山祭は日本の伝統的な祭りで、地域の文化や歴史を反映したイベントです。獅子舞はその中でも特に重要なパフォーマンスであり、地域の人々にとって特別な意味を持っています。獅子舞は、悪霊を追い払うとともに、豊作や繁栄を祈願するために行われます。動画では、獅子舞の演技やその背景、祭りの雰囲気を感じることができます。' where id = 'c011tR5HK125DHNor8HD4';
update content_bodies set title = 'Autumn Takayama Festival ''Lion Dance''', description = 'This video introduces the ''Lion Dance'' at the Autumn Takayama Festival.' where id = 'E31x6_9dAgKKizDnwOgfF';
update content_bodies set title = '屋台の曳廻しは秋の高山祭だけの行事', description = 'この動画では、屋台の曳廻しが秋の高山祭だけで行われることについて紹介しています。祭りでは、4台の屋台が町を巡る様子が楽しめます。' where id = '1RsYU7rcXJjBpSoPH7p1L';
update content_bodies set title = 'The Yatai Procession is Only Held During the Autumn Takayama Festival', description = 'This video introduces the fact that the Yatai procession is an event exclusive to the Autumn Takayama Festival. During this festival, four yatai (float) vehicles can be seen parading through the town.' where id = 'apybIZkXiDhwlxBSf47c5';
update content_bodies set title = 'カン、カコカン。秋の空に響くその音が、高山のまちを包む。闘鶏楽。', description = 'この動画は、カン、カコカンという音が秋の空に響き、高山のまちを包む闘鶏楽について紹介しています。闘鶏楽では、一文字笠に龍と鳳凰が染め抜かれ、鉦と締太鼓の音に合わせて行進する姿が見られ、まるで時を超えた祈りのリズムを感じさせます。' where id = 'TxWKVHfX5Cnqn4cf2rAWv';
update content_bodies set title = 'Kang, Kakokan. The sound resonating in the autumn sky envelops the town of Takayama. Fighting Rooster Music.', description = 'This video introduces the Fighting Rooster Music, known as Kang, Kakokan, which resonates in the autumn sky and envelops the town of Takayama. The performance features a procession accompanied by the sounds of bells and taiko drums, creating a rhythm of prayer that transcends time.' where id = 'Gf7fwffMCe3nls_BDK90s';
update content_bodies set title = '3月から12月まで、山あいの地・飛騨から全国へ。出荷される“緑の宝石”、それが飛騨ほうれんそうです。', description = 'この動画では、3月から12月まで、山あいの地・飛騨から全国に出荷される“緑の宝石”である飛騨ほうれんそうについて紹介しています。' where id = 'fxVdE_mMeDD0b-DdxEwIE';
update content_bodies set title = 'From March to December, the ''Green Jewel'' of Hida, Hida Spinach, is Shipped Nationwide.', description = 'This video introduces Hida spinach, known as the ''green jewel,'' which is shipped from the mountainous region of Hida to the entire country from March to December.' where id = 'xWei_3AmXR9udhHzJABhW';
update content_bodies set title = '海女小屋はちまんかまど「贅沢なセレブ気分アワビコース」(鳥羽市)　｜観光三重｜三重県の観光・旅行情報', description = '日本一の海女が集まる鳥羽市相差町に位置する「海女小屋はちまんかまど」では、贅沢な海鮮コースを提供しています。このコースには、伊勢えび1尾、あわび1個、サザエ2個、ヒオウギ貝2個、大アサリ1個、ひじき煮、伊勢えびあおさ汁、アジの干物が含まれています。海女小屋で焼きたての新鮮な海の幸を楽しむことができます。' where id = 'L_cBFY2DYusOu9gFIO2HI';
update content_bodies set title = 'Amagoya Hachiman Kamado: Luxurious Abalone Course (Toba City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Located in Osozu Town, Toba City, known for having the most ama divers in Japan, Amagoya Hachiman Kamado offers a luxurious seafood course featuring one Ise lobster, one abalone, two turban shells, two scallops, one large clam, hijiki seaweed, Ise lobster and aosa soup, and dried horse mackerel. Enjoy the fresh, grilled delicacies right from the ama hut.' where id = 'ByiWLVr9eIt1uOUR9sLcJ';
update content_bodies set title = 'はじめての3,000m登山にぴったり！岐阜と長野の県境にそびえる日本百名山・乗鞍岳・飛騨高山', description = 'この動画では、岐阜と長野の県境に位置する日本百名山の乗鞍岳と飛騨高山を紹介しています。これらの山は、初めて3,000mの登山に挑戦する人に最適な場所です。' where id = 'jLDaJ_IpgAfLGzRQajfJK';
update content_bodies set title = 'Perfect for Your First 3,000m Climb! Mount Norikura and Hida Takayama on the Border of Gifu and Nagano', description = 'This video introduces Mount Norikura and Hida Takayama, both located on the border of Gifu and Nagano, which are perfect for those attempting their first 3,000m climb. These mountains are part of Japan''s 100 Famous Mountains.' where id = '_ERc6Qu3dMq39Ypql73DZ';
update content_bodies set title = '飛騨高山　雲上の世界へ！乗鞍岳で出会う感動のパノラマとお花畑', description = '乗鞍岳は岐阜県と長野県の県境に位置し、標高3,026mの剣ヶ峰が最高峰です。畳平（2,702m）までバスでアクセスでき、3,000m級の山として手軽に挑戦できる人気のスポットです。夏には高山植物が咲くお花畑を散策でき、火口湖や溶岩地形などの火山特有の景色も楽しめます。頂上からは北アルプスや白山、八ヶ岳などの壮大なパノラマが広がります。初心者向けの登山コースも充実しており、剣ヶ峰までは片道約1時間30分、魔王岳は片道15分で山頂に到達できます。子どもから大人まで楽しめる乗鞍岳は、岳人入門にぴったりの名山です。この動画では登山ルートやお花畑、山頂からの絶景を紹介しています。登山の際は体調や装備に注意し、高山病にも気をつけてください。' where id = '2sj7ZJ_5sW6pKbZI0_1SL';
update content_bodies set title = 'Welcome to Mount Norikura, a World Above the Clouds!', description = 'Mount Norikura, part of the Chubu Sangaku National Park, straddles the border of Gifu and Nagano Prefectures, with its highest peak, Kengamine, reaching 3,026 meters. Accessible by bus to Tatamidaira at 2,702 meters, it is a popular choice for those looking to easily tackle a 3,000-meter mountain. In summer, visitors can stroll through vibrant alpine flower fields, witness volcanic landscapes like crater lakes and lava formations, and enjoy breathtaking panoramic views of the Northern Alps, Hakusan, and Yatsugatake from the summit. The mountain offers beginner-friendly hiking routes, with a one-way trek to Kengamine taking about 1.5 hours and a quick 15-minute hike to Maou-dake. Norikura is an ideal mountain for everyone, from children to adults, making it a perfect introduction to mountaineering. The video showcases the hiking routes, flower-filled meadows, and stunning views from the peak, serving as a great reference for your next adventure.' where id = 'LPGsWd-wiFKaMZHAKZhaD';
update content_bodies set title = '飛騨高山 絶景ドライブ「飛騨・美濃せせらぎ街道」', description = '「飛騨・美濃せせらぎ街道」は、郡上市八幡町から高山市清見町を結ぶ約90分のドライブコースで、吉田川や馬瀬川、川上川などの清流に寄り添いながら、約65kmの大自然を楽しむことができます。出発地の郡上八幡では城下町の風情を感じ、標高が上がるにつれて明宝高原や白樺、カラマツの森が広がり、まるで絵巻物のように景色が変わります。信号や急カーブが少なく運転しやすく、窓を開ければ川のせせらぎと高原の風が心地よく感じられます。春の新緑、夏の涼風、秋の紅葉、冬の静寂と、四季折々の異なる表情を見せる絶景街道です。次の休日に、少し遠出してみませんか？' where id = 'elQXoTVJcFI1EBbh_nGG8';
update content_bodies set title = 'Scenic Drive in Hida Takayama: Hida-Mino Seseragi Road', description = 'The Hida-Mino Seseragi Road is a 90-minute drive connecting Gujo Hachiman to Takayama Kiyomi, offering a stunning 65 km route alongside clear rivers like Yoshida, Mase, and Kawakami. Starting in Gujo Hachiman, known for its castle town atmosphere, the drive ascends through lush landscapes, including Meihō Plateau and forests of white birch and larch, transforming like a picture scroll. With few traffic signals and sharp turns, it’s easy to drive, allowing you to enjoy the soothing sounds of the rivers and the refreshing breeze of the highlands. Each season presents a different view, from spring greenery to autumn foliage and winter tranquility, making it a perfect destination for photography enthusiasts. Consider taking a trip to this breathtaking scenic road on your next holiday.' where id = '597-RR5RiTKcC2LoGtxDw';
update content_bodies set title = '櫻山八幡宮の桜山風鈴まつり', description = 'この動画は櫻山八幡宮で開催される「桜山風鈴まつり」について紹介しています。この祭りでは、約2,000個の風鈴が風に揺れ、澄んだ音が絵馬殿に響き渡ります。ひとつひとつの風鈴には願い札が結ばれており、涼風に乗って境内を巡ります。' where id = 'B6ctJ-9USTqhfbVJjXuKU';
update content_bodies set title = 'Sakurayama Furin Festival at Sakurayama Hachiman Shrine', description = 'This video introduces the Sakurayama Furin Festival held at Sakurayama Hachiman Shrine. The festival features around 2,000 wind chimes that sway in the breeze, creating a clear and soothing sound throughout the shrine''s ema hall. Each wind chime is tied with a wish plaque, which floats on the refreshing wind, spreading hopes and dreams across the shrine grounds.' where id = 'ro4RJdM91He1yhzWfU_OM';
update content_bodies set title = '飛騨高山の夜さんぽ', description = 'この動画では、飛騨高山の夜の散策を紹介しています。昼間とは異なる世界が広がる中で、期間限定のライトアップが施された「赤い中橋」が登場します。鮮やかな赤色が夜の闇に映え、まるで絵本の一場面のような幻想的な光景が広がります。' where id = '7RuO06sS5RqSSph_Ld9OS';
update content_bodies set title = 'Night Stroll in Hida Takayama', description = 'This video introduces a night stroll in Hida Takayama, showcasing the limited-time illumination of the ''Akai Nakabashi'' bridge. The vibrant red color stands out against the night, creating a fantastical scene reminiscent of a storybook.' where id = 'sNvixlLHF_4xSTf5u5nKc';
update content_bodies set title = '久々野町にある「ひだ舟山リゾート アルコピア」のアルコピアひまわり園が期間限定オープン！', description = 'この動画では、久々野町に位置する「ひだ舟山リゾート アルコピア」のアルコピアひまわり園について紹介しています。1ヘクタールのゲレンデを覆い尽くす20万本のひまわりが咲き誇り、訪れる人々に息をのむような絶景を提供しています。' where id = 'AEMlHAQ20ijY_fdNbtqWi';
update content_bodies set title = 'Alcopia Sunflower Garden Opens Again at Hida Funayama Resort', description = 'This video introduces the Alcopia Sunflower Garden located at Hida Funayama Resort in Kuki Town. The garden features a breathtaking view of 200,000 sunflowers covering a 1-hectare slope, creating a stunning landscape that visitors can enjoy.' where id = 'FTUF4_p4XsyaJxX6vO0Xu';
update content_bodies set title = '手筒花火打上げ', description = 'この動画では、8月9日に行われる飛騨高山の夏のイベント「手筒花火打上げ」について紹介しています。手筒花火は、伝統的な花火の一種で、手に持って打ち上げるスタイルが特徴です。このイベントは、地域の夏の風物詩として多くの人々に親しまれており、観客は美しい花火の光と音を楽しむことができます。' where id = 'jiO4nFELsdJZ3Qnnd1G9Y';
update content_bodies set title = 'Handheld Fireworks Display in Hida Takayama', description = 'This video introduces the summer event ''Handheld Fireworks Display'' that takes place on August 9 in Hida Takayama.' where id = 'QYY39dxMQLD8LB69CRaCi';
update content_bodies set title = '「えっ、七夕って8月なの⁉️」', description = 'この動画では、飛騨高山での旧暦に基づく七夕の祝祭について紹介しています。毎年8月5日から7日まで行われるこのイベントでは、観光地である「古い町並み」が幻想的な風景に包まれます。' where id = '-1uN_vpgSbJzdsyjOCn7v';
update content_bodies set title = 'Did you know Tanabata is in August?!', description = 'This video introduces the traditional celebration of Tanabata in Hida Takayama, which follows the old lunar calendar. The event takes place annually from August 5th to 7th, transforming the historic area of ''Old Town'' into a magical landscape.' where id = 'WiAHayVF95GyxR3aM5YkO';
update content_bodies set title = '江戸時代から続く飛騨地方の焼物「小糸焼」', description = 'この動画では、江戸時代から続く飛騨地方の焼物「小糸焼」について紹介しています。普段使いの食器や茶道具、モダンなクラフトなど、手作りのうつわが作られ続けている様子が描かれています。' where id = '-xmKstyKYwdup3-GV7-Iq';
update content_bodies set title = 'Koito-yaki: Traditional Pottery from the Hida Region Since the Edo Period', description = 'This video introduces Koito-yaki, a type of pottery from the Hida region that has been produced since the Edo period. It showcases a variety of handmade tableware, tea utensils, and modern crafts, emphasizing the continued tradition of creating functional and artistic pieces.' where id = 'eTShrUgLc8eaLHQqkC_MR';
update content_bodies set title = '日本の滝百選に選ばれた壮大な滝「平湯大滝」', description = 'この動画は、日本の滝百選に選ばれた壮大な滝「平湯大滝」について紹介しています。落差64メートルの迫力満点の滝で、激しく流れ落ちる水しぶきやせせらぎの音が楽しめます。また、漂うマイナスイオンに癒されるスポットでもあります。' where id = 'sHFo2PNc7AZd8bDZtLKmr';
update content_bodies set title = 'The Magnificent Hirayu Falls, Selected as One of Japan''s Top 100 Waterfalls', description = 'This video introduces Hirayu Falls, a magnificent waterfall selected as one of Japan''s Top 100 Waterfalls. With a height of 64 meters, it offers a powerful display of cascading water. Visitors can enjoy the refreshing sound of the rushing water and the soothing mist, which is rich in negative ions, making it a perfect spot for relaxation.' where id = 'M6jabxjwUW71jPflca4FV';
update content_bodies set title = '雲上の絶景、新たな高みへ！', description = 'この動画では、2025年7月19日に新穂高ロープウェイの西穂高口駅にある展望台が「AlpScape（アルプスケープ）」としてリニューアルオープンすることについて紹介しています。新たな展望台では、雲上の絶景を楽しむことができ、訪れる人々に新しい体験を提供します。' where id = 'IoYOOHHOL4zo3_L2ZTu-H';
update content_bodies set title = 'Breathtaking Views Above the Clouds: A New Height!', description = 'This video introduces the reopening of the observation deck at the Nishihotaka Station of the Shin-Hotaka Ropeway as ''AlpScape'' on July 19, 2025.' where id = 'ys-mudxPsFguz-etlqXYZ';
update content_bodies set title = '美濃から飛騨へ。清らかな流れと四季の彩りに包まれながら走る、全長約65kmのドライブルート「飛騨・美濃せせらぎ街道」', description = 'この動画では、美濃から飛騨へと続く全長約65kmのドライブルート「飛騨・美濃せせらぎ街道」を紹介しています。この道は、清らかな流れと四季折々の美しい風景に囲まれており、ドライブを楽しむには最適な場所です。' where id = 'om1MwysIkvJRG1_rnraue';
update content_bodies set title = 'From Mino to Hida: The 65km Drive Route ''Hida-Mino Seseragi Kaido'' Surrounded by Clear Streams and Seasonal Colors', description = 'This video introduces the ''Hida-Mino Seseragi Kaido,'' a scenic drive route approximately 65 kilometers long that runs from Mino to Hida.' where id = 'e5aqr1hdCnVaRRX7EOmOB';
update content_bodies set title = '飛騨の家具®フェスティバル開催中！今年のテーマは「伝統を生かす ～匠の遺伝子～」。', description = '飛騨の家具®フェスティバルは、2025年7月2日から6日まで、飛騨・世界生活文化センターをメイン会場に開催されています。今年のテーマは「伝統を生かす ～匠の遺伝子～」で、飛騨地域の職人の技術や文化を紹介し、伝統的な工芸の重要性を伝えることを目的としています。この動画では、フェスティバルの内容とその意義について紹介しています。' where id = 'RpQPmN8PFpricxPAiOZSo';
update content_bodies set title = 'Hida Furniture® Festival is Ongoing! This Year''s Theme is ''Utilizing Tradition - The Craftsman''s DNA''.', description = 'The Hida Furniture® Festival is being held from July 2 to July 6, 2025, at the Hida World Living Culture Center. The festival focuses on the theme of preserving and utilizing traditional craftsmanship, showcasing the unique skills and heritage of artisans in the Hida region. This video introduces the festival and its significance in promoting local culture and craftsmanship.' where id = 'pecdualH9rqm_ACE73nxQ';
update content_bodies set title = '明治28年創業、サクッとした食感とほんのり甘く素朴な味わいがクセになる栃の実せんべいの元祖「前畑点心堂」。', description = 'この動画は明治28年に創業した前畑点心堂について紹介しています。看板商品は、丁寧にアク抜きした飛騨産の栃の実を練り込んだ「栃の実せんべい」です。' where id = 'NtyhDJukaNTUQ1FSwBtWI';
update content_bodies set title = 'Founded in 1895, the original ''Tochinomi Senbei'' by Maehata Tenshindō features a crispy texture and a subtly sweet, rustic flavor.', description = 'This video introduces Maehata Tenshindō, established in 1895. Their signature product is ''Tochinomi Senbei,'' made with carefully processed tochi nuts from Hida, which are kneaded into the rice crackers.' where id = 'zftt-iiQN3CPuAATZhZd-';
update content_bodies set title = '飛騨高山で“呑んでめぐって”酒蔵巡礼！「飛騨高山酒蔵のん兵衛まつり」開催中', description = 'この動画では、飛騨高山で開催されている「飛騨高山酒蔵のん兵衛まつり」について紹介しています。この祭りは、地元の酒蔵を巡りながら、様々な日本酒を楽しむことができるイベントです。参加者は、各酒蔵で提供される日本酒を試飲しながら、地域の文化や伝統を体験することができます。' where id = 'khmi2i6gV6CmMahmYdejc';
update content_bodies set title = 'Hida Takayama''s ''Sake Brewery Pilgrimage'' - ''Hida Takayama Sake Brewery Nonbei Festival'' Now Ongoing', description = 'This video introduces the ''Hida Takayama Sake Brewery Nonbei Festival'' currently being held in Hida Takayama.' where id = '_gWYDyXozRiIUKcZ5yrxQ';
update content_bodies set title = '岐阜県高山市の「花の森 四十八滝山野草花園」でのササユリの開花', description = 'この動画では、岐阜県高山市にある「花の森 四十八滝山野草花園」で開花中の約2万本のササユリを紹介しています。淡いピンク色の花びらが揺れ、園内には上品でやさしい香りが広がっています。' where id = 'HaeZ7t3iN95__vPSzDodj';
update content_bodies set title = 'Sasa Lily Blooming at Hananomori Shijuhattaki Wildflower Garden in Takayama, Gifu', description = 'This video introduces approximately 20,000 Sasa lilies currently blooming at the Hananomori Shijuhattaki Wildflower Garden in Takayama, Gifu Prefecture. The delicate pink petals sway gently, filling the garden with a refined and gentle fragrance.' where id = '-WAQkWxr6kHJLwb0PsV5d';
update content_bodies set title = '飛騨高山の人気観光スポット「赤い中橋」', description = 'この動画では、飛騨高山の人気観光スポットの一つである「赤い中橋」について紹介しています。この橋は市内中心部を流れる宮川にかかる真っ赤な橋で、新緑の季節には青い空、川辺の緑、そして鮮やかな赤い橋の美しいコントラストを楽しむことができます。' where id = 'BW5Z9_5wf6TZOLijceCQ0';
update content_bodies set title = 'The Popular Tourist Spot ''Red Nakabashi'' in Hida Takayama', description = 'This video introduces ''Red Nakabashi,'' one of the popular tourist spots in Hida Takayama. The bridge, painted bright red, spans the Miyagawa River in the city center. During the fresh green season, visitors can enjoy the beautiful contrast of the blue sky, the greenery by the riverside, and the vibrant red of the bridge.' where id = '5z1ErMIV9cR6OFpTf2IwW';
update content_bodies set title = '飛騨高山の伝統銘菓', description = '岐阜県高山市には、自然豊かな風土と共に、地域に根ざした伝統的な銘菓が数多く存在します。これらのお菓子は、伝統的な技術を守りながら、素材の風味を活かして作られており、素朴で懐かしい味わいが特徴です。地元の人々に長年愛され、観光客のお土産としても人気の高山の銘菓は、心を優しく包み込む存在です。この記事では、高山ならではの伝統的な銘菓を紹介します。' where id = 'bg2NVnVt7PWA5LITcA_dm';
update content_bodies set title = 'Traditional Sweets of Hida Takayama', description = 'In Takayama, Gifu Prefecture, you can encounter many traditional sweets that have been cherished for generations. These confections are made with great care, preserving traditional techniques while highlighting the natural flavors of the ingredients. They are simple yet nostalgic, providing a comforting experience for those who enjoy them. Loved by locals and appreciated by tourists as perfect souvenirs, these traditional sweets of Takayama are a must-try. This article introduces some of the unique confections that represent the essence of Takayama.' where id = '5pobJApz4ccX9rfXSIi5R';
update content_bodies set title = '第40回 白川郷田植え祭りが開催されました', description = 'この動画は、記念すべき40回目となる「第40回 白川郷田植え祭り」について紹介しています。今回は、飛騨高山・一之宮発祥の伝統工芸「宮笠」を早乙女たちが着用し、匠の技と美しい里山風景が調和した絶景が楽しめます。' where id = 'NzlEzBN1Z7vHBZ3nE77aS';
update content_bodies set title = 'The 40th Shirakawa-go Rice Planting Festival Held', description = 'This video introduces the 40th Shirakawa-go Rice Planting Festival. This milestone event features young women dressed in traditional crafts known as ''Miyagasa,'' originating from Hida Takayama and Ichinomiya. The festival showcases a beautiful harmony between the artisans'' skills and the picturesque Satoyama landscape.' where id = 'iNC9YocqU8K7nCWgdL9sA';
update content_bodies set title = '丹生川町に誕生したいちご狩りスポット「ニシウエ青果園」', description = 'この動画では、丹生川町に新たにオープンしたいちご狩りスポット「ニシウエ青果園」について紹介しています。この園の最大の魅力は、靴を脱いでくつろげる清潔で快適なハウス空間です。床に座ったり寝そべったりしながら、いちご狩りをより自由にリラックスして楽しむことができる新しいスタイルが特徴です。' where id = 'AXehcGgEXDHDqF9_TsPjq';
update content_bodies set title = 'New Strawberry Picking Spot ''Nishiue Seikaen'' in Niyugawa Town', description = 'This video introduces ''Nishiue Seikaen'', a new strawberry picking spot in Niyugawa Town. The main attraction is its clean and comfortable house space where visitors can relax without shoes. Guests can sit or lie down on the floor, allowing for a more free and enjoyable strawberry picking experience.' where id = 'cOR00zKsHDhauSHvq8JIc';
update content_bodies set title = '池田高校全国観光甲子園２０２２グランプリ受賞修学旅行コース', description = '徳島県立池田高等学校の観光班が全国観光甲子園２０２２でグランプリを受賞した修学旅行コースが、そらの郷とタイアップして商品化されました。このコースは、地域の魅力を活かした内容で、観光振興に寄与することを目的としています。池田高校の生徒たちが考案したこのプランは、地域の文化や自然を体験できる機会を提供し、訪れる人々に新たな発見をもたらすことを目指しています。' where id = 'zvV54BXqrYWm4jTrvNmfC';
update content_bodies set title = 'Ikeda High School Wins Grand Prix at National Tourism Koshien 2022', description = 'The tourism team from Tokushima Prefectural Ikeda High School has collaborated with Sora no Sato to commercialize their award-winning school trip course, which won the Grand Prix at the National Tourism Koshien 2022.' where id = 'tzhAbLMH4mQXKksk9062X';
update content_bodies set title = '飛騨高山の老舗「のがわ」', description = 'この動画では、飛騨高山の人気観光スポット中橋近くに位置する創業80余年の老舗「のがわ」を紹介しています。手打ちうどんの味を守り続けるこのお店は、観光客だけでなく地元の人々にも愛されており、名店として知られています。' where id = 'phAiBFUlIqfPJA7qdeI20';
update content_bodies set title = 'Nagawa: A Long-Established Udon Shop in Hida Takayama', description = 'This video introduces ''Nagawa,'' a long-established udon shop with over 80 years of history, located near the popular tourist spot Nakabashi in Hida Takayama. Known for its handmade udon, this restaurant is beloved not only by tourists but also by locals, making it a renowned establishment in the area.' where id = 'B7PUtHaf3wdR5u9OhStrK';
update content_bodies set title = '飛騨高山の伝統工芸品「小屋名しょうけ」', description = '岐阜県高山市久々野町・小屋名地区に伝わる「小屋名しょうけ」は、台所の必需品として長年親しまれてきた竹細工です。野菜の水切りや米あげなど、日常生活に自然に溶け込んでおり、生活の知恵と手しごとの温もりを伝えています。細く割いたスズタケを編み込んだ美しい編み目と、機能性と造形美を兼ね備えた楕円形の形状が特徴です。「片口しょうけ」と「丸じょうけ」の2種類があり、用途や好みに応じて使い分けられています。地元のスズタケ、マタタビ、ツタウルシを材料に、専用の道具を使って熟練の技で製作されます。小屋名しょうけ保存会がこの技を守り、未来へと手渡す活動を行っており、重要なのは「形」ではなく「あり方」であるとされています。手のぬくもりが込められた一つひとつの作品が、今も静かに語りかけています。' where id = 'klM3lydj63zY4fvxK1Z_w';
update content_bodies set title = 'Traditional Craft of Hida Takayama: Koyana Shoke', description = 'Koyana Shoke, a traditional bamboo craft from Koyana district in Hida Takayama, Gifu Prefecture, has been cherished as an essential kitchen item for many years. This bamboo basket is seamlessly integrated into daily life, serving purposes like draining vegetables and washing rice, embodying the wisdom of living and the warmth of craftsmanship. The basket features beautifully balanced weaving created by interlacing thin strips of Suzutake bamboo, resulting in an oval shape that combines functionality with aesthetic appeal. There are two types: ''Katakuchi Shoke'' and ''Maru Jōke,'' used according to preference and purpose. Local materials such as Suzutake, Matatabi, and Tsuta Urushi are utilized, and specialized tools like ''Tsumakiri'' and ''Takewari'' are employed in the intricate crafting process. The Koyana Shoke Preservation Society is dedicated to passing on this skill to future generations, emphasizing the importance of the ''way of being'' rather than just the ''form.'' Each piece carries the warmth of human hands, quietly telling its story.' where id = 'XQC-MCKA6kwY3EEM6YdHl';
update content_bodies set title = '飛騨高山の伝統工芸品「宮笠」', description = '「宮笠」は約330年前に一之宮町に伝えられた伝統工芸品で、イチイとヒノキの木を薄く削り、細長く切り出したものを水に浸して編み込んで作られます。材料の準備や幾何学模様の編み目はすべて匠の技によるものです。宮村に住む問坂義一さんと和彦さんは、親子でこの伝統技術を守り続けています。宮笠は乾燥時は軽く通気性に優れ、雨や雪で水分を含むと木が膨張し、隙間が詰まって雨水の侵入を防ぎます。材料や寸法、形、編み方によって様々な種類があり、特にセミ笠はその技術の集大成です。この伝統は祖父から父、父から息子へと受け継がれ、飛騨一之宮の伝統工芸の灯りは今後も赤く燃え続けるでしょう。' where id = 'jSmvQTm85CFEkUFN3oyaG';
update content_bodies set title = 'Traditional Craft of Hida Takayama: Miyagasa', description = 'Miyagasa, a traditional craft introduced to Ichinomiya Town about 330 years ago, is made by soaking thinly shaved and elongated pieces of Yew and Hinoki wood in water and weaving them together. The preparation of materials and the geometric patterns of the weaving are all the result of skilled craftsmanship. Yoshikazu and Kazuhiko Monzaka, a father and son living in Miyamura, continue to preserve this traditional technique. When dry, Miyagasa is lightweight and highly breathable, but when it absorbs moisture from rain or snow, the woven wood expands, filling gaps and preventing water intrusion. There are various types of Miyagasa, differing in materials, dimensions, shapes, and weaving methods, with the semi-gasa being the culmination of these techniques. This tradition has been passed down from grandfather to father and from father to sons, ensuring that the flame of traditional crafts in Hida Ichinomiya continues to burn brightly.' where id = 'rvdnqtSgFkoSJBRSZV5w_';
update content_bodies set title = '飛騨クラフト：飛騨の小さなリキュール専門所', description = 'この動画では、飛騨の小さなリキュール専門所「飛騨クラフト」について紹介しています。ここでは、旬の国産果実と飛騨の湧き水を使用し、一本ずつ丁寧にお酒を仕込んでいます。' where id = 'EwK2eHMbnUnt21zDgra6I';
update content_bodies set title = 'Hida Craft: A Small Liquor Specialty Shop in Hida', description = 'This video introduces Hida Craft, a small liquor specialty shop in Hida. The shop carefully produces each bottle of liquor using seasonal domestic fruits and pure spring water from Hida.' where id = 'IFKz6tva6RiOaeODSktUz';
update content_bodies set title = '磯揚げ　まる天　「よくばりセット」(伊勢市)　｜観光三重｜三重県の観光・旅行情報', description = '新鮮な魚介類の豊かな風味を楽しめる「磯揚げ」。特に人気のたこ棒、チーズ棒、じゃがバター天、海老マヨ棒、生姜れんこん天を詰め合わせた「よくばりセット」はおすすめです。' where id = 'KVNS0Wliwy6NHrrdEx-Rv';
update content_bodies set title = 'Isobeage Maruten ''Yokubari Set'' (Ise City) | Tourism Mie | Mie Prefecture Travel Information', description = 'The ''Isobeage'' offers a rich flavor of fresh seafood. The ''Yokubari Set'', which includes popular items such as octopus sticks, cheese sticks, potato butter tempura, shrimp mayo sticks, and ginger lotus root tempura, is highly recommended.' where id = 'YxS49zzhoicdJ-jR_A5Xn';
update content_bodies set title = '飛騨高山の伝統工芸', description = '岐阜県高山市には、古くから受け継がれる“匠の技”が今も息づいています。飛騨の木工は木を知り尽くし、美しく組み上げられ、飛騨春慶塗は繊細な筆遣いで時を刻みます。これらの技術は自然と共に生きてきた飛騨の人々の知恵と工夫の結晶です。伝統工芸は単なる“モノ”を作るのではなく、心を込めて受け継がれてきた“生き方”そのものです。幾世代にもわたり培われた「手仕事」の魅力は、今の時代にこそ見直される価値があります。静かな工房の音や道具と向き合う真剣な眼差し、完成した作品に宿るぬくもりをぜひ一度体験してみてください。' where id = 't96jYNA4-UKE_N2S3MIG2';
update content_bodies set title = 'Traditional Crafts of Hida Takayama', description = 'In Takayama, Gifu Prefecture, traditional craftsmanship known as ''takumi no waza'' has been preserved for generations. The art of Hida woodworking showcases a deep understanding of wood, while Hida Shunkei lacquerware is characterized by its delicate brushwork. These techniques, developed in harmony with nature, reflect the wisdom and ingenuity of the local people. Traditional crafts are not merely about creating objects; they embody a way of life that has been passed down with care. The charm of ''handwork,'' cultivated over many generations, is increasingly valued in today''s world. The sounds of quiet workshops, the focused gazes of artisans, and the warmth of completed works invite you to explore this captivating world.' where id = 'wv8ONg59q_KtISf_iHNiu';
update content_bodies set title = '枝垂れ桜の郷”朝日町’にある「黒川天満神社」の枝垂れ桜が満開！2025年4月25日 #飛騨高山', description = 'この動画では、朝日町に位置する黒川天満神社の枝垂れ桜が2025年4月25日に満開を迎えた様子を紹介しています。美しい桜の景色が広がるこの神社は、訪れる人々に春の訪れを感じさせる特別な場所です。' where id = 'LretZ0Rwmq9dnR4zxYBGa';
update content_bodies set title = 'The Weeping Cherry Blossoms in Asahi Town: Full Bloom at Kurokawa Tenman Shrine on April 25, 2025 #HidaTakayama', description = 'This video introduces the weeping cherry blossoms at Kurokawa Tenman Shrine located in Asahi Town, which are in full bloom on April 25, 2025.' where id = 'ffQPI3q95svcHlrWUf-Fp';
update content_bodies set title = '「枝垂れ桜の郷」朝日町の最大級の枝垂れ桜', description = 'この動画では、朝日町にある「浅井神明神社」の最大級の枝垂れ桜について紹介しています。歴史ある神社の厳かな雰囲気の中で、満開の桜を楽しむことができ、春の神秘を感じさせる美しさが広がっています。' where id = '3ozuCgi0QXsKMp5t-GoW3';
update content_bodies set title = 'The Largest Weeping Cherry Blossom in Asahi Town', description = 'This video introduces the Asai Shinmei Shrine, which houses one of the largest weeping cherry blossoms in Asahi Town. The shrine, steeped in history, offers a solemn atmosphere where visitors can enjoy the breathtaking beauty of the cherry blossoms in full bloom, evoking a sense of spring''s mystery.' where id = 'BplqujYgIPqjG7PowhZNR';
update content_bodies set title = '枝垂れ桜の郷”朝日町’にある「法正寺」の枝垂れ桜が満開！', description = 'この動画では、朝日町にある法正寺の枝垂れ桜が満開で見ごろを迎えている様子を紹介しています。鐘楼と桜が調和した情緒ある雰囲気の中で、訪れる人々に美しい景観を提供しています。' where id = 'OseFGPxgkAdzfq7Oz_VUg';
update content_bodies set title = 'The Weeping Cherry Blossoms at Hojoji Temple in Asahi Town are in Full Bloom!', description = 'This video showcases the weeping cherry blossoms at Hojoji Temple, located in Asahi Town, which are currently in full bloom. The picturesque setting, featuring the bell tower and cherry blossoms, creates a charming atmosphere, making it an ideal location for photography.' where id = 'Y5gBnVNId-ARHAUTa-xUH';
update content_bodies set title = '飛騨あさひエリアの中でも最大級に大きい枝垂れ桜がある「浅井神明神社」', description = 'この動画では、飛騨あさひエリアに位置する浅井神明神社にある最大級の枝垂れ桜を紹介しています。ライトに照らされた桜は、闇の中に浮かび上がり、まるで春の夢のような美しさを演出しています。' where id = 'nB8USF4jXrgEziPSE8l8C';
update content_bodies set title = 'The Largest Weeping Cherry Blossom at Asai Shinmei Shrine in Hida Asahi Area', description = 'This video introduces the largest weeping cherry blossom located at Asai Shinmei Shrine in the Hida Asahi area. The cherry blossoms, illuminated by lights, create a dreamlike beauty that stands out against the darkness, reminiscent of spring.' where id = 'vIsbTdMcJyHtz11FRdKHT';
update content_bodies set title = '丹生川町にある千光寺で桜が見頃を迎えています', description = 'この動画では、丹生川町に位置する千光寺での桜の見頃について紹介しています。荘厳な歴史と自然のエネルギーが調和するこの空間では、春の光が差し込み、柔らかな花びらが舞う様子が見られます。この季節は、訪れるのに最適な時期です。' where id = 't-jrGzOFvhbKBmMTIr6Wm';
update content_bodies set title = 'Cherry Blossoms in Full Bloom at Senkoji Temple in Niyugawa Town', description = 'This video introduces the cherry blossoms in full bloom at Senkoji Temple located in Niyugawa Town. The temple, with its majestic history and the energy of nature, creates a harmonious space where the spring light shines through, and soft petals dance in the air. This season is truly the best time to visit.' where id = 'UGBM2wylOT9RjQ6adUTOI';
update content_bodies set title = '朝日町には美しい枝垂れ桜が多くあり「枝垂れ桜の里」と呼ばれています。中でも「青屋神明神社」の枝垂れ桜は、目の前に水田が広がり、映りこむ逆さの桜は圧倒的な美しさ♡撮影2025.4.22　 #飛騨高山', description = 'この動画は朝日町の美しい枝垂れ桜について紹介しています。特に「青屋神明神社」の枝垂れ桜とその周辺の風景に焦点を当てています。' where id = 'JHhWCMyQQ_9GPWwi0rK4Y';
update content_bodies set title = 'Asahi Town is known for its beautiful weeping cherry blossoms, referred to as the ''Village of Weeping Cherry Blossoms''. Among them, the weeping cherry tree at Aoya Shinmei Shrine offers a stunning view, with rice fields reflecting the inverted blossoms, creating an overwhelming beauty. Captured on April 22, 2025. #HidaTakayama', description = 'This video introduces the beautiful weeping cherry blossoms in Asahi Town, focusing particularly on the weeping cherry tree at Aoya Shinmei Shrine and the surrounding scenery.' where id = 'ZoQALf0KbkBXnIg6josyK';
update content_bodies set title = '宮川の川沿いで開催される宮川朝市', description = 'この動画では、毎朝宮川朝市が開催される宮川の川沿いを紹介しています。シダレ桜などの桜を眺めながら散策するのに最適なスポットで、川のせせらぎを聞きながらのんびりと癒される様子が映し出されています。' where id = '3YOkakDW_nlholwYRw5pZ';
update content_bodies set title = 'Miyagawa Morning Market by the River', description = 'This video introduces the Miyagawa River area where the Miyagawa Morning Market is held every morning. It is a perfect spot for a leisurely stroll while enjoying the view of cherry blossoms, including weeping cherry trees. The soothing sound of the river enhances the relaxing atmosphere.' where id = 'cZm4_z6UTyQLYGVgkmnlk';
update content_bodies set title = '日本の雪の村にある隠れた温泉旅館に宿泊 | 里山十条 新潟', description = 'この英語対応の旅館は、現代生活から離れ、リラックスするのに最適な場所です。美しい雪の村に位置し、オサワ駅からの予約制の無料シャトルバスや、越後湯沢駅からの定額タクシーで簡単にアクセスできます。2名分の夕食と朝食を含む合計料金は約126,246円（約839.20米ドル）です。動画では、旅館のロビー、客室ツアー、公共浴場、食事体験、美しい雪景色など、さまざまな側面が紹介されています。客室にはプライベートの露天風呂もあり、朝食も楽しめます。日本国内を移動する際には、便利でお得な「ジャパンレールパス」がおすすめです。' where id = '6QdzZSDqvgFCGPB0S_Ld9';
update content_bodies set title = 'Staying at Hidden Onsen Ryokan in Japan''s Snow Village | Satoyama-jujo Niigata', description = 'This English-friendly ryokan offers a perfect escape from modern life, allowing guests to relax in a serene environment. Located in a picturesque snow village, it provides easy access via a reservation-based free shuttle bus from Osawa Station or a fixed-price taxi from Echigo-Yuzawa Station. The total cost for two people, including dinner and breakfast, is approximately 126,246 yen (about 839.20 USD). The video showcases various aspects of the ryokan, including the lobby, room tour, public bath, dining experiences, and beautiful snow views. Guests can also enjoy a private open-air bath in their room and a delightful breakfast. For those interested in traveling throughout Japan, the Japan Rail Pass is recommended for its convenience and affordability.' where id = 'QhUc0B62o9zzzn2QhQ5_v';
update content_bodies set title = '岐阜県に三社ある護国神社の内の一つ「飛騨護国神社」', description = 'この動画では、岐阜県に存在する三社の護国神社の一つである「飛騨護国神社」について紹介しています。飛騨高山に位置し、地域の歴史や文化に深く根ざした神社です。' where id = 'kSxUQdZHoPcQA9Vwd4TXP';
update content_bodies set title = 'Hida Gokoku Shrine, One of the Three Gokoku Shrines in Gifu Prefecture', description = 'This video introduces Hida Gokoku Shrine, one of the three Gokoku Shrines located in Gifu Prefecture.' where id = 'yBgrN0SIgO7pRPxxI7OTO';
update content_bodies set title = '飛騨高山のランドマーク「中橋」', description = 'この動画では、飛騨高山のランドマークである「中橋」について紹介しています。朱色の欄干と桜のピンク色が調和し、ライトアップされた光が川面に映り込む様子は、まるで絵画のような美しさを放っています。' where id = 'gXwne-bkad2iBN66c2U3U';
update content_bodies set title = 'Nakahashi Bridge: A Landmark of Hida Takayama', description = 'This video introduces Nakahashi Bridge, a landmark in Hida Takayama. The bridge features vibrant red railings and the soft pink of cherry blossoms, creating a picturesque scene that is beautifully illuminated at night, reflecting on the river''s surface like a painting.' where id = 'S9M6ndQMr0Wwt8N6_-DQR';
update content_bodies set title = '朝日町にある青屋神明神社の枝垂れ桜が、満開を迎えています', description = 'この動画では、朝日町に位置する青屋神明神社の枝垂れ桜について紹介しています。昼間の青空に映えるその姿は見事で、4月21日から始まったライトアップでは、その美しさが幻想的な世界へと変わります。' where id = 'vuUftr1tO8-wFszv4Kml6';
update content_bodies set title = 'The Weeping Cherry Blossoms at Aoya Shinmei Shrine in Asahi Town are in Full Bloom', description = 'This video introduces the weeping cherry blossoms at Aoya Shinmei Shrine located in Asahi Town. The blossoms are stunning against the blue sky during the day, but from April 21, the illumination enhances their beauty, creating a fantastical atmosphere.' where id = 'GsHNsELoOwjsZ1J0wLmGo';
update content_bodies set title = '飛騨一之宮 常泉寺川堤のしだれ桜が、今年も美しく満開を迎えました', description = 'この動画では、飛騨一之宮の常泉寺川堤にあるしだれ桜が、今年も美しく満開を迎えた様子を紹介しています。' where id = 's_HjX00RyWmXWuXVJZx2p';
update content_bodies set title = 'The Weeping Cherry Blossoms at Jōsenji Riverbank in Hida Ichinomiya Are in Full Bloom Again This Year', description = 'This video introduces the weeping cherry blossoms at Jōsenji Riverbank in Hida Ichinomiya, which have beautifully reached full bloom this year.' where id = '1ZQs8gKYSn6egMr0rKnAu';
update content_bodies set title = '清見町大谷地区の西光寺裏の山すそに広がるフクジュソウの花々', description = 'この動画では、清見町大谷地区の西光寺裏の山すそに広がる約2,000平方メートルのフクジュソウの花が満開である様子を紹介しています。可愛らしいお椀型の花が見頃を迎えています。' where id = '2XEeGAjF-Ifz3plr2JA6V';
update content_bodies set title = 'A Field of Blooming Fukujusou in Seikouji Area, Kiyomi Town', description = 'This video showcases the stunning sight of blooming Fukujusou flowers covering approximately 2,000 square meters at the foot of the mountain behind Seikouji Temple in the Oya district of Kiyomi Town. The flowers are currently at their peak, displaying their charming, bowl-shaped blossoms.' where id = '6hDIm9uthGhU1WMAPd9h3';
update content_bodies set title = '高山祭の伝統行事「御巡幸」', description = 'この動画は高山祭の伝統行事「御巡幸」について紹介しています。神輿を中心に、獅子舞や闘鶏楽、裃姿の警固など、伝統的な装束をまとった数百名の美しい祭行列が祭区域内を練り歩く様子が見られます。' where id = 'm-IWpSCxuWN6zFuEvhw9h';
update content_bodies set title = 'Traditional Event of Takayama Festival: O-Mikoshi Procession', description = 'This video introduces the traditional event ''O-Mikoshi'' of the Takayama Festival. It showcases a magnificent procession featuring hundreds of participants dressed in traditional attire, including lion dances, cockfighting performances, and guards in ceremonial clothing, all parading through the festival area.' where id = '6dpFOnxUifsUfiEGWs06e';
update content_bodies set title = '色鮮やかな舞と音の競演春の高山祭「闘鶏楽」', description = 'この動画は春の高山祭「闘鶏楽」について紹介しています。闘鶏楽では、白地に色鮮やかな鳳凰が描かれた衣装を身にまとった参加者が、鉦と締太鼓を打ちながら祭行列を巡行します。' where id = 'QntcBxnJWIcgWSyWcnENz';
update content_bodies set title = 'Vibrant Dance and Sound Competition: Spring Takayama Festival ''Tōchiraku''', description = 'This video introduces the Spring Takayama Festival known as ''Tōchiraku''. The festival features performers dressed in colorful costumes adorned with phoenix designs, parading while playing gongs and taiko drums.' where id = 'YAaqi9hxx2rYnae8FRn2E';
update content_bodies set title = '伝統の鼓動が響く、高山祭の獅子舞', description = 'この動画は高山祭の獅子舞について紹介しています。勢いのある動きや力強くも繊細な舞、笛や太鼓の音色とともに響く獅子の咆哮が観客の心を震わせ、世代を越えて受け継がれる誇りを表現しています。' where id = 'i1jsGOFzTxwyIwXA-VfZ-';
update content_bodies set title = 'The Vibrant Tradition of Takayama Festival''s Lion Dance', description = 'This video introduces the lion dance of the Takayama Festival, showcasing its dynamic movements and the powerful yet delicate performance. The sounds of flutes and drums resonate throughout the town, accompanied by the roar of the lion, captivating the hearts of the audience. It embodies the pride passed down through generations.' where id = '32sh1WgD6sOk5JClCzQ5s';
update content_bodies set title = '春の高山祭が無事に終了しました。', description = '14日は快晴でしたが、夜祭は天候不良のため中止となりました。15日は雨のため、屋台の曳き揃えや御巡幸は中止となりましたが、各蔵で屋台が公開され、からくり奉納も無事に行われました。この動画は春の高山祭について紹介しています。' where id = 'cxNXNeDIsGGaShijMuQ_7';
update content_bodies set title = 'The Spring Takayama Festival has successfully concluded.', description = 'The festival took place on the 14th with clear weather, but the night festival was canceled due to poor weather conditions. On the 15th, rain led to the cancellation of the float procession and the shrine visit, but the floats were displayed at various stores, and the karakuri performances were successfully held at each store.' where id = 'H8FenZcPSkLBkDpBH7Hcb';
update content_bodies set title = '春のおとずれの遅い飛騨で迎えたひなまつり', description = 'この動画では、春のおとずれが遅い飛騨で行われたひと月おくれのひなまつりと生きびな祭について紹介しています。生きびな祭では、伝統的な雛人形や祭りの様子が披露されます。' where id = 'cFmxtAr7UxG_LlpcDQMTa';
update content_bodies set title = 'Delayed Arrival of Spring in Hida: Celebrating ''Hinamatsuri'' on April 3rd', description = 'This video introduces the ''Hinamatsuri'' celebration, which is held a month late in Hida, where the arrival of spring has been delayed. The event features the ''Ikibina Matsuri,'' showcasing traditional dolls and festivities.' where id = 'YHvkytwDQp2R94V-jocHo';
update content_bodies set title = '祭屋台のひとつ恵比須台の大規模な修理が139年ぶりに行われ、今日は試運転です。', description = 'この動画では、祭屋台のひとつである恵比須台が139年ぶりに大規模な修理を受け、試運転が無事に行われたことを紹介しています。青空の下での試運転の様子が伝えられています。' where id = '93yTj7oUmPehRIWeZl0WW';
update content_bodies set title = 'A large-scale repair of the Ebisu-dai festival float has been conducted for the first time in 139 years, and today it successfully underwent a trial run.', description = 'This video introduces the large-scale repair of the Ebisu-dai festival float, which took place for the first time in 139 years, and highlights the successful trial run that occurred under clear blue skies.' where id = '-4V9lKR-1msO-Rmv1BmTc';
update content_bodies set title = '国の重要文化財に指定されている「吉島家住宅」', description = 'この動画では、国の重要文化財に指定されている「吉島家住宅」について紹介しています。明治40年に建てられたこの町家は、飛騨匠の技が光る美しい建築であり、重厚な歴史を感じられる空間が魅力です。' where id = 'cFYnOz3KKUfAVvAyv0tMo';
update content_bodies set title = 'Yoshijima House: A National Important Cultural Property', description = 'This video introduces the Yoshijima House, designated as a National Important Cultural Property. Built in 1907, this traditional townhouse showcases the exquisite craftsmanship of Hida artisans and offers a space rich in historical significance.' where id = 'WUgnl3VRGB-BqZhX8zzBW';
update content_bodies set title = '明治期の町家として初めて国の重要指定文化財に指定された「日下部民藝館」', description = 'この動画では、明治期の町家として初めて国の重要指定文化財に指定された「日下部民藝館」について紹介しています。ここでは、明治天皇の即位を記念して作られた「明治雛」などの展示が行われています。' where id = 'inQsc0MFdM_-GTTQLQeh6';
update content_bodies set title = 'Kusakabe Mingeikan: The First Meiji-Era Townhouse Designated as an Important Cultural Property', description = 'This video introduces the Kusakabe Mingeikan, the first Meiji-era townhouse to be designated as an Important Cultural Property by the national government. The museum features exhibits such as the ''Meiji Hina,'' created to commemorate the enthronement of Emperor Meiji.' where id = 'LGtCJARatWxuj3LH5JWo1';
update content_bodies set title = '高山の大人な穴場スポットとしてオススメ「東山遊歩道」', description = 'この動画では、高山の大人向けの穴場スポット「東山遊歩道」を紹介しています。道沿いには古い町並みが広がり、由緒ある12の寺社が点在しています。訪れる人々は、のんびりと散策しながら、歴史的な景観を楽しむことができます。' where id = 'DwTx6yBV6lXl6SAMtTz84';
update content_bodies set title = 'Recommended Hidden Gem for Adults in Takayama: Higashiyama Walking Path', description = 'This video introduces the Higashiyama Walking Path, a recommended hidden gem for adults in Takayama. Visitors can leisurely stroll along the path while enjoying views of the old town and visiting twelve historic temples and shrines located along the way.' where id = 'iq7LtUvzRGxDaAo1Icjkj';
update content_bodies set title = '雪の古い町並　#飛騨高山', description = 'この動画では、雪に覆われた古い町並みを紹介しています。飛騨高山の美しい景観が映し出され、冬の風情を感じることができます。雪の中での町の様子や、伝統的な建物がどのように雪と調和しているかが描かれています。' where id = '5fYb99hXgiCMbNel7uXNw';
update content_bodies set title = 'Old Townscape in Snow - Hida Takayama', description = 'This video introduces the old townscape covered in snow.' where id = 'XYYYO4v_P_Ix9OW7xZ5D1';
update content_bodies set title = '荘厳な雰囲気漂う「櫻山八幡宮」', description = 'この動画では、荘厳な雰囲気が漂う「櫻山八幡宮」について紹介しています。秋の「高山祭（八幡祭）」の例祭の場所として有名で、多くの参拝客で賑わっています。境内は一面の白銀世界で、青空に雪が映え、しっとりとした散策が楽しめる場所です。' where id = '9V1O_M5MfwJ4ayrkDYefp';
update content_bodies set title = 'Sakurayama Hachimangu Shrine: A Majestic Atmosphere', description = 'This video introduces Sakurayama Hachimangu Shrine, known for its majestic atmosphere. It is famous as the site of the Takayama Festival (Hachiman Festival) in autumn, attracting many visitors. The shrine grounds are covered in a beautiful white world, with snow reflecting against the blue sky, making it a delightful place for a serene stroll.' where id = 'ENdwgnEsDjHJVpu3HBTbK';
update content_bodies set title = '新平湯温泉 タルマかねこおりライトアップ', description = 'この動画では、新平湯温泉の名所であるタルマの滝と親水公園一帯で開催される「新平湯温泉 タルマかねこおりライトアップ」について紹介しています。このイベントでは、奥飛騨の美しい自然をテーマにした氷の芸術作品が展示されます。' where id = '8GvzIjgmUC_eHibFccfQL';
update content_bodies set title = 'Shin-Hirayu Onsen Taruma Kanekoori Light Up', description = 'This video introduces the Shin-Hirayu Onsen Taruma Kanekoori Light Up event, held in the area around Taruma Falls and the riverside park, a famous spot in Shin-Hirayu. The event features ice art creations inspired by the beautiful natural scenery of Okuhida.' where id = '2Za2Ht2u9uwDI5JFNSpu6';
update content_bodies set title = '冬ならではの絶景が楽しめる氷点下の森', description = 'この動画では、氷点下の森について紹介しています。氷点下10度の冬の自然を逆手に取り、氷の森が制作されます。昼間はブルーに輝き、夜は青、赤、緑とライトアップされるこの美しいイベントは、30年以上にわたり人気を誇っています。飛騨高山で楽しめる冬の絶景を体験できる貴重な機会です。' where id = 'bJC2i0_m94gQqMHmz_Zcs';
update content_bodies set title = 'A Stunning Winter Wonderland: The Frozen Forest', description = 'This video introduces the Frozen Forest, a breathtaking winter attraction that thrives in sub-zero temperatures. With temperatures dropping to minus 10 degrees Celsius, the forest transforms into a magical ice wonderland. During the day, the ice glows in shades of blue, while at night, it is illuminated in vibrant colors such as blue, red, and green. This enchanting event has been a beloved tradition for over 30 years in Hida Takayama, showcasing the beauty of nature in winter.' where id = 'H61ove4CEc7oNCbb7mdS6';
update content_bodies set title = '15日から25日まで開催「平湯大滝結氷まつり」', description = 'この動画は「平湯大滝結氷まつり」について紹介しています。豪快に流れ落ちる滝水が、奥飛騨の冬の寒さによって巨大な氷柱に変わり、荘厳な青白い氷柱がライトアップされ、幻想的な世界が広がっています。' where id = 'ptTNo_WR84PGBpvx1a5Y9';
update content_bodies set title = 'Hirayu Otaki Ice Festival Held from 15th to 25th', description = 'The video introduces the ''Hirayu Otaki Ice Festival,'' where the majestic waterfall transforms into massive ice pillars due to the cold winter of Okuhida. The stunning blue-white ice formations are illuminated, creating a fantastical world.' where id = 'Rvjrz--jHsPDKPyDa_viF';
update content_bodies set title = '飛騨高山の桜', description = '岐阜県高山市は、雄大な山々に囲まれた自然豊かなエリアで、日本一面積が広く、桜の開花時期が異なるため、長い期間にわたり美しい桜の風景を楽しむことができます。観光名所の赤い中橋と桜のコントラストは見事で、山間の隠れた名所では幻想的な花景色を楽しむことができます。高山の桜は訪れる人々の心を癒やし、特別な旅の思い出を演出します。春の息吹を感じながら、桜巡りを楽しんでみませんか？' where id = '5rbv4bzQ4KxosOXK3VTTb';
update content_bodies set title = 'Cherry Blossoms in Hida Takayama', description = 'Takayama, located in Gifu Prefecture, is surrounded by majestic mountains and is rich in nature. It boasts the largest area in Japan where cherry blossoms bloom at different times, allowing visitors to enjoy beautiful cherry blossom scenery for an extended period. The contrast between the iconic red Nakabashi Bridge and the cherry blossoms creates a stunning visual, while hidden spots in the mountains offer enchanting views of the flowers. The cherry blossoms in Takayama soothe the hearts of visitors and create special memories during their travels. Experience the breath of spring by enjoying a cherry blossom tour.' where id = 'LWZ3WlG7SkSyJjXsrWGcf';
update content_bodies set title = '木々が生い茂り自然のパワーを感じる「日枝神社」', description = 'この動画では、木々が生い茂る「日枝神社」を紹介しています。雪が降り積もった神社は、凛とした雰囲気を醸し出し、どこか神秘的で心が落ち着くスポットです。自然の力を感じることができる場所として、多くの人々に愛されています。' where id = 'WW45Do5jaInIVTz2WS9-z';
update content_bodies set title = 'Hie Shrine: A Spot to Feel the Power of Nature Surrounded by Lush Trees', description = 'This video introduces Hie Shrine, a serene spot where one can feel the power of nature amidst lush trees. The snow-covered landscape creates a tranquil and somewhat mystical atmosphere.' where id = '0JgeFAwg8RNCYni3wIlUJ';
update content_bodies set title = '名古屋方面から東海北陸自動車道で高山へ向かう道', description = 'この動画では、名古屋方面から東海北陸自動車道を利用して高山へ向かう道を紹介しています。道中は一面の白銀世界が広がっており、訪れる際には十分に注意してお越しください。' where id = 'cexkzbfDarYOS4gsapDb5';
update content_bodies set title = 'The Road to Takayama from Nagoya via the Tokai-Hokuriku Expressway', description = 'This video introduces the road from Nagoya to Takayama via the Tokai-Hokuriku Expressway, showcasing a stunning landscape of pure white snow. Travelers are advised to take care while making their journey.' where id = 'TH7n3RVslNcSMLD2EANJN';
update content_bodies set title = '奥飛騨温泉郷新穂高温泉の中尾にある白山神社で開催される「中尾かまくらまつり」', description = 'この動画は、奥飛騨温泉郷新穂高温泉の中尾に位置する白山神社で行われる「中尾かまくらまつり」について紹介しています。神社の境内には、大小さまざまなかまくらが登場し、訪れる人々を楽しませます。' where id = 'O2aduaIcvdUuLZjewIpBu';
update content_bodies set title = 'Nakao Kamakura Festival at Hakusan Shrine in Okuhida Onsen-go, Shin-Hotaka Onsen', description = 'This video introduces the Nakao Kamakura Festival held at Hakusan Shrine in Nakao, located in Okuhida Onsen-go, Shin-Hotaka Onsen. The shrine grounds feature various sizes of kamakura, traditional snow huts.' where id = '2rtr6HufUJhPktMiuDMtU';
update content_bodies set title = '日本一高い場所にある観光鍾乳洞「飛騨大鍾乳洞」', description = 'この動画では、標高約900メートルに位置する日本一高い観光鍾乳洞「飛騨大鍾乳洞」と、冬期限定で高さ約30メートルにもなる谷の水を氷らせた「氷の渓谷」について紹介しています。氷の渓谷では、蒼白の氷柱が美しい絶景を作り出しています。' where id = '1SLIbGqfATwSgVa9sgCpl';
update content_bodies set title = 'The Highest Tourist Limestone Cave in Japan: Hida Great Limestone Cave', description = 'This video introduces the Hida Great Limestone Cave, located at an elevation of approximately 900 meters, making it the highest tourist limestone cave in Japan. It also features the ''Ice Valley,'' a winter-only attraction where water from the valley freezes to a height of about 30 meters, creating stunning ice pillars that offer a breathtaking view.' where id = 'ewYGOe3ppex9u-hu9FpfV';
update content_bodies set title = '毎年大人気!完売必至の予約期間限定販売アップルパイ。', description = 'この動画では、毎年大人気で完売必至の予約期間限定販売のアップルパイについて紹介しています。甘く煮たリンゴが4つ以上も入っており、ボリューム満点です。砂糖を控えめに作られているため、素朴で優しい味わいが特徴です。' where id = 'lEdEtQP6ZtpsZfHmfsRex';
update content_bodies set title = 'Popular Every Year! Limited-Time Reservation Sales of Must-Have Apple Pie.', description = 'This video introduces the highly popular, must-have apple pie available for a limited reservation period each year. The pie is filled with more than four pieces of sweetened cooked apples, offering a generous portion. It is made with a moderate amount of sugar, resulting in a simple and gentle flavor that is characteristic of this treat.' where id = 'M9plltGI_kZPE5vwW0I3p';
update content_bodies set title = '高山冬の風物詩「二十四日市」がはじまりました！', description = 'この動画では、高山の冬の風物詩である「二十四日市」について紹介しています。このイベントでは、飛騨の伝統的な民芸品である名しょうけや有道しゃくしの実演販売が行われ、宮笠や飛騨高山のご当地グルメ、お得な商品もたくさん揃っています。' where id = 'iOdVAEsTd5F5Sx7_cNz5T';
update content_bodies set title = 'The Winter Tradition of Takayama: ''Nijushinichi'' Has Begun!', description = 'This video introduces ''Nijushinichi,'' a winter tradition in Takayama. The event features demonstrations and sales of traditional Hida crafts, including the ''Meishouke'' and ''Miyagasa.'' Visitors can also enjoy local gourmet food from Takayama and find many great deals.' where id = 'b02QVC-XIqpqLbkGFUJqi';
update content_bodies set title = '奥飛騨温泉郷の雪化粧した山々', description = 'この動画では、奥飛騨温泉郷を走ると見られる美しい雪化粧した山々と、広がる雪景色の様子を紹介しています。青空に映える真っ白な雪は、今だけの特別な景色を提供しています。' where id = 'qFwFsElr2DrV7r5Kujo34';
update content_bodies set title = 'Scenic Snow-Covered Mountains in Okuhida Onsen', description = 'This video showcases the beautiful snow-covered mountains and the expansive snowy landscape as one travels through Okuhida Onsen. The bright white snow contrasts beautifully against the blue sky, offering a unique view that can only be experienced at this time.' where id = 'UJy5_brzjOMPrkKe2xv8e';
update content_bodies set title = '合掌造りなど日本の美しい原風景と飛騨人の暮らしや文化を体験できる「#飛騨の里」', description = 'この動画では、合掌造りなどの日本の美しい原風景と、飛騨人の暮らしや文化を体験できる「#飛騨の里」について紹介しています。四季折々の風景を楽しむことができるスポットですが、特に冬の飛騨の里は雪に包まれた幻想的な雰囲気が広がり、魅力が満載です。' where id = 'Kk_ETttB9fohB__l3iSZe';
update content_bodies set title = 'Experience the Beautiful Original Scenery of Japan and the Life and Culture of Hida People at ''Hida no Sato''', description = 'This video introduces ''Hida no Sato'', where you can experience the beautiful original scenery of Japan, including traditional gassho-zukuri architecture, as well as the life and culture of the Hida people. It is a spot where you can enjoy the changing landscapes of the four seasons, but particularly in winter, Hida no Sato transforms into a fantastical atmosphere enveloped in snow, offering a unique charm.' where id = 'JWH4o6ubBbi3TMmUYabKc';
update content_bodies set title = '新穂高温泉中尾高原と鍋平園地を結ぶ「北アルプス大橋」', description = 'この動画では、新穂高温泉中尾高原と鍋平園地を結ぶ「北アルプス大橋」について紹介しています。このアーチ橋は全長150メートル、高さ70メートルで、迫力ある景観を提供します。雪化粧した北アルプスが真っ青な空を背景に際立ち、訪れる人々に感動を与えます。' where id = 'EMELMAeFhnjcMm9LnUUSA';
update content_bodies set title = 'Northern Alps Bridge Connecting Shin-Hotaka Onsen Nakao Highland and Nabe-daira Park', description = 'This video introduces the ''Northern Alps Bridge,'' a 150-meter-long arch bridge that stands 70 meters high, offering a breathtaking view. The snow-covered Northern Alps stand out against the clear blue sky.' where id = 'Fksnk7N47pp1xtSNf1BT4';
update content_bodies set title = '飛騨の里ライトアップ', description = '「飛騨の里ライトアップ」は来月末まで開催されており、降り積もった雪と中心にある凍った池にライトが反射し、幻想的な雰囲気を醸し出しています。この時期にしか見ることができない冬の風物詩で、特別な体験ができます。' where id = 'J3-8TBhi38_y2mfcSzETp';
update content_bodies set title = 'Hida no Sato Light Up Event', description = 'The ''Hida no Sato Light Up'' event is currently being held until the end of next month. The scene features snow-covered landscapes and a frozen pond at the center, where lights reflect, creating a magical atmosphere. This is a winter spectacle that can only be experienced during this season.' where id = 'VDDi86VlF7JVfxC8bROU9';
update content_bodies set title = '宮峠トンネルを抜ければ、一面に広がる白銀世界と青空', description = 'この動画では、宮峠トンネルを抜けた先に広がる白銀の世界と青空、冬の空気の中での夕日の美しさ、そして四季を感じることができるドライブルートについて紹介しています。凛とした冬の空気の中で、夕日が空をオレンジ色に染め上げる様子が印象的です。' where id = '8ew2dwi1DbpD0DJRhHAC7';
update content_bodies set title = 'Beyond the Miyatoge Tunnel: A Winter Wonderland', description = 'This video showcases the breathtaking winter landscape and blue skies that unfold after passing through the Miyatoge Tunnel. It captures the essence of the crisp winter air and the beautiful orange hues of the sunset painting the sky. The route is a perfect representation of the changing seasons, making it an ideal drive for those who appreciate nature''s beauty.' where id = 'vyCWmnPtMuqexbtAwp3mc';
update content_bodies set title = '2024年も残すところあとわずかとなりました。', description = 'この動画では2024年の残りの期間について紹介しており、今年も多くのいいねやコメントをいただいたことに感謝の意を表しています。' where id = 'qJPxbyRFi1bWY6uK0YRCa';
update content_bodies set title = '2024 is almost over.', description = 'This video introduces the remaining period of 2024 and expresses gratitude for the likes and comments received throughout the year.' where id = '4ZCH-WfLI3nNRDS_5iES1';
update content_bodies set title = '雪と中橋', description = 'この動画では、飛騨高山にある中橋の赤色と真っ白な雪との美しいコントラストについて紹介しています。' where id = 'yl3hXVnmWq6IZwZ9HhnsZ';
update content_bodies set title = 'Snow and Nakabashi', description = 'This video introduces the beautiful contrast between the red Nakabashi bridge and the pure white snow in Hida Takayama.' where id = 'f3taAWxU4lvCC1OfQSV1e';
update content_bodies set title = '今回のHIDABITOは飛騨春慶塗師　熊崎信行氏', description = 'この動画では、飛騨春慶塗師の熊崎信行氏を紹介しています。熊崎氏は48年間この職に従事しており、430年の歴史を持つ飛騨春慶の塗師としての人生や、彼の「ツナグ」という思いについて伺っています。' where id = 'JPkZcPCZlxJl8yK41cKZu';
update content_bodies set title = 'HIDABITO Features Kumazaki Nobuyuki, a Hida Shunkei Lacquer Craftsman', description = 'This video introduces Kumazaki Nobuyuki, a craftsman of Hida Shunkei lacquerware, who has been in the profession for 48 years. Hida Shunkei has a history of 430 years, and the video explores his life as a lacquer craftsman and his thoughts on connection.' where id = 'gEExu_T0v42Vh0MCXBbu8';
update content_bodies set title = '国指定天然記念物！樹齢1250年以上といわれる「飛騨国分寺」の大イチョウが見頃を迎えています。', description = 'この動画では、国指定天然記念物であり、樹齢1250年以上とされる「飛騨国分寺」の大イチョウについて紹介しています。高さ約28mのこのイチョウは、見上げると一面が黄金色に染まった美しい景色を楽しむことができます。' where id = 'Fbw7uFroUZlnFUDLlvI96';
update content_bodies set title = 'National Natural Monument! The Great Ginkgo Tree of Hida Kokubunji, estimated to be over 1250 years old, is in full bloom.', description = 'This video introduces the Great Ginkgo Tree of Hida Kokubunji, a national natural monument believed to be over 1250 years old. Standing at approximately 28 meters tall, it offers a stunning view of golden foliage when looked up.' where id = 'MjTZ4cfN78C1oA-LMjw-c';
update content_bodies set title = '高山の大人な穴場スポット「東山遊歩道」', description = 'この動画では、高山の大人な穴場スポットである「東山遊歩道」について紹介しています。道沿いには古い町並みを眺めながら、由緒ある12の寺社が点在しており、のんびりと散策することができます。紅葉も終盤を迎えており、風景の美しさを一層引き立てています。' where id = '1MfGu93dqB8_SWRKWh7gN';
update content_bodies set title = 'Hidden Gem for Adults in Takayama: Higashiyama Walking Path', description = 'This video introduces the Higashiyama Walking Path, a hidden gem for adults in Takayama. Visitors can leisurely stroll along the path while enjoying views of the old town and exploring twelve historic temples and shrines that are scattered along the way. The autumn foliage is also nearing its end, adding to the scenic beauty of the area.' where id = 'iSi-a7CPMY91j-fRE-4OS';
update content_bodies set title = '高山市内を一望できる穴場の紅葉スポット「北山公園 鮎崎城址公園」', description = 'この動画では、高山市内を一望できる穴場の紅葉スポット「北山公園 鮎崎城址公園」について紹介しています。ここでは、山間の段々畑の風景を眺めながら、北山遊歩道を散策することができ、紅葉と里山の美しい風景を楽しむことができます。' where id = 'JxyIV6jT0m2JD6oXz1G6f';
update content_bodies set title = 'Hidden Autumn Foliage Spot Overlooking Takayama City: Kitayama Park Ayuzaki Castle Ruins Park', description = 'This video introduces Kitayama Park Ayuzaki Castle Ruins Park, a hidden spot for autumn foliage that offers a panoramic view of Takayama City. Visitors can enjoy a stroll along the Kitayama Promenade while taking in the beautiful autumn leaves and the scenic terraced fields of the rural landscape.' where id = 'OcczJVVd4koVrR0vg9iVQ';
update content_bodies set title = 'まるで時代劇のセットのような、江戸時代にタイムスリップした気分が満喫できる「高山陣屋」', description = 'この動画では、江戸時代にタイムスリップした気分を味わえる「高山陣屋」について紹介しています。陣屋庭園では紅葉が見頃を迎え、美しい情景を楽しむことができます。また、陽の光が注ぎ込むことで、撮影スポットとしての魅力も増しています。' where id = 'iDzWKtpIE9T1axirl6iRa';
update content_bodies set title = 'Experience the Edo Period at Takayama Jinya, a Set Like a Period Drama', description = 'This video introduces Takayama Jinya, where visitors can feel as if they have traveled back to the Edo period, reminiscent of a period drama set. The garden is currently showcasing beautiful autumn foliage, providing a picturesque scene to enjoy. The sunlight streaming in makes it an ideal spot for photography.' where id = 'slPGVVa-MEds4vtMNwu7v';
update content_bodies set title = '木々が生い茂り、とても爽やかで自然のパワーを感じる「日枝神社」', description = 'この動画は日枝神社について紹介しています。境内まで続く道には、赤や黄色など色鮮やかに染まった木々が生い茂り、自然の美しさを感じることができます。撮影は2024年11月20日、飛騨高山で行われました。' where id = 'MYbUK_-uQrX6S2xUyJ7jO';
update content_bodies set title = 'Hie Shrine: A Refreshing Place Surrounded by Lush Trees', description = 'This video introduces Hie Shrine, a place where you can feel the power of nature. The path leading to the shrine is lined with trees that are vividly colored in red and yellow, showcasing the beauty of autumn foliage. Filmed on November 20, 2024, in Hida Takayama.' where id = 'qV25ENBTSMvzPHdVq_X32';
update content_bodies set title = '飛騨高山　FarmersGifts Hidarice', description = '飛騨高山のお米は、澄んだ空気と清らかな水、昼夜の温度差が豊かな環境で育まれています。飛騨山脈に囲まれたこの地で、手間ひまかけて栽培されるお米は、甘みが際立ち、ふっくらとした食感が特徴です。高山市の豊かな自然が育むお米は、一粒一粒に深い旨味が詰まっています。' where id = 'kcvsBRP5fCtzMK5u6lPq5';
update content_bodies set title = 'Hida Takayama FarmersGifts Hidarice', description = 'Hida Takayama rice is cultivated in a rich environment characterized by clear air, pure water, and significant temperature differences between day and night. Surrounded by the Hida Mountains, the rice is grown with great care, resulting in a distinctive sweetness and fluffy texture. Each grain of rice embodies deep umami, nurtured by the abundant nature of Takayama.' where id = 'q9NKcTBaQx81qLPtrSKAP';
update content_bodies set title = '岐阜県名水50選認定、女男滝の紹介', description = 'この動画では、岐阜県名水50選に認定された女男滝について紹介しています。女男滝は、舟山に源を発し、益田川に注ぐ牛牧谷のあたりに位置しています。上下二段からなる滝で、上が女滝、下が男滝と呼ばれ、子宝伝説が残っており、古くから地域の人々に親しまれています。' where id = '9v8Ojhtjh92ZC593PhVYr';
update content_bodies set title = 'Introduction to Onna Otaki Waterfall, a Selected Water Source in Gifu Prefecture', description = 'This video introduces Onna Otaki, a waterfall located at the confluence of the Ubumaki Valley, originating from Funayama, and the Masuda River. The waterfall consists of two tiers, known as the ''female'' and ''male'' falls, which are associated with a legend of fertility. It has been cherished by locals for a long time.' where id = 'dt0hA8Zu9rnGa0OSMrLpF';
update content_bodies set title = '自然に囲まれた美しい「あららぎ湖」', description = 'この動画では、高山インターから車で約30分の場所に位置する「あららぎ湖」について紹介しています。湖は豊かな自然に囲まれ、透明度の高い水面には四季の景色が映り込み、訪れるたびに異なる表情を見せてくれます。' where id = 'bZR-GK3GgEfqpwQ_tlGMj';
update content_bodies set title = 'Araragi Lake: A Beautiful Lake Surrounded by Nature', description = 'This video introduces Araragi Lake, located about 30 minutes by car from Takayama Interchange. The lake is surrounded by rich nature and features a highly transparent surface that reflects the seasonal scenery, offering different views with each visit.' where id = 'h9nOn4ZmPC2OGdmdvbJbT';
update content_bodies set title = '一之宮町にある往還寺の銀杏が見頃を迎えています', description = 'この動画では、一之宮町の往還寺にある銀杏の様子を紹介しています。推定樹齢200年以上の2本のイチョウは、全長約35mで、見上げると鮮やかな黄色と青空の美しいコントラストが広がります。' where id = 'U3E4bBbgju558Q5UJtEMh';
update content_bodies set title = 'The Ginkgo Trees at Okanji Temple in Ichinomiya Town are at Their Peak', description = 'This video introduces the ginkgo trees at Okanji Temple in Ichinomiya Town. The two ginkgo trees, estimated to be over 200 years old, stand approximately 35 meters tall. When you look up, you can see a stunning contrast of vibrant yellow leaves against the blue sky.' where id = '5Z8jEzdLfR4Jpc_F87fAj';
update content_bodies set title = '「元祖 肉の水炊き むかい」で熟成松阪牛の旨味・甘味・風味を堪能。「東海道亀山宿」生まれの伝統の味', description = '東海道の亀山宿で生まれた名物「肉の水炊き」は、昭和10年に下関から三重に移住した初代店主夫婦によって開発された伝統的な鍋料理です。当時、肉料理といえばすき焼きが主流だった中で、彼らは「てっちり」を参考にし、独自のスタイルを確立しました。熟成された松阪牛の旨味や甘味、風味を楽しむことができるこの料理は、亀山の地域文化を象徴する一品です。' where id = 'HPr7Q1xeEiQtbpAqyddlh';
update content_bodies set title = 'Experience the Flavor of Aged Matsusaka Beef at ''Ganso Niku no Mizutaki Mukai'' - A Traditional Taste Born in Tokaido Kameyama-juku (Kameyama City, Mie Prefecture)', description = 'The famous ''Niku no Mizutaki'' originated in Kameyama-juku along the Tokaido road. Established in 1935 by the first owner couple who moved from Shimonoseki to Mie, this traditional hot pot dish was developed as an alternative to the popular sukiyaki of the time, inspired by ''tecchiri''.' where id = 'ivd-hoVGCqYLyj8P-8w-_';
update content_bodies set title = '飛騨・美濃せせらぎ街道の紅葉', description = 'この動画では、郡上市八幡町から高山市清見町三日町を結ぶ「飛騨・美濃せせらぎ街道」の紅葉について紹介しています。現在、紅葉は見頃を迎えており、このルートの美しい景色を楽しむのに最適な時期です。' where id = 'ro9GygGouialXIBAwC_FA';
update content_bodies set title = 'The Autumn Foliage of the Hida-Mino Seseragi Road', description = 'This video introduces the autumn foliage along the Hida-Mino Seseragi Road, which connects Hachiman-cho in Gujo City to Mikata-cho in Takayama City. The vibrant colors of the leaves are currently at their peak, making it an ideal time to enjoy the scenic beauty of this route.' where id = 'dfKbeJiBxcSAYsmpVoACR';
update content_bodies set title = '熊野古道 馬越峠・天狗倉山～尾鷲セラピストガイド～【ドローン撮影】', description = '世界遺産である熊野古道の伊勢路の中でも、特に美しい石畳が人気の馬越峠と、そこから続く天狗倉山への登山を紹介します。尾鷲市には、登山初心者でも安心して楽しく歩けるようにガイドをしてくれる「尾鷲セラピスト」がいます。豊かな自然に囲まれた熊野古道で、心と身体を癒すヘルスツーリズムを体験することができます。' where id = 'fm9mrby3YOmtDCnZrMYgq';
update content_bodies set title = 'Kumano Kodo: Mount Makikoshi and Tengu Mountain - Guided by Owase Therapists - [Drone Footage]', description = 'The Kumano Kodo, a UNESCO World Heritage site, features the beautiful stone-paved paths of Mount Makikoshi and the ascent to Tengu Mountain. In Owase City, there are supportive ''Owase Therapists'' who guide even beginner hikers to walk safely, enjoyably, and healthily. This experience of health tourism allows visitors to heal their minds and bodies amidst the rich nature of the Kumano Kodo in Owase.' where id = 'J0y8oFhftViYfrDx-15Zl';
update content_bodies set title = 'クライミングジム キャニオン　岩場体験会【ドローン撮影】', description = '東京五輪の追加種目として注目を集めているクライミング。朝日町に位置するクライミングジム キャニオンでは、インドアのボルダリングだけでなく、岩場スポットでのアウトドア体験も提供しています。今回のイベントでは、参加者が人生初の岩場体験に挑戦する機会がありました。' where id = 'aiEhfmntmNfB-7I9OAQ_7';
update content_bodies set title = 'Canyon Climbing Gym: Rock Climbing Experience with Drone Photography', description = 'Climbing has gained attention recently as it was included as an additional event in the Tokyo Olympics. Canyon Climbing Gym, located in Asahi Town, offers not only indoor bouldering but also outdoor climbing experiences at rock spots. This event provided an opportunity for participants to try rock climbing for the first time in their lives.' where id = 'DCydtpMsf9LdWVBy8GOu4';
update content_bodies set title = '飛騨美濃伝統野菜「あきしまささげ」', description = 'この動画では、飛騨美濃の伝統野菜である「あきしまささげ」について紹介しています。' where id = 'zjrbrsWRBN4K-O1VWiqdB';
update content_bodies set title = 'Hida-Mino Traditional Vegetable ''Akishima Sasage''', description = 'This video introduces the Hida-Mino traditional vegetable ''Akishima Sasage''.' where id = 'UvLOvxBhm5EKfPTocYQr-';
update content_bodies set title = '北アルプス乗鞍岳の五色ケ原', description = 'この動画では、北アルプス乗鞍岳の北西山麓に広がる五色ケ原について紹介しています。五色ケ原は約3000haの広大な森林地帯で、手つかずの希少な自然が豊富に残る秘境です。秋が深まり、紅葉シーズンを迎えています。予約は10月31日まで受け付けています。' where id = 'Buer1JuwI61IfYweQS9se';
update content_bodies set title = 'Goshikigahara: A Hidden Gem in the Northern Alps', description = 'This video introduces Goshikigahara, a vast forest area of approximately 3000 hectares located at the northwestern foot of Mount Norikura in the Northern Alps. It is a hidden gem rich in untouched and rare nature, especially beautiful during the autumn foliage season. Reservations are accepted until October 31.' where id = 'lsOFdFkY6ygtDbM26YgWz';
update content_bodies set title = '飛騨の家具®フェスティバルが2024年10月19日(土)から23日(水)まで開催', description = 'この動画では、2024年10月19日(土)から23日(水)まで開催される飛騨の家具®フェスティバルについて紹介しています。各メーカーの展示に加え、トークイベントやワークショップも行われ、多くの方々で賑わうことが期待されています。' where id = '4u6GSGVaJo941R4CgGaNL';
update content_bodies set title = 'Hida Furniture® Festival to be Held from October 19 to 23, 2024', description = 'This video introduces the Hida Furniture® Festival, which will take place from October 19 (Saturday) to October 23 (Wednesday), 2024. The festival will feature exhibitions from various manufacturers, along with talk events and workshops, attracting a large number of visitors.' where id = '_5ib4su9frZqf6S7Yo6kJ';
update content_bodies set title = '乗鞍岳', description = '乗鞍岳は北アルプスの南端に位置し、23の峰、7つの湖、8つの平原からなる人気のスポットです。乗鞍スカイラインを利用することで、初心者でも気軽に高山ハイキングを楽しむことができます。この動画では、乗鞍岳の魅力を紹介しています。' where id = '-ZV9BYoyNhfbEefrdykG4';
update content_bodies set title = 'Norikura Mountain', description = 'Norikura Mountain is located at the southern end of the Northern Alps and is a popular spot featuring 23 peaks, 7 lakes, and 8 plains. It is easily accessible via the Norikura Skyline, making it suitable for beginners to enjoy high-altitude hiking.' where id = 'kzA4RTf7QHrOcFy8C4MUG';
update content_bodies set title = '山々に囲まれた高山の特産品「飛騨りんご」', description = 'この動画では、高山の特産品である「飛騨りんご」について紹介しています。飛騨りんごは、澄んだ空気と豊かな自然に育まれ、甘さと酸味のバランスが絶妙です。' where id = 'A3dILH-TNrog9B27-7Ae7';
update content_bodies set title = 'Hida Apples: A Specialty of Takayama Surrounded by Mountains', description = 'This video introduces Hida apples, a specialty product of Takayama, known for their perfect balance of sweetness and acidity, nurtured by the clear air and rich nature of the mountainous region.' where id = 'RfSVE1e-la_hHHGZrOwpE';
update content_bodies set title = '秋の高山祭「宵祭」', description = 'この動画は秋の飛騨高山高山祭「宵祭」について紹介しています。約100個の提灯をつけた屋台が夜の町並みを巡行する様子は、息をのむほど美しく幻想的です。屋台は「曳き別れ歌」を歌いながら帰っていき、祭りの雰囲気を一層盛り上げます。' where id = 'qib6QGyj7DRu-zHe1nJX1';
update content_bodies set title = 'Autumn Takayama Festival ''Yoimatsuri''', description = 'This video introduces the ''Yoimatsuri'' of the Takayama Festival in autumn. The festival features around 100 floats adorned with lanterns, creating a breathtaking and fantastical scene as they parade through the night streets. The floats return while singing the ''Hikiwakare Uta,'' a traditional song that adds to the festive atmosphere.' where id = 'WSdCFQTEAHl22dWlOgjYU';
update content_bodies set title = '秋の高山祭「御神幸(祭行列)」', description = 'この動画は秋の高山祭「御神幸(祭行列)」について紹介しています。伝統の衣装に身を包んだ数百人もの行列は、まるでタイムスリップしたかのような華やかな光景を作り出します。この祭りは、氏子の繁栄を願い、神様が一泊2日旅をすることを象徴しています。' where id = 'cfJNW6PVouoO822pN1lKh';
update content_bodies set title = 'Autumn Takayama Festival ''Mikoshi Procession''', description = 'This video introduces the Autumn Takayama Festival ''Mikoshi Procession'', featuring hundreds of participants dressed in traditional costumes, creating a vibrant scene reminiscent of a time slip. The procession symbolizes the deity''s overnight journey, wishing for the prosperity of the local community.' where id = 'XP2Cm82_T27tKEsY2TqL1';
update content_bodies set title = '秋の高山祭が無事に終了しました。', description = 'この祭りは9日に曇り、10日に見事な秋晴れの中で行われました。青空の下、屋台の曳き揃えやからくり奉納、御神幸（祭行列）が行われ、5年ぶりに宵祭も開催されました。多くの方々にお越しいただき、賑わいを見せました。' where id = '5thbVpNvQaoh38-56ZzV9';
update content_bodies set title = 'The Autumn Takayama Festival has successfully concluded.', description = 'The festival took place on the 9th under cloudy skies and on the 10th with beautiful autumn weather. The blue sky was expansive, featuring the parade of floats, the karakuri performance, and the procession of the deity. After five years, the evening festival was also held, attracting many visitors.' where id = 'HYUOEOmX29S1TvajjIAnX';
update content_bodies set title = '高山祭「飛騨人HIDABITO」受け継がれる伝統．技術．想い', description = 'この動画では、高山祭「飛騨人HIDABITO」について紹介しています。高山の人々の誇りと意気が感じられる内容です。' where id = 'MV3cUS5vnRugJktcS9qyE';
update content_bodies set title = 'Takayama Festival ''HIDABITO'': A Tradition, Skill, and Spirit Passed Down', description = 'This video introduces the Takayama Festival ''HIDABITO'', showcasing the unwavering pride of Takayama and the spirit of its people.' where id = 'SmtBZfwQBtG-_bwEbC6N0';
update content_bodies set title = '9月28日29日の土日に開催される「飛騨の工房めぐり」', description = 'この動画では、9月28日29日の土日に行われる「飛騨の工房めぐり」について紹介しています。このイベントでは、家具や造形作品を制作している「造形家　たしまねん」が参加し、木の曲線や木目が美しく、あたたかみのあるイスなどが展示販売されます。' where id = 'jscMcWQodGs-e0N0JvCtO';
update content_bodies set title = 'Hida Workshop Tour on September 28th and 29th', description = 'This video introduces the ''Hida Workshop Tour'' taking place on the weekend of September 28th and 29th. The event features ''Sculptor Tashimanen,'' who creates furniture and sculptural works. Visitors can see and purchase beautifully crafted chairs that showcase the warm curves and grains of wood.' where id = 'TnEp3IXsZ17M2D7DudmhH';
update content_bodies set title = '9月28日29日の土日に開催される「飛騨の工房めぐり」', description = 'この動画では、9月28日29日の土日に行われる「飛騨の工房めぐり」について紹介しています。特に、木材を高速で回転させて刃物で削る木工旋盤を使ってものづくりを行っている「osio craft」が取り上げられています。' where id = 'zV6wshIyf4LmFtMxfgORp';
update content_bodies set title = 'Hida Workshop Tour on September 28th and 29th', description = 'This video introduces the ''Hida Workshop Tour'' taking place on the weekend of September 28th and 29th. It features ''osio craft'', a workshop that utilizes a wood lathe, a machine that rapidly spins wood and shapes it with blades, to create various wooden products.' where id = 'QHXPlDydTudmMzsvmlUAO';
update content_bodies set title = '9月28日29日に開催される飛騨の工房めぐりの参加工房紹介「大家桐材店」', description = 'この動画では、9月28日と29日に開催される飛騨の工房めぐりに参加する「大家桐材店」について紹介しています。' where id = 'qmG-LoYrF2cIcfX5T3I2W';
update content_bodies set title = 'Introduction of Ooya Kiri Material Store Participating in Hida Workshop Tour on September 28-29', description = 'This video introduces Ooya Kiri Material Store, which is participating in the Hida workshop tour taking place on September 28 and 29.' where id = 'vi3HojbxAd8yS0Q8VBAYu';
update content_bodies set title = '9月21.22.23日、宮笠まち歩きイベントが開催されました。', description = 'この動画は、9月21日から23日にかけて開催された宮笠まち歩きイベントについて紹介しています。参加者は宮笠をかぶり、その技術や通気性などの魅力を知ることができました。撮影にご協力いただいた皆様に感謝申し上げます。' where id = 'qvUYyU6zBf16KdQWoslHY';
update content_bodies set title = 'Miyagasa Town Walking Event Held on September 21, 22, and 23', description = 'This video introduces the Miyagasa town walking event that took place on September 21, 22, and 23. Participants had the opportunity to wear Miyagasa hats and learn about their features, such as craftsmanship and breathability. We are grateful for the cooperation in filming.' where id = 'Ki3dS2EEOuOdBpCX0GtXi';
update content_bodies set title = '金森長近生誕500年記念を祝し豪華戦国イベントが開催されました。', description = 'この動画は金森長近生誕500年記念を祝う豪華な戦国イベントについて紹介しています。町並みを練り歩くパレードが行われ、飛騨高山まちの体験交流館広場では戦国甲冑劇が披露され、城山公園では火縄銃の演武が行われました。' where id = 'AqvNFqYksokZEgefsYfE3';
update content_bodies set title = 'Celebration of the 500th Anniversary of Kanamori Nagachika with a Grand Sengoku Event', description = 'This video introduces a grand Sengoku event held to celebrate the 500th anniversary of Kanamori Nagachika. The event featured a parade through the town, a Sengoku armor performance at the Hida Takayama Experience Exchange Center Square, and a demonstration of matchlock guns at Shiroyama Park.' where id = 'N9KwFjJbCZiNihCf9WHf1';
update content_bodies set title = '宮峠のトンネルを抜ければ、黄金に輝く一面の稲穂が広がります。飛騨高山収穫の秋到来です。', description = 'この動画では、宮峠のトンネルを抜けた先に広がる黄金に輝く稲穂の景色と、飛騨高山における収穫の秋の様子を紹介しています。' where id = 'N6fh9RDnIwOTicctyqCSL';
update content_bodies set title = 'Beyond the Miyatoge Tunnel, a Golden Sea of Rice Awaits: Autumn Harvest in Hida Takayama', description = 'This video showcases the breathtaking view of golden rice fields that spread out after passing through the Miyatoge Tunnel, highlighting the autumn harvest season in Hida Takayama.' where id = 'bn_dT-_sDv9yVofnSk0Ka';
update content_bodies set title = '飛騨高山まちの体験交流館での宮笠の無料貸出イベント', description = 'この動画では、9月21日、22日、23日に古い町並からすぐの場所にある「飛騨高山まちの体験交流館」の広場で開催される宮笠の無料貸出イベントについて紹介しています。' where id = 'IvApIryFKllWXK39WOz8x';
update content_bodies set title = 'Free Rental Event of Miyagasa at Hida Takayama Town Experience Exchange Center', description = 'This video introduces the free rental event of Miyagasa, which will be held on September 21, 22, and 23 at the plaza of the Hida Takayama Town Experience Exchange Center, located near the old town area.' where id = '4F2VocWTJ_AOkWQMOYC5t';
update content_bodies set title = '平湯峠と乗鞍岳畳平を結ぶ山岳観光道路「乗鞍スカイライン」', description = 'この動画では、平湯峠と乗鞍岳畳平を結ぶ山岳観光道路「乗鞍スカイライン」について紹介しています。乗鞍岳のバスターミナルは標高2702ｍに位置し、バスでアクセスできる日本一の高さを誇ります。また、自転車で登ることができる絶景ロードでもあります。' where id = 'yPgC1XLxk369g-fsjnusl';
update content_bodies set title = 'Norikura Skyline: A Mountain Tourist Road Connecting Hirayu Pass and Norikura-dake Tatamidaira', description = 'This video introduces the Norikura Skyline, a mountain tourist road that connects Hirayu Pass and Norikura-dake Tatamidaira. The bus terminal at Norikura-dake is located at an elevation of 2,702 meters, making it the highest point in Japan accessible by bus. It is also a scenic road that can be cycled, offering breathtaking views.' where id = 'p4Pnxeb50rgjXGMGH5PRL';
update content_bodies set title = '昼夜の寒暖差と乗鞍山麓の湧水を活用した野菜作りが盛んな丹生川町', description = 'この動画では、昼夜の寒暖差と乗鞍山麓の湧水を利用した野菜作りが盛んな丹生川町について紹介しています。特に人気の「宿儺かぼちゃ」についても触れ、そのほくほくとした食感や濃厚な甘み、調理しやすい薄皮の特徴が強調されています。' where id = 'CSNxRNROluz-mgIaXhJ0l';
update content_bodies set title = 'Vegetable Cultivation Utilizing Temperature Differences and Spring Water in Niu River Town', description = 'This video introduces Niu River Town, known for its active vegetable cultivation that takes advantage of the temperature differences between day and night and the spring water from the Norikura Mountains. It particularly highlights the popular ''Sukuna Pumpkin,'' which is characterized by its fluffy texture, rich sweetness, and thin skin, making it easy to cook.' where id = 'mOK2Mtov_DNzkMCd_traR';
update content_bodies set title = '北アルプスの南端・乗鞍岳に抱かれる丹生川町', description = 'この動画では、北アルプスの南端に位置する乗鞍岳に抱かれた丹生川町を紹介しています。ここでは、日本の原風景が広がり、澄んだ空気の中で壮大な風景を楽しみながら自転車を楽しむことができ、心身ともにリフレッシュできるエリアです。' where id = 'b37jNmY2jFTxl8ErnHbUV';
update content_bodies set title = 'Niyukawa Town Embraced by Mount Norikura at the Southern End of the Northern Alps', description = 'This video introduces Niyukawa Town, located at the southern end of Mount Norikura in the Northern Alps. The area offers a glimpse of Japan''s original landscapes, where visitors can enjoy cycling amidst clear air and magnificent scenery, providing a refreshing experience for both body and mind.' where id = 'scjEoMKdXcIDBN4Xv6WXN';
update content_bodies set title = '幻のとうもろこし「タカネコーン」', description = 'この動画では、幻のとうもろこし「タカネコーン」について紹介しています。タカネコーンは、標高1,300m前後の地域で栽培されたトウモロコシだけを指し、メロン並みの糖度が特徴です。' where id = 'QhsZKOGcXm4rQUNALv-ZW';
update content_bodies set title = 'The Legendary Corn ''Takane Corn''', description = 'This video introduces ''Takane Corn'', a type of corn known as the legendary corn. It is cultivated in regions at an altitude of around 1,300 meters and is characterized by its sugar content comparable to that of melons.' where id = 'SMv7dDtA_YwI2lHjhZqk_';
update content_bodies set title = '青い川のような秘密の日本の温泉に宿泊♨️ | Adachiya Ryokan 福島', description = 'この動画では、福島にある隠れた名所、Adachiya Ryokanでの宿泊体験が紹介されています。宿泊予約の方法や、さまざまな予約プラットフォームへのリンクが提供されています。動画では、ラウンジ、チェックインプロセス、部屋のツアー、公共浴場やプライベート露天風呂などの入浴オプションが詳しく紹介されています。また、夕食や朝食の内容も強調されています。福島駅からのアクセス方法も示されており、宿泊料金や食事を含むプランについても言及されています。TABBIAのオンラインストアを訪れたり、Instagramをフォローしたりすることが推奨されています。' where id = 'RmCnd8L-6ZwzgvRaQ_SIm';
update content_bodies set title = 'Staying at a Secret Japanese Hot Spring Like a Blue River♨️ | Adachiya Ryokan Fukushima', description = 'This video showcases a stay at Adachiya Ryokan, a hidden gem in Fukushima known for its beautiful hot springs. Viewers can find information on how to book a stay, including links to various booking platforms. The video features a detailed tour of the ryokan, including the lounge, check-in process, room tour, and various bathing options such as public baths and private open-air baths. It also highlights the dining experience, showcasing dinner and breakfast offerings. The ryokan is accessible from Fukushima Station, with travel options provided. Prices for a stay with meals are mentioned, and viewers are encouraged to explore the TABBIA online store and follow on Instagram for more updates.' where id = 'dtBUkzyj-NsVkzU8_HPeE';
update content_bodies set title = '寒冷な気候と昼夜の寒暖差が大きい飛騨エリアで栽培されるため、甘みが強く、濃厚な味わいが特徴の「飛騨ほうれん草」', description = 'この動画では、寒冷な気候と昼夜の寒暖差が大きい飛騨エリアで栽培される「飛騨ほうれん草」について紹介しています。このほうれん草は、甘みが強く、濃厚な味わいが特徴であり、飛騨エリアは日本でも有数のほうれん草の産地です。' where id = '4FXRYcUZVIoa6ruxGkjrN';
update content_bodies set title = 'Hida Spinach: A Sweet and Rich Flavor Grown in a Cold Climate', description = 'This video introduces ''Hida Spinach,'' which is characterized by its strong sweetness and rich flavor due to being cultivated in the Hida area, known for its cold climate and significant temperature differences between day and night. The Hida region is one of Japan''s leading spinach-producing areas.' where id = 'EVnJIAP9DdY3Oob6l_D0U';
update content_bodies set title = '櫻山八幡宮で開催中の桜山風鈴まつり', description = 'この動画では、秋の高山祭の例祭の場所として知られる「櫻山八幡宮」で行われている「桜山風鈴まつり」について紹介しています。絵馬殿には約2,000個の風鈴が飾られ、手水舎には生花が浮かび、涼しげな雰囲気が漂っています。風鈴の音色が響き渡り、訪れる人々に涼を感じさせます。' where id = 'i6IQskPXCAwj6GYZEi4pV';
update content_bodies set title = 'Sakurayama Furin Festival at Sakurayama Hachiman Shrine', description = 'This video introduces the Sakurayama Furin Festival currently being held at Sakurayama Hachiman Shrine, a famous site for the Takayama Autumn Festival. Approximately 2,000 wind chimes are displayed in the Ema Hall, and fresh flowers float in the water basin, creating a refreshing atmosphere filled with soothing sounds.' where id = 'OWjJrlb2fh-RlhOPMt3BN';
update content_bodies set title = '早朝7時から営業している「ダルマベーカリー」', description = 'この動画では、早朝7時から営業している「ダルマベーカリー」について紹介しています。このパン屋は、子供から大人まで楽しめる幅広い商品ラインナップが人気で、80〜90種類のパンが並びます。期間限定のパンもあり、どれにしようか迷ってしまうほどの魅力があります。' where id = 'pfL8jhxpAwegaQJTGA20G';
update content_bodies set title = 'Daruma Bakery Opens at 7 AM: A Popular Bakery for All Ages', description = 'This video introduces Daruma Bakery, which opens at 7 AM. The bakery is known for its wide range of products that appeal to both children and adults. With 80 to 90 types of bread available, including limited-time offerings, customers may find it difficult to choose from the delicious selection.' where id = 'YWBtwI3ohiMqyURrmGbpg';
update content_bodies set title = '飛騨地方の七夕祭り', description = 'この動画では、飛騨地方の七夕祭りについて紹介しています。飛騨地方では、旧暦に基づいて行事が行われるため、七夕祭りは毎年8月7日に祝われます。この時期、古い町並みの軒先には笹の葉が飾られ、笹と七夕飾りが揺れる様子が涼しげな雰囲気を醸し出します。' where id = 'LFH42y5QsLMXJHqroNSBh';
update content_bodies set title = 'Tanabata Festival in Hida Region', description = 'This video introduces the Tanabata Festival in the Hida region, which is celebrated on August 7th according to the lunar calendar. During this time, bamboo leaves are decorated along the eaves of the old town, creating a refreshing atmosphere with the swaying bamboo and Tanabata ornaments.' where id = 'gUb_0rcRcWlh8sYz-SER5';
update content_bodies set title = '～飛騨高山夏の風物詩～打ち上げる者、観る者の厄払いを願い、毎年8月9日に開催される「飛騨高山手筒花火打上げ」', description = 'この動画は、毎年8月9日に行われる飛騨高山手筒花火打上げについて紹介しています。このイベントは、参加者と観客の厄払いを願い、竹筒に仕込んだ花火を手で持って打ち上げる勇壮な花火です。火の粉を浴びながら行われるこの伝統的な行事は、夏の風物詩として多くの人々に親しまれています。' where id = '_HubrxuXWpDuq_mtlBcMW';
update content_bodies set title = 'Hida Takayama Summer Tradition - Handheld Fireworks Display', description = 'The Hida Takayama Handheld Fireworks Display is held annually on August 9th, aiming to ward off misfortune for both the participants and spectators. This spectacular event features fireworks launched from bamboo tubes held by hand, creating a thrilling experience as participants are showered with sparks.' where id = 'CPD97wVFQgt_A0HySlv0O';
update content_bodies set title = '久々野町にある「下本農園」でのトマト狩り体験', description = 'この動画では、久々野町に位置する「下本農園」でのトマト狩り体験を紹介しています。農園では、甘さを抑えつつ酸味が効いた水々しいトマトを育てており、糖度を上げることで水分量が減少し、水々しさが失われることを防いでいます。絶妙なバランスが保たれたトマトを楽しむことができます。' where id = 'rgT7mKpmeBQoprHFmls-d';
update content_bodies set title = 'Tomato Picking Experience at Shimamoto Farm in Kuzuyano Town', description = 'This video introduces the tomato picking experience at Shimamoto Farm located in Kuzuyano Town. The farm cultivates tomatoes that maintain a delicate balance between sweetness and acidity, ensuring a juicy texture without excessive sweetness. This is achieved by increasing the sugar content while reducing the water content.' where id = 'CPfSMgnfEQCxM-2bQ3W1X';
update content_bodies set title = '高山市江名子町で飛騨メロンを栽培している「林農園」', description = 'この動画では、高山市江名子町にある「林農園」で栽培されている飛騨メロンについて紹介しています。飛騨高山の寒暖差のある気候が、コクのある上品な甘さとみずみずしい果肉を持つメロンの生産を可能にしています。' where id = 'HUbDXuLuIrFiZ4GTYWEPO';
update content_bodies set title = 'Hayashi Farm Cultivating Hida Melons in Enaiko Town, Takayama', description = 'This video introduces Hayashi Farm, which cultivates Hida melons in Enaiko Town, Takayama. The unique climate of Takayama, with its significant temperature differences, allows for the production of melons that are characterized by their rich, elegant sweetness and juicy flesh.' where id = '2aLvBOXcBWCaR2Wbak_yw';
update content_bodies set title = '飛騨高山 里山サイクリング', description = '日本一面積が広い高山市は、山々に囲まれ、90％以上が森林で占められた自然豊かなスポットです。美しい自然、歴史、文化、温泉、グルメなど、多彩な魅力が詰まった飛騨高山では、懐かしく心温まる日本の原風景が広がります。飛騨高山の大自然を満喫するためのオススメアクティビティは「e-bike（イーバイク）」です。澄んだ空気と北アルプスの壮大な風景の中を駆け抜ける爽快感は格別です。イーバイクは電動アシスト機能があり、体力に自信がない方や自転車に慣れていない方でも気軽に楽しめます。坂道も軽々と登れるため、高山の起伏の多い地形でも安心です。イーバイクで飛騨高山を散策してみませんか？レンタル詳細は公式サイトをご確認ください。' where id = 'dt1Ob1HHn08Weu_CmhgeE';
update content_bodies set title = 'Hida Takayama Satoyama Cycling', description = 'Hida Takayama, the largest city in Japan by area, is surrounded by mountains and over 90% of its land is covered by forests, making it a nature-rich destination. This area is filled with diverse attractions, including beautiful nature, history, culture, hot springs, and gourmet food, showcasing a nostalgic and heartwarming view of Japan''s original landscape. A recommended activity to fully enjoy the great outdoors of Hida Takayama is e-biking. Riding through the clear air and the magnificent scenery of the Northern Alps (Hida Mountains) is refreshing! E-bikes come with an electric assist feature, making it easy for those who may not be confident in their physical fitness or are not used to cycling to enjoy biking. They can easily tackle hills, ensuring a comfortable ride even in the hilly terrain of Takayama. Why not explore Hida Takayama on an e-bike? For rental details, please check the official website.' where id = '35uXmBJAbx8C0bFH2E__C';
update content_bodies set title = '今から約330年前に一之宮町に伝えられた「宮笠」', description = 'この動画では、約330年前に一之宮町に伝えられた「宮笠」について紹介しています。代々宮村で暮らす問坂義一さんと和彦さん親子が、この伝統技術を守り続けています。' where id = 'GP79Fjt982GRxgWFt6GXD';
update content_bodies set title = 'The ''Miyagasa'' Passed Down in Ichinomiya Town for About 330 Years', description = 'This video introduces the ''Miyagasa,'' a traditional craft that has been passed down in Ichinomiya Town for approximately 330 years. The technique is preserved by Yoshikazu and Kazuhiko Monzaka, a father and son who have lived in the Miyamura area for generations.' where id = 'Y3jrKEfZiN662-mv5VS80';
update content_bodies set title = '梅雨があけて、飛騨高山も夏本番！', description = 'この動画では、梅雨があけた後の飛騨高山の夏の様子を紹介しています。真っ青な空と白い雲が広がり、夏にしか見ることができない絶景が楽しめることが伝えられています。' where id = 'Ojw84yd--e4B216OBv5b9';
update content_bodies set title = 'Summer Begins in Takayama After the Rainy Season!', description = 'This video introduces the summer season in Takayama, highlighting the clear blue skies and white clouds that create breathtaking views unique to this time of year.' where id = '5VxiG51vGG45CYW9RV0v2';
update content_bodies set title = '高山市久々野町の小屋名地区に伝わる竹細工のざる「小屋名しょうけ」', description = 'この動画では、高山市久々野町の小屋名地区に伝わる竹細工のざる「小屋名しょうけ」について紹介しています。スズタケを縦横に丹念に編み込んだ美しい編み目が特徴で、精巧なつくりが魅力です。' where id = 'sIlJcHq_BbOKafxtDnNYb';
update content_bodies set title = 'Koyana Shouke: Bamboo Craft from Koyana District in Hida Takayama', description = 'This video introduces Koyana Shouke, a bamboo basket crafted in the Koyana district of Hida Takayama. The basket features intricate weaving of suzutake, showcasing a beautiful and tightly woven design.' where id = 'jO9ndKtu3361DZKgqRzWy';
update content_bodies set title = '日本で一番大きな市の高山市は、90％以上が森林に占められている自然豊かなエリア', description = 'この動画は、日本で一番大きな市である高山市について紹介しています。高山市は90％以上が森林に覆われており、彩り豊かな滝や森が点在しています。川のせせらぎや森の匂い、木々の感触を通じて、心を開放するリフレッシュ体験ができる場所です。' where id = 'FdpnLJ4u-LD6BxTpNK65a';
update content_bodies set title = 'Takayama City: Japan''s Largest City Surrounded by Nature', description = 'This video introduces Takayama City, the largest city in Japan, which is over 90% forested. The area is rich in nature, featuring vibrant waterfalls and lush forests. Visitors can enjoy a refreshing experience with the sounds of flowing rivers, the scent of the woods, and the feel of the trees.' where id = 'vtC3HHOA1YPAJJg9CORON';
update content_bodies set title = '水温が年間14℃前後に保たれる清流でのみ生息する貴重な植物「梅花藻(バイカモ)」', description = 'この動画では、水温が年間14℃前後に保たれる清流でのみ生息する貴重な植物「梅花藻(バイカモ)」について紹介しています。飛騨一宮水無神社前の常泉寺川の下流にかかる橋から約500ｍにわたって、白く小さな花を見ることができます。' where id = 'g8oBfAhT5j5ten1EhwFeC';
update content_bodies set title = 'A Rare Plant ''Baikamo'' That Lives Only in Clear Streams with a Water Temperature of Around 14°C', description = 'This video introduces ''Baikamo,'' a rare plant that thrives only in clear streams where the water temperature is maintained around 14°C. You can see small white flowers of Baikamo along a 500-meter stretch from the bridge over the Jōsenji River, downstream from the Minashi Shrine in Hida Ichinomiya.' where id = 'FZDH_4JqRUhR_XMBqlyP-';
update content_bodies set title = '丹生川町にある千光寺でアジサイが見頃を迎えています', description = 'この動画では、丹生川町に位置する千光寺でのアジサイの見頃を紹介しています。参道沿いには約1000株のアジサイが咲き誇り、華やかな雰囲気を醸し出しています。撮影は7月5日に行われました。' where id = '_kFfx5XmOD7jR0bm6MGom';
update content_bodies set title = 'Hydrangeas in Full Bloom at Senkoji Temple in Niyukawa Town', description = 'This video introduces the hydrangeas in full bloom at Senkoji Temple located in Niyukawa Town. Along the approach to the temple, approximately 1,000 hydrangea plants are in full bloom, creating a vibrant atmosphere. The footage was captured on July 5th.' where id = 'jkHWfcxWgF5-7LpL915Po';
update content_bodies set title = 'また訪れたくなる神秘の森「五色ヶ原の森」', description = 'この動画では、神秘的な「五色ヶ原の森」について紹介しています。滝の音や森林の香り、澄んだ空気が広がるこの場所では、自然の中でしか体感できない非日常的な体験が待っています。五色ヶ原の森は、訪れるたびに新たな感動を与えてくれる場所です。' where id = 'X1gVYT84Gb3plJXBv_Mpb';
update content_bodies set title = 'The Enigmatic Forest of Goshikigahara: A Place You Want to Visit Again', description = 'This video introduces the enchanting Goshikigahara forest, where the sounds of waterfalls, the scent of the forest, and the clear air create a unique experience in nature. It offers an extraordinary escape that can only be felt in Goshikigahara.' where id = 'MnR60QMPTxSTs7Edozpar';
update content_bodies set title = '飛騨高山の走りたい道「丹生川の田園風景」', description = 'この動画では、飛騨高山にある「丹生川の田園風景」という走りたい道を紹介しています。山々に囲まれたこの地域は、一面に広がる田んぼと青空が特徴で、走り抜けるとどこか懐かしく爽快な景色が広がります。' where id = 'gHt4WNMns2fZsHUYzCbJ-';
update content_bodies set title = 'Scenic Route in Hida Takayama: Niyugawa''s Rural Landscape', description = 'This video introduces the scenic route in Hida Takayama known as ''Niyugawa''s Rural Landscape.'' Surrounded by mountains, the area features expansive rice fields and a clear blue sky, creating a nostalgic and refreshing view as one travels through.' where id = 'NKEINj5sgNSY-QPJ4WWC7';
update content_bodies set title = '日本酒の聖地「飛騨高山」', description = 'この動画は日本酒の聖地「飛騨高山」について紹介しています。「飛騨高山・酒蔵のん兵衛まつり」では、スタンプラリーを行いながら6つの酒蔵で2種類の試飲が楽しめ、記念杯や特製エコバッグなど特典が満載の日本酒イベントです。' where id = 'ZzSD-E_syIH62BbfHm7Ju';